/* 03-store.js */
(function defineStore(root) {
  'use strict';

  const { clone } = root.YC.utils;
  const STORAGE_KEY = 'yen-center-lms-fe-state-v4';
  const V3_STORAGE_KEY = 'yen-center-lms-fe-state-v3';
  const LEGACY_STORAGE_KEY = 'yen-center-lms-fe-state-v2';
  const SESSION_KEY = 'yen-center-lms-fe-session-v4';
  const CMS_COLLECTIONS = Object.freeze(['siteSettings', 'navigationGroups', 'navigationItems', 'heroBanners', 'publicProgramProfiles', 'publicBranchProfiles', 'publicTeacherProfiles', 'articles', 'articleCategories', 'publicEvents', 'staticPages', 'contactChannels']);

  function hydrateV4(previous, clock = () => new Date()) {
    const baseline = root.YC.seed.createSeed(clock);
    const next = clone(previous);
    CMS_COLLECTIONS.forEach((key) => {
      if (!Array.isArray(next[key])) next[key] = clone(baseline[key]);
    });
    return next;
  }

  function migrateV3(previous, clock = () => new Date()) {
    const baseline = root.YC.seed.createSeed(clock);
    const next = clone(previous);
    next.schemaVersion = 4;
    next.permissionDefinitions = baseline.permissionDefinitions;
    next.rolePermissions = baseline.rolePermissions;
    next.userPermissionOverrides = Array.isArray(next.userPermissionOverrides) ? next.userPermissionOverrides : [];
    next.changeRequests = Array.isArray(next.changeRequests) ? next.changeRequests : [];
    next.remedialCases = Array.isArray(next.remedialCases) ? next.remedialCases : [];
    next.settings = { ...baseline.settings, ...(next.settings || {}) };
    next.organizations = (next.organizations || baseline.organizations).map((item) => ({ version: 1, ...item }));
    next.courses = (next.courses || []).map((item) => ({ version: 1, ...item }));
    next.courseVersions = (next.courseVersions || []).map((item) => ({ recordVersion: 1, ...item }));
    next.classes = (next.classes || []).map((item) => ({ version: 1, ...item }));
    next.sessions = (next.sessions || []).map((item) => ({ version: 1, ...item }));
    (next.remedialAssignments || []).forEach((assignment, index) => {
      if (assignment.remedialCaseId) return;
      const attendance = (next.attendanceRecords || []).find((item) => item.sessionId === assignment.sessionId && item.learnerId === assignment.learnerId) || null;
      const session = (next.sessions || []).find((item) => item.id === assignment.sessionId) || null;
      const cohort = (next.classes || []).find((item) => item.id === session?.classId) || null;
      const courseVersion = (next.courseVersions || []).find((item) => item.id === cohort?.courseVersionId) || null;
      let remedialCase = next.remedialCases.find((item) => attendance && item.sourceAttendanceId === attendance.id);
      if (!remedialCase) {
        remedialCase = {
          id: `remedial-case-migrated-${index + 1}`, learnerId: assignment.learnerId,
          sourceAttendanceId: attendance?.id || null, sourceSessionId: assignment.sessionId,
          sourceClassId: cohort?.id || null, sourceCourseVersionId: courseVersion?.id || null,
          sourceCourseId: courseVersion?.courseId || null, sourceLessonTemplateId: assignment.lessonTemplateId || session?.lessonTemplateId || null,
          policySnapshot: clone(courseVersion?.remedialPolicy || { triggerStatuses: ['ABSENT'], requiredModes: ['ONLINE'], deadlineDays: next.settings?.remedialDeadlineDays || baseline.settings.remedialDeadlineDays, passingScore: next.settings?.defaultPassingScore || baseline.settings.defaultPassingScore, minimumVideoProgress: next.settings?.minimumVideoProgress || baseline.settings.minimumVideoProgress }),
          requiredModes: ['ONLINE'], openedAt: assignment.assignedAt || next.seededAt, openedBy: assignment.assignedBy || 'migration-v3', resolution: null,
          reconciliationHistory: [{ fromStatus: null, toStatus: attendance?.status || 'ABSENT', occurredAt: next.seededAt, actorId: 'migration-v3' }],
        };
        next.remedialCases.push(remedialCase);
      }
      assignment.remedialCaseId = remedialCase.id;
      (next.makeUpBookings || []).filter((item) => item.sourceAttendanceId === remedialCase.sourceAttendanceId).forEach((item) => { item.remedialCaseId = remedialCase.id; });
    });
    next.migrationNotice = { code: 'V3_MIGRATED', message: 'Đã nâng dữ liệu v3 lên schema v4 và giữ nguyên hành trình học tập.' };
    return next;
  }

  function browserStorage() {
    try {
      return root.localStorage;
    } catch (_error) {
      return null;
    }
  }

  function create({ storage = browserStorage(), clock = () => new Date() } = {}) {
    let current;

    function persist() {
      if (storage) storage.setItem(STORAGE_KEY, JSON.stringify(current));
    }

    function fresh(migrationNotice = null) {
      const seeded = root.YC.seed.createSeed(clock);
      seeded.migrationNotice = migrationNotice;
      return seeded;
    }

    function load() {
      if (storage) {
        try {
          const rawV4 = storage.getItem(STORAGE_KEY);
          if (rawV4) {
            const parsed = JSON.parse(rawV4);
            if (parsed.schemaVersion === 4) return hydrateV4(parsed, clock);
          }
          const rawV3 = storage.getItem(V3_STORAGE_KEY);
          if (rawV3) {
            const parsed = JSON.parse(rawV3);
            if (parsed.schemaVersion === 3) return migrateV3(parsed, clock);
          }
          if (storage.getItem(LEGACY_STORAGE_KEY)) {
            return fresh({ code: 'V2_RESET_REQUIRED', message: 'Dữ liệu v2 đã được thay bằng seed v3 để bảo toàn quan hệ nghiệp vụ.' });
          }
        } catch (_error) {
          return fresh({ code: 'CORRUPT_STATE_RESET', message: 'Dữ liệu local không hợp lệ đã được reset an toàn.' });
        }
      }
      return fresh();
    }

    current = load();
    persist();

    return Object.freeze({
      getState() { return current; },
      replace(next) {
        if (!next || next.schemaVersion !== 4) throw new Error('StateV4 required');
        current = clone(next);
        persist();
        return current;
      },
      reset() {
        current = fresh();
        persist();
        return current;
      },
      transact(mutator) {
        const draft = clone(current);
        draft.currentAt = new Date(clock()).toISOString();
        const result = mutator(draft);
        current = draft;
        persist();
        return result;
      },
      storage,
      clock,
    });
  }

  root.YC.define('store', Object.freeze({ create, hydrateV4, LEGACY_STORAGE_KEY, SESSION_KEY, STORAGE_KEY, V3_STORAGE_KEY, migrateV3 }));
})(globalThis);

/* 04-policy.js */
(function definePolicy(root) {
  'use strict';

  const legacyAliases = root.YC.permissions.legacyAliases;
  const roleCapabilities = Object.freeze(Object.fromEntries(
    Object.entries(root.YC.permissions.roleDefaults.reduce((result, grant) => {
      if (!result[grant.role]) result[grant.role] = [];
      result[grant.role].push(grant.permissionId);
      return result;
    }, {})).map(([role, permissions]) => [role, Object.freeze(permissions)])
  ));

  function currentTimestamp(state) {
    const value = state.currentAt || state.seededAt || new Date().toISOString();
    return new Date(value).getTime();
  }

  function isEffective(record, state) {
    const moment = currentTimestamp(state);
    if (record.effectiveFrom && new Date(record.effectiveFrom).getTime() > moment) return false;
    if (record.effectiveTo && new Date(record.effectiveTo).getTime() <= moment) return false;
    return record.status !== 'INACTIVE' && record.status !== 'REVOKED';
  }

  function classIdFor(resource, state) {
    if (resource.classId) return resource.classId;
    if (resource.sessionId) return state.sessions.find((item) => item.id === resource.sessionId)?.classId || null;
    if (resource.learnerId) return state.learners.find((item) => item.id === resource.learnerId)?.classId || null;
    return null;
  }

  function branchIdFor(resource, state) {
    if (resource.branchId) return resource.branchId;
    const classId = classIdFor(resource, state);
    return classId ? state.classes.find((item) => item.id === classId)?.branchId || null : null;
  }

  function assignmentAllows(actor, resource, state) {
    const profile = state.teacherProfiles.find((item) => item.userId === actor.id && item.status === 'ACTIVE');
    const classId = classIdFor(resource, state);
    if (!profile || !classId) return false;
    const moment = currentTimestamp(state);
    return state.teacherAssignments.some((item) => item.teacherProfileId === profile.id
      && item.classId === classId
      && ['ACCEPTED', 'ACTIVE'].includes(item.status)
      && new Date(item.startsAt).getTime() <= moment
      && new Date(item.endsAt).getTime() >= moment);
  }

  function listed(scopeIds, id) {
    return Array.isArray(scopeIds) && scopeIds.length > 0 && Boolean(id) && scopeIds.includes(id);
  }

  function scopeAllows(actor, grant, resource, state) {
    const scope = grant.scopeType || 'ORGANIZATION';
    const scopeIds = grant.scopeIds || [];
    if (scope === 'ORGANIZATION') {
      return !resource.organizationId || state.organizations.some((item) => item.id === resource.organizationId);
    }
    if (scope === 'BRANCH') {
      const branchId = branchIdFor(resource, state);
      if (!branchId || !(actor.branchIds || []).includes(branchId)) return false;
      return scopeIds.length === 0 || scopeIds.includes(branchId);
    }
    if (scope === 'ASSIGNED_CLASS') return assignmentAllows(actor, resource, state);
    if (scope === 'CLASS') return listed(scopeIds, classIdFor(resource, state));
    if (scope === 'SESSION') return listed(scopeIds, resource.sessionId || null);
    if (scope === 'OWN_LEARNER' || scope === 'LINKED_LEARNER') {
      return Boolean(resource.learnerId) && (actor.linkedLearnerIds || []).includes(resource.learnerId);
    }
    return false;
  }

  function result(allowed, permissionId, source, scope = null, recordId = null) {
    return Object.freeze({ allowed, source, permissionId, scope, recordId });
  }

  function explain(actor, requestedId, resource = {}, state) {
    const permissionId = legacyAliases[requestedId] || requestedId;
    if (!actor || actor.status !== 'ACTIVE') return result(false, permissionId, 'INACTIVE_USER');
    if (!state || !Array.isArray(state.rolePermissions) || !Array.isArray(state.userPermissionOverrides)) {
      return result(false, permissionId, 'POLICY_STATE_MISSING');
    }

    const overrides = state.userPermissionOverrides.filter((item) => item.userId === actor.id
      && item.permissionId === permissionId
      && isEffective(item, state)
      && scopeAllows(actor, item, resource, state));
    const userDeny = overrides.find((item) => item.effect === 'DENY');
    if (userDeny) return result(false, permissionId, 'USER_DENY', userDeny.scopeType, userDeny.id);
    const userAllow = overrides.find((item) => item.effect === 'ALLOW');
    if (userAllow) return result(true, permissionId, 'USER_ALLOW', userAllow.scopeType, userAllow.id);

    const roleGrants = state.rolePermissions.filter((item) => item.role === actor.role
      && item.permissionId === permissionId
      && isEffective(item, state)
      && scopeAllows(actor, item, resource, state));
    const roleDeny = roleGrants.find((item) => item.effect === 'DENY');
    if (roleDeny) return result(false, permissionId, 'ROLE_DENY', roleDeny.scopeType, roleDeny.id);
    const roleAllow = roleGrants.find((item) => item.effect === 'ALLOW');
    if (roleAllow) return result(true, permissionId, 'ROLE', roleAllow.scopeType, roleAllow.id);
    return result(false, permissionId, 'DEFAULT_DENY');
  }

  function can(actor, permissionId, resource = {}, state) {
    return explain(actor, permissionId, resource, state).allowed;
  }

  function visibleFeedback(actor, records, state) {
    if (!actor) return [];
    if (['ADMIN', 'ACADEMIC_MANAGER'].includes(actor.role)) return records.slice();
    if (actor.role === 'PARENT') {
      return records.filter((item) => (actor.linkedLearnerIds || []).includes(item.learnerId)
        && ['PARENT', 'LEARNER_PARENT'].includes(item.visibility));
    }
    if (actor.role === 'STUDENT') {
      return records.filter((item) => (actor.linkedLearnerIds || []).includes(item.learnerId)
        && ['LEARNER', 'LEARNER_PARENT'].includes(item.visibility));
    }
    if (actor.role === 'TEACHER') {
      return records.filter((item) => item.visibility !== 'RESTRICTED'
        && can(actor, 'learner.view', { learnerId: item.learnerId }, state));
    }
    return [];
  }

  root.YC.define('policy', Object.freeze({ assignmentAllows, can, explain, roleCapabilities, visibleFeedback }));
})(globalThis);

/* 05-approval.js */
(function defineApproval(root) {
  'use strict';

  const { clone, uid } = root.YC.utils;

  const REQUEST_TRANSITIONS = Object.freeze({
    DRAFT: Object.freeze(['SUBMITTED', 'WITHDRAWN']),
    SUBMITTED: Object.freeze(['IN_REVIEW', 'APPROVED', 'CHANGES_REQUESTED', 'REJECTED', 'CONFLICTED', 'WITHDRAWN']),
    IN_REVIEW: Object.freeze(['APPROVED', 'CHANGES_REQUESTED', 'REJECTED', 'CONFLICTED']),
    CHANGES_REQUESTED: Object.freeze(['SUBMITTED', 'WITHDRAWN']),
    APPROVED: Object.freeze([]),
    REJECTED: Object.freeze([]),
    CONFLICTED: Object.freeze([]),
    WITHDRAWN: Object.freeze([]),
  });

  const RESOURCES = Object.freeze({
    COURSE: Object.freeze({ collection: 'courses', versionKey: 'version' }),
    COURSE_VERSION: Object.freeze({ collection: 'courseVersions', versionKey: 'recordVersion' }),
    CLASS: Object.freeze({ collection: 'classes', versionKey: 'version' }),
    SESSION: Object.freeze({ collection: 'sessions', versionKey: 'version' }),
  });

  const PERMISSIONS = Object.freeze({
    'COURSE.CREATE': 'course.request_create',
    'COURSE.UPDATE': 'course.request_update',
    'COURSE.ARCHIVE': 'course.request_archive',
    'COURSE_VERSION.CREATE': 'course.request_update',
    'COURSE_VERSION.UPDATE': 'course.request_update',
    'COURSE_VERSION.PUBLISH': 'course.publish',
    'CLASS.CREATE': 'class.request_create',
    'CLASS.UPDATE': 'class.request_update',
    'CLASS.ARCHIVE': 'class.request_archive',
    'SESSION.CREATE': 'session.request_create',
    'SESSION.UPDATE': 'session.request_reschedule',
    'SESSION.RESCHEDULE': 'session.request_reschedule',
    'SESSION.CANCEL': 'session.request_cancel',
  });

  function approvalError(code, message) {
    const error = new Error(message);
    error.code = code;
    return error;
  }

  function definition(resourceType) {
    const result = RESOURCES[resourceType];
    if (!result) throw approvalError('UNSUPPORTED_RESOURCE', 'Loại dữ liệu chưa được hỗ trợ trong luồng phê duyệt.');
    return result;
  }

  function permissionFor(resourceType, operation) {
    const permissionId = PERMISSIONS[`${resourceType}.${operation}`];
    if (!permissionId) throw approvalError('UNSUPPORTED_OPERATION', 'Thao tác chưa được hỗ trợ trong luồng phê duyệt.');
    return permissionId;
  }

  function diff(before, after) {
    const left = before || {};
    const right = after || {};
    return [...new Set([...Object.keys(left), ...Object.keys(right)])].sort().filter((field) => (
      JSON.stringify(left[field]) !== JSON.stringify(right[field])
    )).map((field) => ({ field, before: clone(left[field] ?? null), after: clone(right[field] ?? null) }));
  }

  function validateSession(snapshot, state, operation, excludeSessionId = null) {
    if (operation === 'CREATE') {
      if (!state.classes.some((item) => item.id === snapshot.classId)) throw approvalError('CLASS_NOT_FOUND', 'Không tìm thấy lớp của buổi học.');
      if (!state.lessonTemplates.some((item) => item.id === snapshot.lessonTemplateId)) throw approvalError('LESSON_NOT_FOUND', 'Không tìm thấy bài học mẫu.');
    }
    if (['CREATE', 'RESCHEDULE', 'UPDATE'].includes(operation)) {
      const startsAt = new Date(snapshot.startsAt).getTime();
      const endsAt = new Date(snapshot.endsAt).getTime();
      if (!Number.isFinite(startsAt) || !Number.isFinite(endsAt) || endsAt <= startsAt) {
        throw approvalError('INVALID_SESSION_TIME', 'Thời gian kết thúc phải sau thời gian bắt đầu.');
      }
    }
    if (['CREATE', 'RESCHEDULE', 'UPDATE'].includes(operation) && root.YC.selectors?.sessionValidation) {
      const validation = root.YC.selectors.sessionValidation(state, { ...snapshot, excludeSessionId });
      if (!validation.valid) throw approvalError(validation.errors[0].code, validation.errors[0].message);
    }
  }

  function validateCourse(snapshot, state, excludeId = null) {
    const code = String(snapshot.code || '').trim().toUpperCase();
    if (!code || !String(snapshot.name || '').trim()) throw approvalError('COURSE_REQUIRED', 'Cần mã và tên khóa học.');
    if (!state.programs.some((item) => item.id === snapshot.programId)) throw approvalError('PROGRAM_NOT_FOUND', 'Không tìm thấy chương trình.');
    if (!state.levels.some((item) => item.id === snapshot.levelId && item.programId === snapshot.programId)) throw approvalError('LEVEL_PROGRAM_MISMATCH', 'Cấp độ không thuộc chương trình đã chọn.');
    if (state.courses.some((item) => item.id !== excludeId && String(item.code).toUpperCase() === code)) throw approvalError('COURSE_CODE_EXISTS', 'Mã khóa học đã tồn tại.');
  }

  function validateClass(snapshot, state, excludeId = null) {
    const code = String(snapshot.code || '').trim().toUpperCase();
    if (!code || !String(snapshot.name || '').trim()) throw approvalError('CLASS_REQUIRED', 'Cần mã và tên lớp học.');
    if (!state.branches.some((item) => item.id === snapshot.branchId && item.status === 'ACTIVE')) throw approvalError('BRANCH_NOT_FOUND', 'Không tìm thấy chi nhánh đang hoạt động.');
    const version = state.courseVersions.find((item) => item.id === snapshot.courseVersionId);
    if (!version || version.status !== 'PUBLISHED' || !version.immutable) throw approvalError('COURSE_VERSION_NOT_PUBLISHED', 'Lớp chỉ được gắn với phiên bản khóa học đã công bố.');
    const capacity = Number(snapshot.capacity || 0);
    const minimum = Number(snapshot.minCapacity || 1);
    if (!Number.isInteger(capacity) || capacity < 1 || !Number.isInteger(minimum) || minimum < 1 || minimum > capacity) throw approvalError('INVALID_CLASS_CAPACITY', 'Sức chứa tối thiểu và tối đa của lớp không hợp lệ.');
    if (state.classes.some((item) => item.id !== excludeId && String(item.code).toUpperCase() === code)) throw approvalError('CLASS_CODE_EXISTS', 'Mã lớp đã tồn tại.');
    if (snapshot.startDate && snapshot.endDate && new Date(snapshot.endDate).getTime() < new Date(snapshot.startDate).getTime()) throw approvalError('INVALID_CLASS_DATES', 'Ngày kết thúc phải sau ngày bắt đầu.');
  }

  function buildRequest(input, context) {
    const resourceType = String(input.resourceType || '').toUpperCase();
    const operation = String(input.operation || '').toUpperCase();
    const config = definition(resourceType);
    permissionFor(resourceType, operation);
    const collection = context.state[config.collection];
    const resourceId = input.resourceId || null;
    const before = resourceId ? collection.find((item) => item.id === resourceId) || null : null;
    if (operation !== 'CREATE' && !before) throw approvalError('RESOURCE_NOT_FOUND', 'Không tìm thấy dữ liệu gốc cần thay đổi.');
    const proposedSnapshot = clone(input.proposedSnapshot || {});
    if (!Object.keys(proposedSnapshot).length && !['ARCHIVE', 'CANCEL'].includes(operation)) {
      throw approvalError('PROPOSAL_REQUIRED', 'Cần có nội dung thay đổi được đề xuất.');
    }
    if (resourceType === 'SESSION') validateSession({ ...(before || {}), ...proposedSnapshot }, context.state, operation, resourceId);
    if (resourceType === 'COURSE' && !['ARCHIVE'].includes(operation)) validateCourse({ ...(before || {}), ...proposedSnapshot }, context.state, resourceId);
    if (resourceType === 'CLASS' && !['ARCHIVE'].includes(operation)) validateClass({ ...(before || {}), ...proposedSnapshot }, context.state, resourceId);
    const provisionalResourceId = operation === 'CREATE'
      ? proposedSnapshot.provisionalId || proposedSnapshot.id || uid(resourceType.toLowerCase())
      : null;
    return {
      id: uid('change-request'),
      resourceType,
      operation,
      resourceId,
      provisionalResourceId,
      baseVersion: Number(input.baseVersion ?? 0),
      beforeSnapshot: clone(before),
      proposedSnapshot,
      diff: diff(before, proposedSnapshot),
      reason: String(input.reason || '').trim(),
      submittedBy: context.actorId,
      submittedAt: context.now,
      status: 'SUBMITTED',
      revision: Number(input.revision || 1),
      reviewerId: null,
      reviewNote: null,
      reviewedAt: null,
      appliedAt: null,
      eventIds: [],
    };
  }

  function assertReviewable(request) {
    if (!request) throw approvalError('REQUEST_NOT_FOUND', 'Không tìm thấy yêu cầu phê duyệt.');
    if (!['SUBMITTED', 'IN_REVIEW'].includes(request.status)) {
      throw approvalError('REQUEST_NOT_REVIEWABLE', 'Yêu cầu không còn ở trạng thái có thể duyệt.');
    }
    return request;
  }

  function transition(request, nextStatus) {
    if (!(REQUEST_TRANSITIONS[request.status] || []).includes(nextStatus)) {
      throw approvalError('INVALID_REQUEST_TRANSITION', `Không thể chuyển yêu cầu từ ${request.status} sang ${nextStatus}.`);
    }
    request.status = nextStatus;
    return request;
  }

  function stale(request, state) {
    const config = definition(request.resourceType);
    const collection = state[config.collection];
    if (request.operation === 'CREATE') {
      return request.baseVersion !== 0 || collection.some((item) => item.id === request.provisionalResourceId);
    }
    const canonical = collection.find((item) => item.id === request.resourceId);
    return !canonical || Number(canonical[config.versionKey] || 0) !== Number(request.baseVersion);
  }

  function applyChange(request, state) {
    const config = definition(request.resourceType);
    const collection = state[config.collection];
    if (request.operation === 'CREATE') {
      const proposed = clone(request.proposedSnapshot);
      delete proposed.provisionalId;
      const record = {
        ...proposed,
        id: request.provisionalResourceId,
        [config.versionKey]: Number(proposed[config.versionKey] || 1),
        changeRequestId: request.id,
      };
      if (request.resourceType === 'SESSION') validateSession(record, state, request.operation);
      if (request.resourceType === 'COURSE') validateCourse(record, state);
      if (request.resourceType === 'CLASS') validateClass(record, state);
      collection.push(record);
      if (request.resourceType === 'CLASS' && Array.isArray(record.recurrence) && record.recurrence.length) {
        state.timetableRules.push({
          id: uid('timetable'), classId: record.id, recurrence: clone(record.recurrence),
          durationMinutes: Number(record.durationMinutes || 90), room: record.room,
          branchId: record.branchId, timezone: record.timezone || 'Asia/Ho_Chi_Minh', status: 'ACTIVE',
        });
      }
      if (request.resourceType === 'SESSION') {
        state.lessonPlans.push({ id: uid('lesson-plan'), sessionId: record.id, lessonTemplateId: record.lessonTemplateId, adaptations: [], readiness: 'DRAFT', ownerId: request.submittedBy });
        const assignments = state.teacherAssignments.filter((item) => item.classId === record.classId && ['ACCEPTED', 'ACTIVE'].includes(item.status));
        assignments.forEach((assignment) => state.sessionAssignments.push({ id: uid('session-assignment'), sessionId: record.id, teacherProfileId: assignment.teacherProfileId, role: assignment.role, status: 'ACTIVE', startsAt: record.startsAt, endsAt: record.endsAt }));
      }
      return record;
    }

    const canonical = collection.find((item) => item.id === request.resourceId);
    if (!canonical) throw approvalError('RESOURCE_NOT_FOUND', 'Không tìm thấy dữ liệu gốc cần áp dụng.');
    if (request.resourceType === 'COURSE' && !['ARCHIVE'].includes(request.operation)) validateCourse({ ...canonical, ...request.proposedSnapshot }, state, canonical.id);
    if (request.resourceType === 'CLASS' && !['ARCHIVE'].includes(request.operation)) validateClass({ ...canonical, ...request.proposedSnapshot }, state, canonical.id);
    if (request.resourceType === 'SESSION' && ['RESCHEDULE', 'UPDATE'].includes(request.operation)) {
      validateSession({ ...canonical, ...request.proposedSnapshot }, state, request.operation, canonical.id);
      canonical.scheduleRevisions ||= [];
      canonical.scheduleRevisions.push({
        startsAt: canonical.startsAt, endsAt: canonical.endsAt, room: canonical.room, mode: canonical.mode,
        version: canonical[config.versionKey], changedByRequestId: request.id, changedAt: request.reviewedAt,
      });
    }
    if (request.operation === 'ARCHIVE') canonical.status = 'ARCHIVED';
    else if (request.operation === 'CANCEL') canonical.status = 'CANCELLED';
    else Object.assign(canonical, clone(request.proposedSnapshot));
    canonical.id = request.resourceId;
    canonical[config.versionKey] = Number(canonical[config.versionKey] || 0) + 1;
    canonical.changeRequestId = request.id;
    return canonical;
  }

  function resourceScope(input, state) {
    const proposed = input.proposedSnapshot || {};
    const resourceType = String(input.resourceType || '').toUpperCase();
    const config = RESOURCES[resourceType];
    const canonical = config && input.resourceId ? state[config.collection].find((item) => item.id === input.resourceId) : null;
    return {
      classId: proposed.classId || canonical?.classId || null,
      sessionId: resourceType === 'SESSION' ? input.resourceId || null : null,
      branchId: proposed.branchId || canonical?.branchId || null,
      organizationId: state.organizations[0]?.id,
    };
  }

  root.YC.define('approval', Object.freeze({
    REQUEST_TRANSITIONS,
    applyChange,
    assertReviewable,
    buildRequest,
    diff,
    permissionFor,
    resourceScope,
    stale,
    transition,
  }));
})(globalThis);

/* 05-commands.js */
(function defineCommands(root) {
  'use strict';

  const { clone, uid } = root.YC.utils;
  const CMS_COLLECTIONS = Object.freeze([
    'navigationGroups', 'navigationItems', 'heroBanners', 'publicProgramProfiles', 'publicBranchProfiles',
    'publicTeacherProfiles', 'articles', 'articleCategories', 'publicEvents', 'staticPages', 'contactChannels',
  ]);

  class CommandError extends Error {
    constructor(code, message, details = {}) {
      super(message);
      this.name = 'CommandError';
      this.code = code;
      Object.assign(this, details);
    }
  }

  function required(value, code, message) {
    if (!value) throw new CommandError(code, message);
    return value;
  }

  function requireRole(actor, roles) {
    required(actor, 'AUTH_REQUIRED', 'Cần đăng nhập để thực hiện thao tác này.');
    if (!roles.includes(actor.role) && actor.role !== 'ADMIN') {
      throw new CommandError('FORBIDDEN', 'Vai trò hiện tại không có quyền thực hiện thao tác này.');
    }
  }

  function create(store) {
    function nowIso() {
      return new Date(store.clock()).toISOString();
    }

    function publishSiteItem(draft, collectionName, item, actorId) {
      const collection = cmsCollection(draft, collectionName);
      const publishedAt = nowIso();
      collection.filter((entry) => entry.id !== item.id && (entry.contentKey || entry.id) === (item.contentKey || item.id) && entry.status === 'PUBLISHED').forEach((entry) => {
        entry.status = 'ARCHIVED';
        entry.effectiveTo = publishedAt;
        entry.archivedBy = actorId;
        entry.archivedAt = publishedAt;
      });
      item.status = 'PUBLISHED';
      item.effectiveFrom = item.effectiveFrom || publishedAt;
      item.publishedBy = actorId;
      item.publishedAt = publishedAt;
      return publishedAt;
    }

    function appendEvent(draft, context, type, resourceType, resourceId, summary, extra = {}) {
      const event = {
        id: uid('event'),
        type,
        resourceType,
        resourceId,
        actorId: context.actor.id,
        occurredAt: nowIso(),
        summary,
        ...extra,
      };
      draft.domainEvents.unshift(event);
      context.eventIds.push(event.id);
      return event;
    }

    function appendAudit(draft, context, action, resourceType, resourceId, detail) {
      draft.auditLogs.unshift({
        id: uid('audit'),
        actorId: context.actor.id,
        action,
        resourceType,
        resourceId,
        detail,
        occurredAt: nowIso(),
      });
    }

    function notifyRole(draft, role, title, body, link = '') {
      const recipient = draft.users.find((item) => item.role === role && item.status === 'ACTIVE');
      if (!recipient) return;
      draft.notifications.unshift({ id: uid('notification'), userId: recipient.id, title, body, link, read: false, createdAt: nowIso() });
    }

    function requirePermission(draft, context, permissionId) {
      required(context.actor, 'AUTH_REQUIRED', 'Cần đăng nhập để thực hiện thao tác này.');
      const organizationId = draft.organizations[0]?.id;
      if (!root.YC.policy.can(context.actor, permissionId, { organizationId }, draft)) {
        throw new CommandError('FORBIDDEN', 'Tài khoản hiện tại không có quyền thực hiện thao tác này.');
      }
    }

    function requireReason(payload) {
      const reason = String(payload.reason || '').trim();
      if (!reason) throw new CommandError('REASON_REQUIRED', 'Cần ghi rõ lý do thay đổi quyền.');
      return reason;
    }

    function cmsCollection(draft, name) {
      if (!CMS_COLLECTIONS.includes(name) || !Array.isArray(draft[name])) {
        throw new CommandError('CMS_COLLECTION_INVALID', 'Loại nội dung website không hợp lệ.');
      }
      return draft[name];
    }

    function cmsItem(draft, payload) {
      return required(cmsCollection(draft, payload.collection).find((item) => item.id === payload.contentId), 'SITE_CONTENT_NOT_FOUND', 'Không tìm thấy nội dung website.');
    }

    function contentFields(payload) {
      const reserved = new Set(['collection', 'contentId', 'sourceContentId', 'reason', 'id', 'revision', 'status', 'createdBy', 'createdAt', 'updatedBy', 'updatedAt', 'publishedBy', 'publishedAt', 'archivedBy', 'archivedAt', 'approvalRequestId']);
      return Object.fromEntries(Object.entries(payload).filter(([key]) => !reserved.has(key)).map(([key, value]) => [key, clone(value)]));
    }

    function validatePermissionInput(draft, payload) {
      const permissionId = String(payload.permissionId || '').trim();
      required(draft.permissionDefinitions.find((item) => item.id === permissionId && item.status === 'ACTIVE'), 'PERMISSION_NOT_FOUND', 'Không tìm thấy quyền đang hoạt động.');
      const effect = String(payload.effect || '').toUpperCase();
      if (!['ALLOW', 'DENY'].includes(effect)) throw new CommandError('INVALID_PERMISSION_EFFECT', 'Hiệu lực quyền phải là Cho phép hoặc Từ chối.');
      const scopeType = String(payload.scopeType || 'ORGANIZATION').toUpperCase();
      if (!['ORGANIZATION', 'BRANCH', 'CLASS', 'SESSION', 'ASSIGNED_CLASS', 'OWN_LEARNER', 'LINKED_LEARNER'].includes(scopeType)) {
        throw new CommandError('INVALID_PERMISSION_SCOPE', 'Phạm vi quyền không hợp lệ.');
      }
      return { permissionId, effect, scopeType, scopeIds: Array.isArray(payload.scopeIds) ? payload.scopeIds.filter(Boolean) : [] };
    }

    function ensureAdminContinuity(draft) {
      const organizationId = draft.organizations[0]?.id;
      const safe = draft.users.filter((item) => item.role === 'ADMIN' && item.status === 'ACTIVE').some((admin) => (
        root.YC.policy.can(admin, 'access.manage_role', { organizationId }, draft)
        && root.YC.policy.can(admin, 'approval.decide', { organizationId }, draft)
      ));
      if (!safe) throw new CommandError('LAST_ADMIN_GUARD', 'Phải còn ít nhất một Quản trị viên có quyền quản lý truy cập và phê duyệt.');
    }

    function approvalCall(callback) {
      try {
        return callback();
      } catch (error) {
        throw new CommandError(error.code || 'APPROVAL_ERROR', error.message || 'Không thể xử lý yêu cầu phê duyệt.');
      }
    }

    function notifyUser(draft, userId, title, body, link) {
      if (!draft.users.some((item) => item.id === userId && item.status === 'ACTIVE')) return;
      draft.notifications.unshift({ id: uid('notification'), userId, title, body, link, read: false, createdAt: nowIso() });
    }

    function generateClassSessions(draft, cohort) {
      const rules = draft.timetableRules.filter((item) => item.classId === cohort.id && item.status !== 'INACTIVE');
      const unitIds = draft.units.filter((item) => item.courseVersionId === cohort.courseVersionId).sort((a, b) => a.order - b.order).map((item) => item.id);
      const lessons = draft.lessonTemplates.filter((item) => unitIds.includes(item.unitId)).sort((a, b) => unitIds.indexOf(a.unitId) - unitIds.indexOf(b.unitId));
      if (!lessons.length) throw new CommandError('CLASS_LESSON_REQUIRED', 'Phiên bản khóa học chưa có bài học để sinh lịch.');
      const dayIndexes = { SUN: 0, MON: 1, TUE: 2, WED: 3, THU: 4, FRI: 5, SAT: 6 };
      const start = new Date(`${cohort.startDate || nowIso().slice(0, 10)}T00:00:00Z`);
      const fallbackEnd = new Date(start.getTime() + 28 * 86400000);
      const end = cohort.endDate ? new Date(`${cohort.endDate}T23:59:59Z`) : fallbackEnd;
      let created = 0;
      for (let cursor = new Date(start); cursor <= end && created < 48; cursor = new Date(cursor.getTime() + 86400000)) {
        const date = cursor.toISOString().slice(0, 10);
        for (const rule of rules) {
          for (const slot of rule.recurrence || []) {
            const match = /^(SUN|MON|TUE|WED|THU|FRI|SAT)_(\d{2})(\d{2})$/.exec(slot);
            if (!match || dayIndexes[match[1]] !== cursor.getUTCDay()) continue;
            const startsAt = new Date(`${date}T${match[2]}:${match[3]}:00+07:00`);
            const endsAt = new Date(startsAt.getTime() + Number(rule.durationMinutes || cohort.durationMinutes || 90) * 60000);
            const startIso = startsAt.toISOString();
            if (draft.sessions.some((item) => item.classId === cohort.id && item.startsAt === startIso)) continue;
            const lesson = lessons[created % lessons.length];
            draft.sessions.push({
              id: uid('session'), classId: cohort.id, lessonTemplateId: lesson.id,
              startsAt: startIso, endsAt: endsAt.toISOString(), room: rule.room || cohort.room,
              mode: cohort.mode, status: 'PLANNED', attendanceFinalized: false, version: 1,
              generatedFromTimetableId: rule.id,
            });
            created += 1;
          }
        }
      }
      return created;
    }

    function findLead(draft, leadId) {
      return required(draft.leads.find((item) => item.id === leadId), 'LEAD_NOT_FOUND', 'Không tìm thấy khách hàng.');
    }

    function latestForLead(collection, leadId) {
      return collection.filter((item) => item.leadId === leadId).at(-1) || null;
    }

    function activeMakeUpBooking(draft, caseId) {
      return draft.makeUpBookings.find((item) => item.remedialCaseId === caseId && ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status)) || null;
    }

    function validateMakeUpTarget(draft, payload, context) {
      const remedialCase = required(draft.remedialCases.find((item) => item.id === payload.caseId), 'REMEDIAL_CASE_NOT_FOUND', 'Không tìm thấy hồ sơ học bù.');
      const targetSession = required(draft.sessions.find((item) => item.id === payload.targetSessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học đích.');
      const candidate = required(root.YC.remedial.rankMakeUpTargets(draft, remedialCase.id).find((item) => item.sessionId === targetSession.id), 'MAKE_UP_TARGET_INELIGIBLE', 'Buổi học này không thể dùng làm lịch học bù.');
      const failures = candidate.hardGates.filter((item) => !item.passed);
      const nonMappingFailures = failures.filter((item) => item.key !== 'LESSON_TEMPLATE');
      if (nonMappingFailures.length) {
        throw new CommandError('MAKE_UP_TARGET_INELIGIBLE', nonMappingFailures.map((item) => item.label).join(' · '), {
          alternatives: root.YC.remedial.rankMakeUpTargets(draft, remedialCase.id).filter((item) => item.eligible).slice(0, 3),
        });
      }
      let contentMapping = { type: 'EXACT', sourceLessonTemplateId: remedialCase.sourceLessonTemplateId, targetLessonTemplateId: targetSession.lessonTemplateId, coverageNote: null, approvedBy: null, approvedAt: null };
      if (failures.some((item) => item.key === 'LESSON_TEMPLATE')) {
        if (context.actor.role !== 'ADMIN') throw new CommandError('CONTENT_MAPPING_APPROVAL_REQUIRED', 'Nội dung khác bài học gốc; cần Admin duyệt mapping.');
        const overrideNote = String(payload.overrideNote || '').trim();
        if (!overrideNote) throw new CommandError('OVERRIDE_NOTE_REQUIRED', 'Admin cần ghi rõ phạm vi nội dung tương đương.');
        contentMapping = { ...contentMapping, type: 'ADMIN_EQUIVALENT', coverageNote: overrideNote, approvedBy: context.actor.id, approvedAt: nowIso() };
      }
      return { remedialCase, targetSession, targetClass: draft.classes.find((item) => item.id === targetSession.classId), candidate, contentMapping };
    }

    function makeUpBookingRecord(draft, validated, context, status) {
      const confirmationDeadline = new Date(new Date(nowIso()).getTime() + 24 * 60 * 60 * 1000).toISOString();
      const booking = {
        id: uid('make-up'), remedialCaseId: validated.remedialCase.id, learnerId: validated.remedialCase.learnerId,
        sourceAttendanceId: validated.remedialCase.sourceAttendanceId,
        originalSessionId: validated.remedialCase.sourceSessionId, originalClassId: validated.remedialCase.sourceClassId,
        targetSessionId: validated.targetSession.id, targetClassId: validated.targetSession.classId,
        sessionId: validated.targetSession.id, reservedSeats: 1, rosterRole: 'MAKE_UP_GUEST',
        contentMapping: validated.contentMapping, status, bookedBy: status === 'BOOKED' ? context.actor.id : null,
        bookedAt: status === 'BOOKED' ? nowIso() : null, heldBy: status === 'HELD' ? context.actor.id : null,
        heldAt: status === 'HELD' ? nowIso() : null, confirmationDeadline,
        history: [{ fromStatus: 'CANDIDATE', toStatus: status, occurredAt: nowIso(), actorId: context.actor.id }],
      };
      draft.makeUpBookings.push(booking);
      return booking;
    }

    function applyAdminDirectChange(draft, input, context) {
      const permissionId = approvalCall(() => root.YC.approval.permissionFor(input.resourceType, input.operation));
      const scope = root.YC.approval.resourceScope(input, draft);
      if (!root.YC.policy.can(context.actor, permissionId, scope, draft)) throw new CommandError('FORBIDDEN', 'Tài khoản hiện tại không có quyền tạo dữ liệu này.');
      const request = approvalCall(() => root.YC.approval.buildRequest(input, { actorId: context.actor.id, now: nowIso(), state: draft }));
      request.direct = true;
      request.reviewerId = context.actor.id;
      request.reviewNote = 'Quản trị viên tạo trực tiếp theo quyền được cấp.';
      request.reviewedAt = nowIso();
      const canonical = approvalCall(() => root.YC.approval.applyChange(request, draft));
      root.YC.approval.transition(request, 'APPROVED');
      request.resourceId = canonical.id;
      request.appliedAt = nowIso();
      draft.changeRequests.push(request);
      const event = appendEvent(draft, context, 'ADMIN_DIRECT_CHANGE_APPLIED', 'CHANGE_REQUEST', request.id, `${request.resourceType} · ${request.operation} · ${input.reason}.`);
      request.eventIds.push(event.id);
      appendAudit(draft, context, 'ADMIN_DIRECT_CHANGE_APPLIED', request.resourceType, canonical.id, input.reason);
      return { message: 'Đã tạo dữ liệu chính thức và lưu đầy đủ nhật ký.', requestId: request.id, resourceId: canonical.id, status: request.status, applied: true };
    }

    const handlers = {
      SAVE_SITE_SETTINGS(draft, payload, context) {
        requirePermission(draft, context, 'site.configure_contact');
        const settings = required(draft.siteSettings?.[0], 'SITE_SETTINGS_NOT_FOUND', 'Chưa có cấu hình website.');
        Object.assign(settings, contentFields(payload), { updatedBy: context.actor.id, updatedAt: nowIso(), revision: Number(settings.revision || 0) + 1 });
        appendEvent(draft, context, 'SITE_SETTINGS_SAVED', 'SITE_SETTINGS', settings.id, 'Đã cập nhật cấu hình thương hiệu và kênh liên hệ.');
        appendAudit(draft, context, 'SITE_SETTINGS_SAVED', 'SITE_SETTINGS', settings.id, 'Cập nhật cấu hình website.');
        return { message: 'Đã lưu cấu hình website.', settingsId: settings.id };
      },

      CREATE_SITE_CONTENT_DRAFT(draft, payload, context) {
        requirePermission(draft, context, 'site.edit');
        const collection = cmsCollection(draft, payload.collection);
        const source = payload.sourceContentId
          ? required(collection.find((item) => item.id === payload.sourceContentId), 'SITE_CONTENT_NOT_FOUND', 'Không tìm thấy phiên bản nguồn.')
          : null;
        const base = source ? clone(source) : {};
        ['id', 'status', 'createdBy', 'createdAt', 'updatedBy', 'updatedAt', 'publishedBy', 'publishedAt', 'archivedBy', 'archivedAt', 'approvalRequestId', 'effectiveTo'].forEach((key) => delete base[key]);
        const fields = contentFields(payload);
        const contentKey = String(fields.contentKey || source?.contentKey || uid('site-key'));
        const revision = Math.max(0, ...collection.filter((item) => (item.contentKey || item.id) === contentKey).map((item) => Number(item.revision || 0))) + 1;
        const item = {
          ...base, ...fields, id: uid('site-content'), contentKey, revision, status: 'DRAFT',
          sourceRevisionId: source?.id || null, effectiveFrom: fields.effectiveFrom || source?.effectiveFrom || nowIso(), effectiveTo: fields.effectiveTo || null,
          createdBy: context.actor.id, createdAt: nowIso(), updatedBy: context.actor.id, updatedAt: nowIso(),
        };
        collection.push(item);
        appendEvent(draft, context, 'SITE_CONTENT_DRAFT_CREATED', 'SITE_CONTENT', item.id, `${payload.collection} · phiên bản ${revision}.`);
        appendAudit(draft, context, 'SITE_CONTENT_DRAFT_CREATED', 'SITE_CONTENT', item.id, `Tạo nháp ${payload.collection}.`);
        return { message: 'Đã tạo bản nháp nội dung.', contentId: item.id, revision };
      },

      SUBMIT_SITE_CONTENT(draft, payload, context) {
        requirePermission(draft, context, 'site.submit');
        const reason = requireReason(payload);
        const item = cmsItem(draft, payload);
        if (item.status !== 'DRAFT') throw new CommandError('SITE_CONTENT_NOT_DRAFT', 'Chỉ nội dung nháp mới có thể gửi duyệt.');
        item.status = 'SUBMITTED';
        item.submittedBy = context.actor.id;
        item.submittedAt = nowIso();
        const request = {
          id: uid('change-request'), resourceType: 'SITE_CONTENT', resourceId: item.id, collection: payload.collection,
          operation: 'PUBLISH', status: 'SUBMITTED', requesterId: context.actor.id, submittedBy: context.actor.id, reason,
          baseVersion: Number(item.sourceRevisionId ? item.revision - 1 : 0), revision: Number(item.revision || 1), diff: [],
          beforeSnapshot: null, afterSnapshot: clone(item), proposedSnapshot: clone(item), submittedAt: nowIso(), eventIds: [],
        };
        item.approvalRequestId = request.id;
        draft.changeRequests.push(request);
        const event = appendEvent(draft, context, 'SITE_CONTENT_SUBMITTED', 'CHANGE_REQUEST', request.id, `${payload.collection} · ${reason}.`);
        request.eventIds.push(event.id);
        appendAudit(draft, context, 'SITE_CONTENT_SUBMITTED', 'SITE_CONTENT', item.id, reason);
        notifyRole(draft, 'ADMIN', 'Có nội dung website chờ duyệt', `${context.actor.name}: ${item.title || item.name || item.label || payload.collection}.`, '/app/admin/site-content');
        return { message: 'Đã gửi nội dung và đang chờ Admin duyệt.', contentId: item.id, requestId: request.id, status: item.status };
      },

      PUBLISH_SITE_CONTENT(draft, payload, context) {
        requirePermission(draft, context, 'site.publish');
        const collection = cmsCollection(draft, payload.collection);
        const item = required(collection.find((entry) => entry.id === payload.contentId), 'SITE_CONTENT_NOT_FOUND', 'Không tìm thấy nội dung website.');
        if (!['DRAFT', 'SUBMITTED'].includes(item.status)) throw new CommandError('SITE_CONTENT_NOT_PUBLISHABLE', 'Nội dung không ở trạng thái có thể xuất bản.');
        const publishedAt = publishSiteItem(draft, payload.collection, item, context.actor.id);
        if (item.approvalRequestId) {
          const request = draft.changeRequests.find((entry) => entry.id === item.approvalRequestId);
          if (request) Object.assign(request, { status: 'APPROVED', reviewerId: context.actor.id, reviewedAt: publishedAt, appliedAt: publishedAt, reviewNote: String(payload.reviewNote || 'Đã duyệt nội dung để xuất bản.') });
        }
        appendEvent(draft, context, 'SITE_CONTENT_PUBLISHED', 'SITE_CONTENT', item.id, `${payload.collection} · phiên bản ${item.revision || 1}.`);
        appendAudit(draft, context, 'SITE_CONTENT_PUBLISHED', 'SITE_CONTENT', item.id, `Xuất bản ${payload.collection}.`);
        return { message: item.effectiveFrom > publishedAt ? 'Đã lên lịch xuất bản nội dung.' : 'Đã xuất bản nội dung.', contentId: item.id, status: item.status };
      },

      ARCHIVE_SITE_CONTENT(draft, payload, context) {
        requirePermission(draft, context, 'site.archive');
        const reason = requireReason(payload);
        const item = cmsItem(draft, payload);
        if (item.status === 'ARCHIVED') throw new CommandError('SITE_CONTENT_ALREADY_ARCHIVED', 'Nội dung đã được lưu trữ.');
        item.status = 'ARCHIVED';
        item.effectiveTo = nowIso();
        item.archivedBy = context.actor.id;
        item.archivedAt = nowIso();
        item.archiveReason = reason;
        appendEvent(draft, context, 'SITE_CONTENT_ARCHIVED', 'SITE_CONTENT', item.id, reason);
        appendAudit(draft, context, 'SITE_CONTENT_ARCHIVED', 'SITE_CONTENT', item.id, reason);
        return { message: 'Đã lưu trữ nội dung.', contentId: item.id, status: item.status };
      },

      SET_ROLE_PERMISSION(draft, payload, context) {
        requirePermission(draft, context, 'access.manage_role');
        const reason = requireReason(payload);
        const role = String(payload.role || '').toUpperCase();
        required(draft.users.find((item) => item.role === role) || root.YC.permissions.roleDefaults.find((item) => item.role === role), 'ROLE_NOT_FOUND', 'Không tìm thấy vai trò.');
        const input = validatePermissionInput(draft, payload);
        const changedAt = nowIso();
        draft.rolePermissions.filter((item) => item.role === role
          && item.permissionId === input.permissionId
          && item.status !== 'REVOKED'
          && (!item.effectiveTo || new Date(item.effectiveTo).getTime() > new Date(changedAt).getTime()))
          .forEach((item) => {
            item.effectiveTo = changedAt;
            item.status = 'REPLACED';
          });
        const record = {
          id: uid('role-permission'), role, permissionId: input.permissionId, effect: input.effect,
          scopeType: input.scopeType, scopeIds: input.scopeIds,
          effectiveFrom: payload.effectiveFrom || changedAt, effectiveTo: payload.effectiveTo || null,
          status: 'ACTIVE', changedBy: context.actor.id, changedAt, reason,
        };
        draft.rolePermissions.push(record);
        ensureAdminContinuity(draft);
        appendEvent(draft, context, 'ROLE_PERMISSION_SET', 'ROLE_PERMISSION', record.id, `${role} · ${input.permissionId} · ${input.effect}.`);
        appendAudit(draft, context, 'ROLE_PERMISSION_SET', 'ROLE_PERMISSION', record.id, reason);
        return { message: 'Đã cập nhật quyền của vai trò.', rolePermissionId: record.id };
      },

      SET_USER_PERMISSION_OVERRIDE(draft, payload, context) {
        requirePermission(draft, context, 'access.manage_user_override');
        const reason = requireReason(payload);
        const user = required(draft.users.find((item) => item.id === payload.userId), 'USER_NOT_FOUND', 'Không tìm thấy tài khoản.');
        const input = validatePermissionInput(draft, payload);
        const grantedAt = nowIso();
        draft.userPermissionOverrides.filter((item) => item.userId === user.id
          && item.permissionId === input.permissionId
          && item.status !== 'REVOKED'
          && (!item.effectiveTo || new Date(item.effectiveTo).getTime() > new Date(grantedAt).getTime()))
          .forEach((item) => {
            item.effectiveTo = grantedAt;
            item.status = 'REPLACED';
          });
        const record = {
          id: uid('user-permission'), userId: user.id, permissionId: input.permissionId, effect: input.effect,
          scopeType: input.scopeType, scopeIds: input.scopeIds,
          effectiveFrom: payload.effectiveFrom || grantedAt, effectiveTo: payload.effectiveTo || null,
          status: 'ACTIVE', grantedBy: context.actor.id, grantedAt, reason,
        };
        draft.userPermissionOverrides.push(record);
        ensureAdminContinuity(draft);
        appendEvent(draft, context, 'USER_PERMISSION_OVERRIDE_SET', 'USER_PERMISSION_OVERRIDE', record.id, `${user.name} · ${input.permissionId} · ${input.effect}.`);
        appendAudit(draft, context, 'USER_PERMISSION_OVERRIDE_SET', 'USER_PERMISSION_OVERRIDE', record.id, reason);
        return { message: 'Đã lưu ngoại lệ quyền của tài khoản.', overrideId: record.id };
      },

      REVOKE_USER_PERMISSION_OVERRIDE(draft, payload, context) {
        requirePermission(draft, context, 'access.manage_user_override');
        const reason = requireReason(payload);
        const record = required(draft.userPermissionOverrides.find((item) => item.id === payload.overrideId), 'OVERRIDE_NOT_FOUND', 'Không tìm thấy ngoại lệ quyền.');
        if (record.status === 'REVOKED') throw new CommandError('OVERRIDE_ALREADY_REVOKED', 'Ngoại lệ quyền đã được thu hồi trước đó.');
        record.status = 'REVOKED';
        record.effectiveTo = nowIso();
        record.revokedBy = context.actor.id;
        record.revokedAt = nowIso();
        record.revokeReason = reason;
        ensureAdminContinuity(draft);
        appendEvent(draft, context, 'USER_PERMISSION_OVERRIDE_REVOKED', 'USER_PERMISSION_OVERRIDE', record.id, reason);
        appendAudit(draft, context, 'USER_PERMISSION_OVERRIDE_REVOKED', 'USER_PERMISSION_OVERRIDE', record.id, reason);
        return { message: 'Đã thu hồi ngoại lệ quyền.', overrideId: record.id };
      },

      SUBMIT_CHANGE_REQUEST(draft, payload, context) {
        required(context.actor, 'AUTH_REQUIRED', 'Cần đăng nhập để gửi yêu cầu.');
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Cần ghi rõ lý do đề xuất thay đổi.');
        const resourceType = String(payload.resourceType || '').toUpperCase();
        const operation = String(payload.operation || '').toUpperCase();
        const permissionId = approvalCall(() => root.YC.approval.permissionFor(resourceType, operation));
        const scope = root.YC.approval.resourceScope(payload, draft);
        if (!root.YC.policy.can(context.actor, permissionId, scope, draft)) {
          throw new CommandError('FORBIDDEN', 'Tài khoản hiện tại không có quyền gửi đề xuất này.');
        }
        const request = approvalCall(() => root.YC.approval.buildRequest({ ...payload, reason }, {
          actorId: context.actor.id,
          now: nowIso(),
          state: draft,
        }));
        draft.changeRequests.push(request);
        const event = appendEvent(draft, context, 'CHANGE_REQUEST_SUBMITTED', 'CHANGE_REQUEST', request.id, `${request.resourceType} · ${request.operation} · ${reason}.`);
        request.eventIds.push(event.id);
        appendAudit(draft, context, 'CHANGE_REQUEST_SUBMITTED', 'CHANGE_REQUEST', request.id, reason);
        notifyRole(draft, 'ADMIN', 'Có yêu cầu chờ phê duyệt', `${context.actor.name}: ${request.resourceType} · ${request.operation}.`, `/app/admin/approvals/${request.id}`);
        return {
          message: 'Đã gửi yêu cầu và đang chờ Quản trị viên duyệt.',
          requestId: request.id,
          provisionalResourceId: request.provisionalResourceId,
          status: request.status,
        };
      },

      REVIEW_CHANGE_REQUEST(draft, payload, context) {
        requirePermission(draft, context, 'approval.decide');
        const request = required(draft.changeRequests.find((item) => item.id === payload.requestId), 'REQUEST_NOT_FOUND', 'Không tìm thấy yêu cầu phê duyệt.');
        const inputDecision = String(payload.decision || '').toUpperCase();
        const decisionMap = { APPROVE: 'APPROVED', REJECT: 'REJECTED', REQUEST_CHANGES: 'CHANGES_REQUESTED', CHANGES_REQUESTED: 'CHANGES_REQUESTED' };
        const nextStatus = decisionMap[inputDecision];
        if (!nextStatus) throw new CommandError('INVALID_REVIEW_DECISION', 'Quyết định duyệt không hợp lệ.');
        if (request.status === nextStatus && ['APPROVED', 'REJECTED', 'CHANGES_REQUESTED'].includes(nextStatus)) {
          return { message: 'Quyết định này đã được ghi nhận trước đó.', requestId: request.id, status: request.status, idempotent: true, applied: request.status === 'APPROVED' };
        }
        if (request.submittedBy === context.actor.id) throw new CommandError('SELF_REVIEW_FORBIDDEN', 'Người gửi không được tự duyệt yêu cầu của mình.');
        const note = String(payload.note || '').trim();
        if (['REJECTED', 'CHANGES_REQUESTED'].includes(nextStatus) && !note) {
          throw new CommandError('REVIEW_NOTE_REQUIRED', 'Từ chối hoặc yêu cầu chỉnh sửa phải có ghi chú.');
        }
        approvalCall(() => root.YC.approval.assertReviewable(request, draft));
        request.reviewerId = context.actor.id;
        request.reviewNote = note || null;
        request.reviewedAt = nowIso();

        if (nextStatus === 'APPROVED' && request.resourceType !== 'SITE_CONTENT' && root.YC.approval.stale(request, draft)) {
          root.YC.approval.transition(request, 'CONFLICTED');
          const event = appendEvent(draft, context, 'CHANGE_REQUEST_CONFLICTED', 'CHANGE_REQUEST', request.id, 'Dữ liệu gốc đã thay đổi; yêu cầu cần được cập nhật lại.');
          request.eventIds.push(event.id);
          appendAudit(draft, context, 'CHANGE_REQUEST_CONFLICTED', 'CHANGE_REQUEST', request.id, note || 'Phát hiện sai khác phiên bản dữ liệu gốc.');
          notifyUser(draft, request.submittedBy, 'Yêu cầu cần cập nhật lại', `${request.resourceType} · dữ liệu gốc đã thay đổi.`, `/app/teacher/requests/${request.id}`);
          return { message: 'Yêu cầu bị xung đột phiên bản và chưa được áp dụng.', requestId: request.id, status: request.status, applied: false };
        }

        if (nextStatus === 'APPROVED') {
          const canonical = request.resourceType === 'SITE_CONTENT'
            ? required(cmsCollection(draft, request.collection).find((item) => item.id === request.resourceId && item.status === 'SUBMITTED'), 'SITE_CONTENT_NOT_REVIEWABLE', 'Nội dung không còn ở trạng thái chờ duyệt.')
            : approvalCall(() => root.YC.approval.applyChange(request, draft));
          if (request.resourceType === 'SITE_CONTENT') publishSiteItem(draft, request.collection, canonical, context.actor.id);
          root.YC.approval.transition(request, 'APPROVED');
          request.appliedAt = nowIso();
          request.resourceId = canonical.id;
        } else {
          if (request.resourceType === 'SITE_CONTENT') {
            const item = cmsCollection(draft, request.collection).find((entry) => entry.id === request.resourceId);
            if (item?.status === 'SUBMITTED') Object.assign(item, { status: 'DRAFT', updatedBy: context.actor.id, updatedAt: nowIso() });
          }
          root.YC.approval.transition(request, nextStatus);
        }
        const type = `CHANGE_REQUEST_${request.status}`;
        const event = appendEvent(draft, context, type, 'CHANGE_REQUEST', request.id, `${request.resourceType} · ${request.status}${note ? ` · ${note}` : ''}.`);
        request.eventIds.push(event.id);
        appendAudit(draft, context, type, 'CHANGE_REQUEST', request.id, note || 'Đã duyệt và áp dụng dữ liệu trong cùng transaction.');
        notifyUser(draft, request.submittedBy, `Yêu cầu: ${request.status}`, `${request.resourceType} · ${request.operation}.`, `/app/teacher/requests/${request.id}`);
        return { message: nextStatus === 'APPROVED' ? 'Đã duyệt và áp dụng thay đổi.' : 'Đã ghi nhận quyết định.', requestId: request.id, resourceId: request.resourceId, status: request.status, applied: nextStatus === 'APPROVED' };
      },

      WITHDRAW_CHANGE_REQUEST(draft, payload, context) {
        const request = required(draft.changeRequests.find((item) => item.id === payload.requestId), 'REQUEST_NOT_FOUND', 'Không tìm thấy yêu cầu phê duyệt.');
        if (request.submittedBy !== context.actor.id) throw new CommandError('FORBIDDEN', 'Chỉ người gửi mới được rút yêu cầu.');
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Cần ghi rõ lý do rút yêu cầu.');
        approvalCall(() => root.YC.approval.transition(request, 'WITHDRAWN'));
        request.withdrawnAt = nowIso();
        request.withdrawnBy = context.actor.id;
        request.withdrawReason = reason;
        const event = appendEvent(draft, context, 'CHANGE_REQUEST_WITHDRAWN', 'CHANGE_REQUEST', request.id, reason);
        request.eventIds.push(event.id);
        appendAudit(draft, context, 'CHANGE_REQUEST_WITHDRAWN', 'CHANGE_REQUEST', request.id, reason);
        return { message: 'Đã rút yêu cầu và giữ lại lịch sử.', requestId: request.id, status: request.status };
      },

      CREATE_PUBLIC_LEAD(draft, payload, context) {
        requireRole(context.actor, ['PUBLIC', 'VISITOR']);
        const type = String(payload.type || 'B2C').toUpperCase();
        if (!['B2C', 'B2B', 'SUPPORT'].includes(type)) throw new CommandError('INVALID_LEAD_TYPE', 'Loại yêu cầu không hợp lệ.');
        const name = String(payload.name || '').trim();
        const phone = String(payload.phone || '').trim();
        const email = String(payload.email || '').trim();
        const message = String(payload.message || '').trim();
        if (!name || (!phone && !email) || !message) throw new CommandError('CONTACT_REQUIRED', 'Cần họ tên, thông tin liên hệ và nội dung yêu cầu.');
        const count = draft.leads.filter((item) => item.type === type).length + 1;
        const lead = {
          id: uid('lead'), code: `YC-${type}-${String(count).padStart(4, '0')}`, type, name,
          studentName: String(payload.studentName || '').trim(), organization: String(payload.organization || '').trim(),
          phone, email, message, goal: String(payload.goal || message).trim(), availability: [],
          branchId: payload.branchId || 'branch-q3', learnerId: null, visitorUserId: context.actor.role === 'VISITOR' ? context.actor.id : null,
          status: 'NEW', ownerId: 'admissions-1', createdAt: nowIso(),
        };
        draft.leads.unshift(lead);
        draft.outboundMessages.unshift({ id: uid('outbound'), channel: 'IN_APP', recipient: email || phone, template: type === 'SUPPORT' ? 'SUPPORT_ACKNOWLEDGED' : 'CONTACT_ACKNOWLEDGED', status: 'MOCKED', createdAt: nowIso() });
        appendEvent(draft, context, 'PUBLIC_REQUEST_CREATED', 'LEAD', lead.id, `${lead.code} · ${lead.name}.`);
        appendAudit(draft, context, 'PUBLIC_REQUEST_CREATED', 'LEAD', lead.id, `${type} · ${message}`);
        notifyRole(draft, 'ADMISSIONS', 'Có yêu cầu mới', `${lead.code} · ${lead.name}.`, '/app/admissions/leads');
        if (context.actor.role === 'VISITOR') {
          draft.notifications.unshift({ id: uid('notification'), userId: context.actor.id, title: 'Đã tiếp nhận yêu cầu', body: `${lead.code} · Trung tâm sẽ liên hệ với bạn.`, link: '/tai-khoan', read: false, createdAt: nowIso() });
        }
        return { message: `Đã tiếp nhận yêu cầu ${lead.code}.`, code: lead.code, leadId: lead.id };
      },

      CREATE_LEARNER(draft, payload, context) {
        requireRole(context.actor, ['ADMIN']);
        const code = String(payload.code || '').trim().toUpperCase();
        const name = String(payload.name || '').trim();
        if (!code || !name) throw new CommandError('LEARNER_REQUIRED', 'Cần mã và họ tên học viên.');
        if (draft.learners.some((item) => item.code === code)) throw new CommandError('LEARNER_CODE_EXISTS', 'Mã học viên đã tồn tại.');
        const cohort = payload.classId ? required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.') : null;
        const learner = { id: uid('student'), code, name, phone: String(payload.phone || '').trim(), birthDate: '', status: 'ACTIVE', classId: cohort?.id || null, branchId: cohort?.branchId || 'branch-q3', goal: String(payload.goal || 'Bổ sung từ Quản trị viên').trim() };
        draft.learners.push(learner);
        if (cohort) draft.enrollments.push({ id: uid('enrollment'), learnerId: learner.id, classId: cohort.id, courseVersionId: cohort.courseVersionId, status: 'ACTIVE', startsAt: nowIso(), endsAt: null });
        appendEvent(draft, context, 'LEARNER_CREATED', 'LEARNER', learner.id, `${learner.name} · ${learner.code}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'LEARNER_CREATED', 'LEARNER', learner.id, cohort ? `Xếp lớp ${cohort.name}.` : 'Chưa xếp lớp.');
        return { message: 'Đã thêm học viên.', learnerId: learner.id };
      },

      UPDATE_LEAD_STATUS(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        const status = String(payload.status || '').toUpperCase();
        if (!['NEW', 'CONTACTED', 'PLACEMENT_BOOKED', 'PLACED', 'WON', 'LOST'].includes(status)) throw new CommandError('INVALID_LEAD_STATUS', 'Trạng thái yêu cầu không hợp lệ.');
        const previous = lead.status;
        lead.status = status;
        appendEvent(draft, context, 'LEAD_STATUS_UPDATED', 'LEAD', lead.id, `${previous} → ${status}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'LEAD_STATUS_UPDATED', 'LEAD', lead.id, `${previous} → ${status}.`);
        return { message: 'Đã cập nhật trạng thái yêu cầu.' };
      },

      MARK_NOTIFICATIONS_READ(draft, _payload, context) {
        const rows = draft.notifications.filter((item) => item.userId === context.actor.id && !item.read);
        rows.forEach((item) => { item.read = true; item.readAt = nowIso(); });
        appendAudit(draft, context, 'NOTIFICATIONS_MARKED_READ', 'USER', context.actor.id, `${rows.length} thông báo.`);
        return { message: `Đã đánh dấu ${rows.length} thông báo là đã đọc.`, count: rows.length };
      },

      RUN_MOCK_SYNC(draft, _payload, context) {
        requireRole(context.actor, ['ADMIN']);
        const sync = { id: uid('sync'), adapter: 'GOOGLE_SHEETS_MOCK', status: 'COMPLETED', createdAt: nowIso(), createdBy: context.actor.id };
        draft.integrationRuns ||= [];
        draft.integrationRuns.unshift(sync);
        appendEvent(draft, context, 'MOCK_SYNC_COMPLETED', 'INTEGRATION_RUN', sync.id, 'Đồng bộ Google Sheets mô phỏng đã hoàn tất.');
        appendAudit(draft, context, 'MOCK_SYNC_COMPLETED', 'INTEGRATION_RUN', sync.id, 'Không gửi dữ liệu ra ngoài.');
        return { message: 'Đã chạy đồng bộ mô phỏng.' };
      },

      UPDATE_SETTINGS(draft, payload, context) {
        requireRole(context.actor, ['ADMIN']);
        const rules = {
          minimumVideoProgress: { min: 1, max: 100 },
          defaultPassingScore: { min: 1, max: 100 },
          remedialDeadlineDays: { min: 1, max: 60 },
        };
        const next = {};
        for (const [key, limits] of Object.entries(rules)) {
          if (payload[key] === undefined || payload[key] === '') continue;
          const value = Number(payload[key]);
          if (!Number.isInteger(value) || value < limits.min || value > limits.max) {
            throw new CommandError('INVALID_SETTING', `Giá trị ${key} không hợp lệ.`);
          }
          next[key] = value;
        }
        if (!Object.keys(next).length) throw new CommandError('INVALID_SETTING', 'Cần nhập ít nhất một thiết lập hợp lệ.');
        Object.assign(draft.settings, next);
        appendEvent(draft, context, 'DEMO_SETTINGS_UPDATED', 'SETTINGS', draft.settings.organizationId, 'Đã cập nhật quy tắc học tập của bản demo.');
        appendAudit(draft, context, 'DEMO_SETTINGS_UPDATED', 'SETTINGS', draft.settings.organizationId, Object.entries(next).map(([key, value]) => `${key}=${value}`).join(' · '));
        return { message: 'Đã lưu thiết lập demo.' };
      },

      REGISTER_VISITOR(draft, payload, context) {
        requireRole(context.actor, ['PUBLIC']);
        const name = String(payload.name || '').trim();
        const email = String(payload.email || '').trim().toLowerCase();
        const phone = String(payload.phone || '').replace(/\s+/g, '');
        const secret = String(payload.secret || '');
        if (!name || !email || !phone || !secret) throw new CommandError('REGISTRATION_REQUIRED', 'Cần nhập đầy đủ họ tên, email, số điện thoại và mật khẩu.');
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new CommandError('INVALID_EMAIL', 'Email không hợp lệ.');
        if (secret.length < 6) throw new CommandError('WEAK_SECRET', 'Mật khẩu cần có ít nhất 6 ký tự.');
        const identifiers = [email, phone];
        const duplicate = draft.users.some((user) => (user.identifiers || []).some((value) => identifiers.includes(String(value).toLowerCase())));
        if (duplicate) throw new CommandError('IDENTIFIER_EXISTS', 'Email hoặc số điện thoại đã được sử dụng.');
        const visitor = {
          id: uid('visitor'), role: 'VISITOR', name, identifiers, secret, status: 'ACTIVE', branchIds: [],
          savedProgramIds: [], registeredEventIds: [], createdAt: nowIso(),
        };
        draft.users.push(visitor);
        draft.notifications.unshift({ id: uid('notification'), userId: visitor.id, title: 'Chào mừng đến Lớp Tiếng Anh Cô Yến', body: 'Bạn có thể lưu chương trình, đăng ký sự kiện và theo dõi yêu cầu tư vấn tại đây.', link: '/tai-khoan', read: false, createdAt: nowIso() });
        appendEvent(draft, context, 'VISITOR_REGISTERED', 'USER', visitor.id, `${visitor.name} đã tạo tài khoản khách.`);
        appendAudit(draft, context, 'VISITOR_REGISTERED', 'USER', visitor.id, 'Tài khoản được tạo trong bộ nhớ trình duyệt.');
        return { message: 'Đăng ký tài khoản thành công.', actorId: visitor.id };
      },

      TOGGLE_PROGRAM_INTEREST(draft, payload, context) {
        requireRole(context.actor, ['VISITOR']);
        const program = required(draft.programs.find((item) => item.id === payload.programId && item.status === 'PUBLISHED'), 'PROGRAM_NOT_FOUND', 'Không tìm thấy chương trình.');
        context.actor.savedProgramIds ||= [];
        const index = context.actor.savedProgramIds.indexOf(program.id);
        const saved = index === -1;
        if (saved) context.actor.savedProgramIds.push(program.id);
        else context.actor.savedProgramIds.splice(index, 1);
        appendEvent(draft, context, saved ? 'PROGRAM_INTEREST_SAVED' : 'PROGRAM_INTEREST_REMOVED', 'PROGRAM', program.id, `${context.actor.name} · ${program.name}.`);
        return { message: saved ? 'Đã lưu chương trình quan tâm.' : 'Đã bỏ lưu chương trình.', saved };
      },

      REGISTER_PUBLIC_EVENT(draft, payload, context) {
        requireRole(context.actor, ['VISITOR']);
        const publicEvents = root.YC.publicContent?.published('publicEvents', draft) || [];
        const event = required(publicEvents.find((item) => item.id === payload.eventId) || draft.publicContent.events.find((item) => item.id === payload.eventId && item.status === 'PUBLISHED'), 'EVENT_NOT_FOUND', 'Không tìm thấy sự kiện.');
        context.actor.registeredEventIds ||= [];
        if (!context.actor.registeredEventIds.includes(event.id)) context.actor.registeredEventIds.push(event.id);
        draft.notifications.unshift({ id: uid('notification'), userId: context.actor.id, title: 'Đăng ký sự kiện thành công', body: event.title, link: '/tai-khoan', read: false, createdAt: nowIso() });
        appendEvent(draft, context, 'PUBLIC_EVENT_REGISTERED', 'EVENT', event.id, `${context.actor.name} · ${event.title}.`);
        return { message: 'Đã đăng ký sự kiện.', eventId: event.id };
      },

      CONTACT_LEAD(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        if (lead.status !== 'NEW') throw new CommandError('INVALID_LEAD_STATE', 'Khách hàng chỉ được liên hệ lần đầu từ trạng thái Mới.');
        lead.status = 'CONTACTED';
        lead.contactedAt = nowIso();
        draft.consultations.push({ id: uid('consultation'), leadId: lead.id, ownerId: context.actor.id, note: payload.note || 'Đã xác nhận nhu cầu.', occurredAt: nowIso() });
        appendEvent(draft, context, 'LEAD_CONTACTED', 'LEAD', lead.id, `${lead.name} đã được liên hệ.` , { learnerId: lead.learnerId });
        appendAudit(draft, context, 'LEAD_CONTACTED', 'LEAD', lead.id, payload.note || 'Xác nhận nhu cầu học.');
        return { message: 'Đã liên hệ và ghi nhận nhu cầu.' };
      },

      BOOK_PLACEMENT(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        if (lead.status !== 'CONTACTED') throw new CommandError('LEAD_NOT_CONTACTED', 'Cần liên hệ khách hàng trước khi đặt lịch kiểm tra đầu vào.');
        lead.status = 'PLACEMENT_BOOKED';
        const booking = { id: uid('placement-booking'), leadId: lead.id, learnerId: lead.learnerId, branchId: lead.branchId, startsAt: payload.startsAt, mode: payload.mode || 'OFFLINE', status: 'BOOKED', createdBy: context.actor.id };
        draft.placementBookings.push(booking);
        appendEvent(draft, context, 'PLACEMENT_BOOKED', 'PLACEMENT_BOOKING', booking.id, `Đặt lịch kiểm tra đầu vào cho ${lead.name}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'PLACEMENT_BOOKED', 'PLACEMENT_BOOKING', booking.id, `${payload.startsAt} · ${booking.mode}`);
        notifyRole(draft, 'ACADEMIC_MANAGER', 'Có lịch kiểm tra đầu vào mới', `${lead.name} cần được đánh giá đầu vào.`, '/app/academic/dashboard');
        return { message: 'Đã đặt lịch kiểm tra đầu vào.' };
      },

      RECORD_PLACEMENT(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const lead = findLead(draft, payload.leadId);
        const booking = latestForLead(draft.placementBookings, lead.id);
        if (!booking || booking.status !== 'BOOKED') throw new CommandError('PLACEMENT_NOT_BOOKED', 'Cần có lịch kiểm tra đầu vào hợp lệ trước khi ghi kết quả.');
        if (draft.placementResults.some((item) => item.leadId === lead.id)) throw new CommandError('PLACEMENT_EXISTS', 'Khách hàng đã có kết quả đầu vào.');
        booking.status = 'COMPLETED';
        const result = {
          id: uid('placement'),
          leadId: lead.id,
          learnerId: lead.learnerId,
          status: 'REVIEWED',
          frameworkLevel: payload.frameworkLevel,
          centerLevelId: payload.centerLevelId,
          skills: { ...payload.skills },
          recommendation: payload.recommendation,
          reviewedBy: context.actor.id,
          recordedAt: nowIso(),
        };
        draft.placementResults.push(result);
        appendEvent(draft, context, 'PLACEMENT_RECORDED', 'PLACEMENT_RESULT', result.id, `${lead.name}: ${result.frameworkLevel} · ${result.recommendation}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'PLACEMENT_RECORDED', 'PLACEMENT_RESULT', result.id, 'Kết quả đa kỹ năng đã được ghi nhận.');
        return { message: 'Đã ghi kết quả đầu vào.' };
      },

      RELEASE_PLACEMENT(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const lead = findLead(draft, payload.leadId);
        const result = latestForLead(draft.placementResults, lead.id);
        if (!result || result.status !== 'REVIEWED') throw new CommandError('PLACEMENT_NOT_REVIEWED', 'Kết quả đầu vào chưa được duyệt để phát hành.');
        result.status = 'RELEASED';
        result.releasedAt = nowIso();
        lead.status = 'PLACED';
        appendEvent(draft, context, 'PLACEMENT_RELEASED', 'PLACEMENT_RESULT', result.id, `Đã phát hành khuyến nghị ${result.recommendation}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'PLACEMENT_RELEASED', 'PLACEMENT_RESULT', result.id, 'Quản lý học thuật phê duyệt kết quả.');
        notifyRole(draft, 'ADMISSIONS', 'Kết quả đầu vào đã được phát hành', `${lead.name}: ${result.recommendation}.`, '/app/admissions/offers');
        return { message: 'Đã phát hành kết quả đầu vào.' };
      },

      CREATE_OFFER(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        const placement = latestForLead(draft.placementResults, lead.id);
        if (!placement || placement.status !== 'RELEASED') throw new CommandError('PLACEMENT_NOT_RELEASED', 'Cần kết quả đầu vào đã phát hành trước khi tạo gói đề xuất.');
        const packageItem = required(draft.packages.find((item) => item.id === payload.packageId), 'PACKAGE_NOT_FOUND', 'Không tìm thấy gói học.');
        const discount = Math.max(0, Number(payload.discount || 0));
        const offer = { id: uid('offer'), leadId: lead.id, learnerId: lead.learnerId, packageId: packageItem.id, listPrice: packageItem.price, discount, total: packageItem.price - discount, currency: packageItem.currency, status: 'DRAFT', createdBy: context.actor.id, createdAt: nowIso() };
        draft.offers.push(offer);
        lead.status = 'OFFERED';
        appendEvent(draft, context, 'OFFER_CREATED', 'OFFER', offer.id, `Gói đề xuất ${offer.total.toLocaleString('vi-VN')} ${offer.currency}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'OFFER_CREATED', 'OFFER', offer.id, `Giảm ${discount.toLocaleString('vi-VN')} ${offer.currency}.`);
        return { message: 'Đã tạo gói đề xuất nháp.' };
      },

      SEND_OFFER(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        const offer = required(latestForLead(draft.offers, lead.id), 'OFFER_NOT_FOUND', 'Không tìm thấy gói đề xuất.');
        if (offer.status !== 'DRAFT') throw new CommandError('INVALID_OFFER_STATE', 'Chỉ gói đề xuất nháp mới được gửi.');
        offer.status = 'SENT';
        offer.sentAt = nowIso();
        draft.outboundMessages.unshift({ id: uid('outbound'), channel: 'EMAIL', recipient: lead.email || lead.phone, template: 'OFFER_SENT', status: 'MOCKED', mode: 'MOCK', createdAt: nowIso() });
        appendEvent(draft, context, 'OFFER_SENT', 'OFFER', offer.id, `Đã gửi gói đề xuất mô phỏng cho ${lead.parentName || lead.name}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'OFFER_SENT_MOCK', 'OFFER', offer.id, 'Gửi ra ngoài ở chế độ mô phỏng, không gọi nhà cung cấp thật.');
        return { message: 'Đã gửi gói đề xuất ở chế độ mô phỏng.' };
      },

      ACCEPT_OFFER(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const lead = findLead(draft, payload.leadId);
        const offer = required(latestForLead(draft.offers, lead.id), 'OFFER_NOT_FOUND', 'Không tìm thấy gói đề xuất.');
        if (offer.status !== 'SENT') throw new CommandError('OFFER_NOT_SENT', 'Gói đề xuất phải được gửi trước khi ghi nhận chấp nhận.');
        offer.status = 'ACCEPTED';
        offer.acceptedAt = nowIso();
        appendEvent(draft, context, 'OFFER_ACCEPTED', 'OFFER', offer.id, `${lead.parentName || lead.name} đã chấp nhận gói đề xuất.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'OFFER_ACCEPTED', 'OFFER', offer.id, 'Tuyển sinh ghi nhận xác nhận trong bản mẫu.');
        notifyRole(draft, 'FINANCE', 'Gói đề xuất chờ xuất hóa đơn', `${lead.name} đã chấp nhận gói đề xuất.`, '/app/finance/invoices');
        return { message: 'Đã ghi nhận gói đề xuất được chấp nhận.' };
      },

      ISSUE_INVOICE(draft, payload, context) {
        requireRole(context.actor, ['FINANCE']);
        const lead = findLead(draft, payload.leadId);
        const offer = required(latestForLead(draft.offers, lead.id), 'OFFER_NOT_FOUND', 'Không tìm thấy gói đề xuất.');
        if (offer.status !== 'ACCEPTED') throw new CommandError('OFFER_NOT_ACCEPTED', 'Gói đề xuất chưa được chấp nhận.');
        const invoice = { id: uid('invoice'), leadId: lead.id, learnerId: lead.learnerId, offerId: offer.id, amount: offer.total, currency: offer.currency, status: 'ISSUED', mode: 'MOCK', issuedAt: nowIso(), dueAt: new Date(new Date(nowIso()).getTime() + 3 * 86400000).toISOString() };
        draft.invoices.push(invoice);
        appendEvent(draft, context, 'INVOICE_ISSUED', 'INVOICE', invoice.id, `Hóa đơn mô phỏng ${invoice.amount.toLocaleString('vi-VN')} ${invoice.currency}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'MOCK_INVOICE_ISSUED', 'INVOICE', invoice.id, 'Hóa đơn bản mẫu, không phải chứng từ tài chính thật.');
        return { message: 'Đã phát hành hóa đơn mô phỏng.' };
      },

      RECORD_MOCK_PAYMENT(draft, payload, context) {
        requireRole(context.actor, ['FINANCE']);
        const lead = findLead(draft, payload.leadId);
        const invoice = required(latestForLead(draft.invoices, lead.id), 'INVOICE_NOT_FOUND', 'Không tìm thấy hóa đơn.');
        if (invoice.status !== 'ISSUED') throw new CommandError('INVOICE_NOT_PAYABLE', 'Hóa đơn không ở trạng thái chờ thanh toán.');
        invoice.status = 'PAID';
        invoice.paidAt = nowIso();
        const payment = { id: uid('payment'), invoiceId: invoice.id, leadId: lead.id, learnerId: lead.learnerId, amount: invoice.amount, currency: invoice.currency, reference: payload.reference || uid('MOCK'), provider: 'DEMO_LEDGER', mode: 'MOCK', status: 'PAID', paidAt: nowIso() };
        draft.payments.push(payment);
        lead.status = 'WON';
        appendEvent(draft, context, 'PAYMENT_RECORDED', 'PAYMENT', payment.id, `Đã ghi nhận thanh toán mô phỏng cho ${lead.name}.`, { learnerId: lead.learnerId });
        appendAudit(draft, context, 'MOCK_PAYMENT_RECORDED', 'PAYMENT', payment.id, `${payment.reference} · Sổ mô phỏng.`);
        notifyRole(draft, 'STUDENT_SERVICE', 'Học viên đã đủ điều kiện xếp lớp', `${lead.name} đã hoàn tất thanh toán mô phỏng.`, '/app/service/allocation');
        return { message: 'Đã ghi nhận thanh toán mô phỏng.' };
      },

      ALLOCATE_CLASS(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        const lead = findLead(draft, payload.leadId);
        const classItem = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        const activeCount = draft.enrollments.filter((item) => item.classId === classItem.id && item.status === 'ACTIVE').length;
        if (activeCount >= classItem.capacity || classItem.status === 'FULL') {
          const alternatives = draft.classes
            .filter((item) => item.id !== classItem.id && item.courseVersionId === classItem.courseVersionId && ['OPEN', 'ACTIVE'].includes(item.status))
            .map((item) => ({ classId: item.id, name: item.name, seats: item.capacity - draft.enrollments.filter((enrollment) => enrollment.classId === item.id && enrollment.status === 'ACTIVE').length, scheduleLabel: item.scheduleLabel }))
            .filter((item) => item.seats > 0)
            .sort((a, b) => b.seats - a.seats);
          throw new CommandError('NO_SEAT', 'Lớp đã hết chỗ; cần chọn phương án thay thế.', { alternatives });
        }
        const learner = required(draft.learners.find((item) => item.id === lead.learnerId), 'LEARNER_NOT_FOUND', 'Khách hàng chưa có hồ sơ học viên.');
        const paid = draft.payments.some((item) => item.leadId === lead.id && item.status === 'PAID');
        if (!paid) throw new CommandError('PAYMENT_REQUIRED', 'Cần ghi nhận thanh toán trước khi xếp lớp.');
        if (draft.enrollments.some((item) => item.learnerId === learner.id && item.status === 'ACTIVE')) throw new CommandError('ACTIVE_ENROLLMENT_EXISTS', 'Học viên đã có ghi danh đang hoạt động.');
        const enrollment = { id: uid('enrollment'), learnerId: learner.id, classId: classItem.id, courseVersionId: classItem.courseVersionId, status: 'ACTIVE', startsAt: nowIso(), endsAt: null, allocatedBy: context.actor.id };
        draft.enrollments.push(enrollment);
        learner.classId = classItem.id;
        learner.branchId = classItem.branchId;
        learner.status = 'ACTIVE';
        appendEvent(draft, context, 'LEARNER_ALLOCATED', 'ENROLLMENT', enrollment.id, `${learner.name} vào lớp ${classItem.name}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'CLASS_ALLOCATED', 'ENROLLMENT', enrollment.id, `Đã xác nhận thanh toán · ${classItem.code}.`);
        notifyRole(draft, 'ACADEMIC_MANAGER', 'Lớp cần gán giáo viên', `${classItem.name} có học viên mới.`, '/app/academic/assignments');
        return { message: 'Đã xếp lớp và tạo ghi danh.' };
      },

      TRANSFER_ENROLLMENT(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        if (!String(payload.reason || '').trim()) throw new CommandError('REASON_REQUIRED', 'Chuyển lớp cần có lý do.');
        const current = required(draft.enrollments.find((item) => item.learnerId === payload.learnerId && item.status === 'ACTIVE'), 'ACTIVE_ENROLLMENT_NOT_FOUND', 'Không tìm thấy ghi danh đang hoạt động.');
        const nextClass = required(draft.classes.find((item) => item.id === payload.toClassId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp đích.');
        const occupied = draft.enrollments.filter((item) => item.classId === nextClass.id && item.status === 'ACTIVE').length;
        if (occupied >= nextClass.capacity) throw new CommandError('NO_SEAT', 'Lớp đích đã hết chỗ.', { alternatives: [] });
        current.status = 'TRANSFERRED';
        current.endsAt = nowIso();
        current.transferReason = payload.reason.trim();
        const replacement = { id: uid('enrollment'), learnerId: payload.learnerId, classId: nextClass.id, courseVersionId: nextClass.courseVersionId, status: 'ACTIVE', startsAt: nowIso(), endsAt: null, transferredFromId: current.id, allocatedBy: context.actor.id };
        draft.enrollments.push(replacement);
        const learner = draft.learners.find((item) => item.id === payload.learnerId);
        learner.classId = nextClass.id;
        learner.branchId = nextClass.branchId;
        appendEvent(draft, context, 'ENROLLMENT_TRANSFERRED', 'ENROLLMENT', replacement.id, `${learner.name} chuyển sang ${nextClass.name}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'ENROLLMENT_TRANSFERRED', 'ENROLLMENT', replacement.id, payload.reason.trim());
        return { message: 'Đã chuyển lớp và giữ nguyên lịch sử ghi danh cũ.' };
      },

      CREATE_RENEWAL(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        const promotion = draft.promotionDecisions.find((item) => item.learnerId === learner.id && item.decision === 'PROMOTE' && item.status === 'FINAL');
        if (!promotion) throw new CommandError('PROMOTION_REQUIRED', 'Cần quyết định lên lớp đã chốt trước khi tạo gia hạn.');
        const packageItem = required(draft.packages.find((item) => item.id === payload.packageId), 'PACKAGE_NOT_FOUND', 'Không tìm thấy gói học.');
        const renewal = { id: uid('renewal'), learnerId: learner.id, nextCourseVersionId: promotion.nextCourseVersionId, packageId: packageItem.id, status: 'OFFERED', outcome: promotion.decision, nextGoal: 'Tiếp tục A2.2 và tăng sự tự tin khi nói', offeredAt: nowIso(), ownerId: context.actor.id };
        draft.renewals.push(renewal);
        appendEvent(draft, context, 'RENEWAL_OFFERED', 'RENEWAL', renewal.id, `Đã tạo gói gia hạn cho ${learner.name}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'RENEWAL_OFFERED', 'RENEWAL', renewal.id, `Khóa tiếp theo: ${promotion.nextCourseVersionId}.`);
        return { message: 'Đã tạo gói gia hạn.' };
      },

      ACCEPT_RENEWAL(draft, payload, context) {
        requireRole(context.actor, ['ADMISSIONS']);
        const renewal = required(draft.renewals.find((item) => item.learnerId === payload.learnerId && item.status === 'OFFERED'), 'RENEWAL_NOT_FOUND', 'Không tìm thấy gói gia hạn đang chờ.');
        renewal.status = 'ACCEPTED';
        renewal.acceptedAt = nowIso();
        appendEvent(draft, context, 'RENEWAL_ACCEPTED', 'RENEWAL', renewal.id, 'Phụ huynh đã chấp nhận lộ trình tiếp theo.', { learnerId: renewal.learnerId });
        appendAudit(draft, context, 'RENEWAL_ACCEPTED', 'RENEWAL', renewal.id, 'Tuyển sinh ghi nhận xác nhận trong bản mẫu.');
        return { message: 'Đã hoàn tất gia hạn.' };
      },

      REQUEST_CREATE_COURSE(draft, payload, context) {
        const branchId = payload.branchId || context.actor.branchIds?.[0];
        const proposal = {
          provisionalId: payload.provisionalId || uid('course-proposed'),
          code: String(payload.code || '').trim().toUpperCase(),
          name: String(payload.name || '').trim(),
          programId: payload.programId,
          levelId: payload.levelId,
          ageBand: payload.ageBand,
          modes: Array.isArray(payload.modes) ? payload.modes : [payload.mode || 'OFFLINE'],
          description: String(payload.description || '').trim(),
          branchId,
          branchIds: Array.isArray(payload.branchIds) ? payload.branchIds : branchId ? [branchId] : [],
          status: 'DRAFT',
          version: 1,
        };
        const input = {
          resourceType: 'COURSE', operation: 'CREATE', baseVersion: 0,
          proposedSnapshot: proposal, reason: payload.reason,
        };
        if (context.actor.role === 'ADMIN') return applyAdminDirectChange(draft, input, context);
        return handlers.SUBMIT_CHANGE_REQUEST(draft, input, context);
      },

      REQUEST_UPDATE_COURSE(draft, payload, context) {
        const course = required(draft.courses.find((item) => item.id === payload.courseId), 'COURSE_NOT_FOUND', 'Không tìm thấy khóa học.');
        const branchId = payload.branchId || course.branchIds?.[0] || context.actor.branchIds?.[0];
        const proposal = { ...payload, branchId };
        delete proposal.courseId;
        delete proposal.reason;
        return handlers.SUBMIT_CHANGE_REQUEST(draft, {
          resourceType: 'COURSE', operation: 'UPDATE', resourceId: course.id, baseVersion: course.version,
          proposedSnapshot: proposal, reason: payload.reason,
        }, context);
      },

      CREATE_COURSE_VERSION(draft, payload, context) {
        requirePermission(draft, context, 'course.review');
        const course = required(draft.courses.find((item) => item.id === payload.courseId), 'COURSE_NOT_FOUND', 'Không tìm thấy khóa học.');
        const base = required(draft.courseVersions.find((item) => item.id === payload.baseVersionId && item.courseId === course.id), 'BASE_VERSION_NOT_FOUND', 'Không tìm thấy phiên bản gốc của khóa học.');
        const nextNumber = Math.max(0, ...draft.courseVersions.filter((item) => item.courseId === course.id).map((item) => Number(item.version || 0))) + 1;
        const version = {
          ...clone(base), id: uid('course-version'), version: nextNumber, recordVersion: 1,
          title: String(payload.title || `${course.name} · v${nextNumber}`).trim(),
          baseVersionId: base.id, changeSummary: String(payload.changeSummary || '').trim(),
          status: 'DRAFT', immutable: false, publishedAt: null, publishedBy: null,
          createdAt: nowIso(), createdBy: context.actor.id,
        };
        draft.courseVersions.push(version);

        const unitMap = new Map();
        const lessonMap = new Map();
        draft.units.filter((item) => item.courseVersionId === base.id).forEach((item) => {
          const cloned = { ...clone(item), id: uid('unit'), courseVersionId: version.id };
          unitMap.set(item.id, cloned.id);
          draft.units.push(cloned);
        });
        const baseUnitIds = [...unitMap.keys()];
        draft.lessonTemplates.filter((item) => baseUnitIds.includes(item.unitId)).forEach((item) => {
          const cloned = { ...clone(item), id: uid('lesson'), unitId: unitMap.get(item.unitId), version: 1, status: 'DRAFT' };
          lessonMap.set(item.id, cloned.id);
          draft.lessonTemplates.push(cloned);
        });
        const baseLessonIds = [...lessonMap.keys()];
        draft.learningItems.filter((item) => baseLessonIds.includes(item.lessonTemplateId)).forEach((item) => {
          draft.learningItems.push({ ...clone(item), id: uid('learning-item'), lessonTemplateId: lessonMap.get(item.lessonTemplateId), status: 'DRAFT' });
        });
        draft.assessments.filter((item) => item.courseVersionId === base.id || baseLessonIds.includes(item.lessonTemplateId)).forEach((item) => {
          draft.assessments.push({
            ...clone(item), id: uid('assessment'),
            courseVersionId: item.courseVersionId === base.id ? version.id : item.courseVersionId,
            lessonTemplateId: lessonMap.get(item.lessonTemplateId) || item.lessonTemplateId,
            status: 'DRAFT',
          });
        });
        appendEvent(draft, context, 'COURSE_VERSION_FORKED', 'COURSE_VERSION', version.id, `${base.title} → v${nextNumber}.`);
        appendAudit(draft, context, 'COURSE_VERSION_FORKED', 'COURSE_VERSION', version.id, version.changeSummary || 'Tạo bản nháp từ phiên bản đã công bố.');
        return { message: 'Đã tạo phiên bản khóa học mới để chỉnh sửa.', courseVersionId: version.id };
      },

      SUBMIT_COURSE_VERSION(draft, payload, context) {
        requirePermission(draft, context, 'course.review');
        const version = required(draft.courseVersions.find((item) => item.id === payload.courseVersionId), 'COURSE_VERSION_NOT_FOUND', 'Không tìm thấy phiên bản khóa học.');
        if (version.immutable || version.status !== 'DRAFT') throw new CommandError('INVALID_COURSE_VERSION_STATE', 'Chỉ bản nháp chưa khóa mới có thể gửi duyệt.');
        const validation = root.YC.selectors.coursePublishValidation(draft, version.id);
        if (!validation.valid) throw new CommandError('COURSE_VERSION_INVALID', 'Phiên bản khóa học chưa đủ điều kiện gửi duyệt.', { evidence: validation });
        version.status = 'SUBMITTED';
        version.submittedAt = nowIso();
        version.submittedBy = context.actor.id;
        version.submitReason = String(payload.reason || '').trim();
        appendEvent(draft, context, 'COURSE_VERSION_SUBMITTED', 'COURSE_VERSION', version.id, `${version.title} đang chờ phát hành.`);
        appendAudit(draft, context, 'COURSE_VERSION_SUBMITTED', 'COURSE_VERSION', version.id, version.submitReason || 'Đã vượt qua kiểm tra cấu trúc.');
        return { message: 'Đã gửi phiên bản khóa học để phát hành.', validation };
      },

      ARCHIVE_COURSE(draft, payload, context) {
        requirePermission(draft, context, 'course.request_archive');
        const course = required(draft.courses.find((item) => item.id === payload.courseId), 'COURSE_NOT_FOUND', 'Không tìm thấy khóa học.');
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Lưu trữ khóa học cần có lý do.');
        const versionIds = draft.courseVersions.filter((item) => item.courseId === course.id).map((item) => item.id);
        const inUse = draft.classes.some((item) => versionIds.includes(item.courseVersionId));
        course.status = inUse ? 'RETIRED' : 'ARCHIVED';
        course.version = Number(course.version || 0) + 1;
        course.archivedAt = nowIso();
        course.archivedBy = context.actor.id;
        appendEvent(draft, context, 'COURSE_ARCHIVED', 'COURSE', course.id, `${course.name} → ${course.status}.`);
        appendAudit(draft, context, 'COURSE_ARCHIVED', 'COURSE', course.id, reason);
        return { message: inUse ? 'Đã ngừng mở mới; lịch sử lớp vẫn được giữ.' : 'Đã lưu trữ khóa học.', status: course.status };
      },

      REQUEST_CREATE_CLASS(draft, payload, context) {
        const proposal = {
          provisionalId: payload.provisionalId || uid('class-proposed'),
          code: String(payload.code || '').trim().toUpperCase(), name: String(payload.name || '').trim(),
          branchId: payload.branchId, courseVersionId: payload.courseVersionId,
          ageBand: payload.ageBand, mode: payload.mode || 'OFFLINE',
          capacity: Number(payload.capacity || 0), minCapacity: Number(payload.minCapacity || 1),
          room: String(payload.room || '').trim(), meetingUrl: String(payload.meetingUrl || '').trim(),
          startDate: payload.startDate, endDate: payload.endDate,
          enrollmentStartsAt: payload.enrollmentStartsAt || null, enrollmentEndsAt: payload.enrollmentEndsAt || payload.startDate || null,
          timezone: payload.timezone || 'Asia/Ho_Chi_Minh', recurrence: Array.isArray(payload.recurrence) ? payload.recurrence : [],
          durationMinutes: Number(payload.durationMinutes || 90), waitlistPolicy: payload.waitlistPolicy || 'QUEUE',
          remedialPolicySnapshot: clone(draft.courseVersions.find((item) => item.id === payload.courseVersionId)?.remedialPolicy || {}),
          status: 'DRAFT', version: 1,
        };
        const input = {
          resourceType: 'CLASS', operation: 'CREATE', baseVersion: 0,
          proposedSnapshot: proposal, reason: payload.reason,
        };
        if (context.actor.role === 'ADMIN') return applyAdminDirectChange(draft, input, context);
        return handlers.SUBMIT_CHANGE_REQUEST(draft, input, context);
      },

      REQUEST_UPDATE_CLASS(draft, payload, context) {
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        if (payload.courseVersionId && payload.courseVersionId !== cohort.courseVersionId && draft.sessions.some((item) => item.classId === cohort.id)) {
          throw new CommandError('COURSE_VERSION_PINNED', 'Không thể đổi phiên bản khóa học sau khi lớp đã có buổi học.');
        }
        const proposal = { ...payload };
        delete proposal.classId;
        delete proposal.reason;
        return handlers.SUBMIT_CHANGE_REQUEST(draft, {
          resourceType: 'CLASS', operation: 'UPDATE', resourceId: cohort.id, baseVersion: cohort.version,
          proposedSnapshot: proposal, reason: payload.reason,
        }, context);
      },

      OPEN_CLASS(draft, payload, context) {
        requirePermission(draft, context, 'class.request_update');
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        if (cohort.status !== 'DRAFT') throw new CommandError('INVALID_CLASS_STATE', 'Chỉ lớp nháp đã duyệt mới có thể mở ghi danh.');
        const version = draft.courseVersions.find((item) => item.id === cohort.courseVersionId);
        if (!version || version.status !== 'PUBLISHED' || !version.immutable) throw new CommandError('COURSE_VERSION_NOT_PUBLISHED', 'Lớp chỉ được mở với phiên bản khóa học đã công bố.');
        if (!draft.timetableRules.some((item) => item.classId === cohort.id && item.status !== 'INACTIVE')) throw new CommandError('TIMETABLE_REQUIRED', 'Cần lịch định kỳ trước khi mở lớp.');
        const createdSessions = generateClassSessions(draft, cohort);
        cohort.status = 'OPEN';
        cohort.openedAt = nowIso();
        cohort.openedBy = context.actor.id;
        cohort.version = Number(cohort.version || 0) + 1;
        appendEvent(draft, context, 'CLASS_OPENED', 'CLASS', cohort.id, `${cohort.name} · sinh ${createdSessions} buổi học.`);
        appendAudit(draft, context, 'CLASS_OPENED', 'CLASS', cohort.id, String(payload.reason || 'Đã kiểm tra khóa học và lịch định kỳ.'));
        return { message: `Đã mở lớp và sinh ${createdSessions} buổi học.`, createdSessions };
      },

      MARK_CLASS_READY(draft, payload, context) {
        requirePermission(draft, context, 'class.request_update');
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        if (cohort.status !== 'OPEN') throw new CommandError('INVALID_CLASS_STATE', 'Chỉ lớp đang mở mới có thể chuyển sang Sẵn sàng.');
        const readiness = root.YC.selectors.classReadiness(draft, cohort.id);
        const blocking = readiness.errors.filter((item) => item.code !== 'MINIMUM_CAPACITY');
        const minimumError = readiness.errors.find((item) => item.code === 'MINIMUM_CAPACITY');
        const overrideReason = String(payload.overrideReason || '').trim();
        if (blocking.length || (minimumError && !overrideReason)) throw new CommandError('CLASS_NOT_READY', 'Lớp chưa đủ điều kiện sẵn sàng.', { evidence: readiness });
        if (minimumError) cohort.readinessOverride = { reason: overrideReason, approvedBy: context.actor.id, approvedAt: nowIso(), rule: minimumError.code };
        cohort.status = 'READY';
        cohort.readyAt = nowIso();
        cohort.version = Number(cohort.version || 0) + 1;
        appendEvent(draft, context, 'CLASS_READY', 'CLASS', cohort.id, minimumError ? 'Sẵn sàng theo ngoại lệ sức chứa.' : 'Đã đạt đủ điều kiện sẵn sàng.');
        appendAudit(draft, context, 'CLASS_READY', 'CLASS', cohort.id, overrideReason || 'Đủ khóa học, lịch, giáo viên, phòng và sức chứa.');
        return { message: 'Đã chuyển lớp sang trạng thái Sẵn sàng.', readiness, overridden: Boolean(minimumError) };
      },

      ARCHIVE_CLASS(draft, payload, context) {
        requirePermission(draft, context, 'class.request_archive');
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Lưu trữ lớp cần có lý do.');
        cohort.status = 'ARCHIVED';
        cohort.archivedAt = nowIso();
        cohort.archivedBy = context.actor.id;
        cohort.version = Number(cohort.version || 0) + 1;
        appendEvent(draft, context, 'CLASS_ARCHIVED', 'CLASS', cohort.id, cohort.name);
        appendAudit(draft, context, 'CLASS_ARCHIVED', 'CLASS', cohort.id, reason);
        return { message: 'Đã lưu trữ lớp và giữ nguyên lịch sử ghi danh, buổi học.' };
      },

      CREATE_CONTENT_DRAFT(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'ACADEMIC_MANAGER']);
        const version = required(draft.courseVersions.find((item) => item.id === payload.courseVersionId), 'COURSE_VERSION_NOT_FOUND', 'Không tìm thấy phiên bản khóa học.');
        const lesson = required(draft.lessonTemplates.find((item) => item.id === payload.lessonTemplateId), 'LESSON_NOT_FOUND', 'Không tìm thấy bài học.');
        const unit = required(draft.units.find((item) => item.id === lesson.unitId && item.courseVersionId === version.id), 'LESSON_COURSE_MISMATCH', 'Bài học không thuộc phiên bản khóa học đã chọn.');
        const title = String(payload.title || '').trim();
        if (!title) throw new CommandError('TITLE_REQUIRED', 'Cần nhập tên nội dung.');
        const draftItem = {
          id: uid('content-draft'),
          courseVersionId: version.id,
          unitId: unit.id,
          lessonTemplateId: lesson.id,
          type: payload.type || 'PRACTICE',
          title,
          status: 'DRAFT',
          createdBy: context.actor.id,
          createdAt: nowIso(),
        };
        draft.contentDrafts ||= [];
        draft.contentDrafts.unshift(draftItem);
        appendEvent(draft, context, 'CONTENT_DRAFT_CREATED', 'CONTENT_DRAFT', draftItem.id, `${title} · ${version.title}.`);
        appendAudit(draft, context, 'CONTENT_DRAFT_CREATED', 'CONTENT_DRAFT', draftItem.id, `Bài ${lesson.title}.`);
        return { message: 'Đã tạo bản nháp nội dung.', contentDraftId: draftItem.id };
      },

      PUBLISH_COURSE_VERSION(draft, payload, context) {
        const version = required(draft.courseVersions.find((item) => item.id === payload.courseVersionId), 'COURSE_VERSION_NOT_FOUND', 'Không tìm thấy phiên bản khóa học.');
        if (version.status === 'PUBLISHED' && version.immutable) throw new CommandError('COURSE_VERSION_IMMUTABLE', 'Phiên bản khóa học đã công bố thì không thể sửa.');
        requirePermission(draft, context, 'course.publish');
        if (!['SUBMITTED', 'APPROVED'].includes(version.status)) throw new CommandError('INVALID_COURSE_VERSION_STATE', 'Phiên bản khóa học chưa sẵn sàng để công bố.');
        const validation = root.YC.selectors.coursePublishValidation(draft, version.id);
        if (!validation.valid) throw new CommandError('COURSE_VERSION_INVALID', 'Phiên bản khóa học chưa đủ điều kiện công bố.', { evidence: validation });
        version.status = 'PUBLISHED';
        version.immutable = true;
        version.publishedAt = nowIso();
        version.publishedBy = context.actor.id;
        version.recordVersion = Number(version.recordVersion || 0) + 1;
        appendEvent(draft, context, 'COURSE_VERSION_PUBLISHED', 'COURSE_VERSION', version.id, `${version.title} đã được công bố.`);
        appendAudit(draft, context, 'COURSE_VERSION_PUBLISHED', 'COURSE_VERSION', version.id, String(payload.reason || 'Đã khóa bản chụp chương trình học.'));
        return { message: 'Đã công bố phiên bản khóa học.' };
      },

      PROPOSE_TEACHER_ASSIGNMENT(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const profile = required(draft.teacherProfiles.find((item) => item.userId === payload.teacherId), 'TEACHER_NOT_FOUND', 'Không tìm thấy hồ sơ giáo viên.');
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        const evidence = root.YC.selectors.teacherEligibility(draft, payload.teacherId, cohort.id, Number(payload.workloadMinutes || 720));
        if (!evidence.eligible) throw new CommandError('TEACHER_INELIGIBLE', 'Giáo viên không đạt điều kiện bắt buộc.', { evidence });
        if (draft.teacherAssignments.some((item) => item.classId === cohort.id && ['PROPOSED', 'ACCEPTED', 'ACTIVE'].includes(item.status))) {
          throw new CommandError('CLASS_ALREADY_ASSIGNED', 'Lớp đã có phân công giáo viên đang hiệu lực.');
        }
        const assignment = {
          id: uid('teacher-assignment'),
          teacherProfileId: profile.id,
          classId: cohort.id,
          role: 'PRIMARY',
          startsAt: nowIso(),
          endsAt: new Date(new Date(nowIso()).getTime() + 120 * 86400000).toISOString(),
          workloadMinutes: Number(payload.workloadMinutes || 720),
          status: 'PROPOSED',
          proposedAt: nowIso(),
          assignedBy: context.actor.id,
          eligibilityEvidence: evidence,
        };
        draft.teacherAssignments.push(assignment);
        appendEvent(draft, context, 'TEACHER_ASSIGNMENT_PROPOSED', 'TEACHER_ASSIGNMENT', assignment.id, `${draft.users.find((item) => item.id === payload.teacherId)?.name} được đề xuất cho ${cohort.name}.`);
        appendAudit(draft, context, 'TEACHER_ASSIGNMENT_PROPOSED', 'TEACHER_ASSIGNMENT', assignment.id, 'Đã đạt mọi điều kiện bắt buộc.');
        draft.notifications.unshift({ id: uid('notification'), userId: payload.teacherId, title: 'Có đề xuất nhận lớp mới', body: cohort.name, link: '/app/teacher/dashboard', read: false, createdAt: nowIso() });
        return { message: 'Đã gửi đề xuất phân công cho giáo viên.', evidence };
      },

      ACCEPT_TEACHER_ASSIGNMENT(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const profile = required(draft.teacherProfiles.find((item) => item.userId === context.actor.id), 'TEACHER_NOT_FOUND', 'Không tìm thấy hồ sơ giáo viên.');
        const assignment = required(draft.teacherAssignments.find((item) => item.teacherProfileId === profile.id && item.classId === payload.classId && item.status === 'PROPOSED'), 'ASSIGNMENT_NOT_FOUND', 'Không tìm thấy đề xuất phân công.');
        assignment.status = 'ACTIVE';
        assignment.acceptedAt = nowIso();
        draft.sessionAssignments.push(...draft.sessions.filter((item) => item.classId === assignment.classId).map((session) => ({ id: uid('session-assignment'), sessionId: session.id, teacherProfileId: profile.id, role: assignment.role, status: 'ACTIVE', startsAt: assignment.startsAt, endsAt: assignment.endsAt })));
        appendEvent(draft, context, 'TEACHER_ASSIGNMENT_ACCEPTED', 'TEACHER_ASSIGNMENT', assignment.id, 'Giáo viên đã nhận lớp.');
        appendAudit(draft, context, 'TEACHER_ASSIGNMENT_ACTIVATED', 'TEACHER_ASSIGNMENT', assignment.id, 'Quyền lớp có hiệu lực theo thời hạn phân công.');
        notifyRole(draft, 'ACADEMIC_MANAGER', 'Giáo viên đã nhận lớp', `${context.actor.name} đã nhận phân công.`, '/app/academic/assignments');
        return { message: 'Đã nhận lớp và kích hoạt quyền theo phân công.' };
      },

      REQUEST_CREATE_SESSION(draft, payload, context) {
        const cohort = required(draft.classes.find((item) => item.id === payload.classId), 'CLASS_NOT_FOUND', 'Không tìm thấy lớp.');
        const proposal = {
          provisionalId: payload.provisionalId || uid('session-proposed'), classId: cohort.id,
          lessonTemplateId: payload.lessonTemplateId, startsAt: payload.startsAt, endsAt: payload.endsAt,
          room: String(payload.room || cohort.room || '').trim(), mode: payload.mode || cohort.mode,
          status: 'PLANNED', attendanceFinalized: false, version: 1,
        };
        const validation = root.YC.selectors.sessionValidation(draft, proposal);
        if (!validation.valid) throw new CommandError(validation.errors[0].code, validation.errors[0].message, { evidence: validation });
        const input = {
          resourceType: 'SESSION', operation: 'CREATE', baseVersion: 0,
          proposedSnapshot: proposal, reason: payload.reason,
        };
        if (context.actor.role === 'ADMIN') return applyAdminDirectChange(draft, input, context);
        return handlers.SUBMIT_CHANGE_REQUEST(draft, input, context);
      },

      REQUEST_RESCHEDULE_SESSION(draft, payload, context) {
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (['IN_PROGRESS', 'COMPLETED'].includes(session.status) || session.actualStartsAt) throw new CommandError('SESSION_ALREADY_STARTED', 'Không thể đổi lịch sau khi buổi học đã bắt đầu.');
        const proposal = {
          startsAt: payload.startsAt, endsAt: payload.endsAt,
          room: String(payload.room || session.room || '').trim(), mode: payload.mode || session.mode,
        };
        const validation = root.YC.selectors.sessionValidation(draft, { ...session, ...proposal, excludeSessionId: session.id });
        if (!validation.valid) throw new CommandError(validation.errors[0].code, validation.errors[0].message, { evidence: validation });
        return handlers.SUBMIT_CHANGE_REQUEST(draft, {
          resourceType: 'SESSION', operation: 'RESCHEDULE', resourceId: session.id, baseVersion: session.version,
          proposedSnapshot: proposal, reason: payload.reason,
        }, context);
      },

      REQUEST_CANCEL_SESSION(draft, payload, context) {
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (session.status === 'CANCELLED') throw new CommandError('SESSION_ALREADY_CANCELLED', 'Buổi học đã được hủy trước đó.');
        return handlers.SUBMIT_CHANGE_REQUEST(draft, {
          resourceType: 'SESSION', operation: 'CANCEL', resourceId: session.id, baseVersion: session.version,
          proposedSnapshot: {}, reason: payload.reason,
        }, context);
      },

      CONFIRM_SESSION(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER', 'STUDENT_SERVICE']);
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (session.status !== 'PLANNED') throw new CommandError('INVALID_SESSION_STATE', 'Chỉ buổi ở trạng thái Đã lên lịch mới được xác nhận.');
        const cohort = draft.classes.find((item) => item.id === session.classId);
        const conflicts = root.YC.selectors.scheduleConflicts(draft, { teacherId: payload.teacherId, branchId: cohort.branchId, room: session.room, startsAt: session.startsAt, endsAt: session.endsAt });
        if (conflicts.length) throw new CommandError('SCHEDULE_CONFLICT', 'Lịch bị trùng giáo viên hoặc phòng.', { evidence: conflicts });
        session.status = 'CONFIRMED';
        appendEvent(draft, context, 'SESSION_CONFIRMED', 'SESSION', session.id, 'Buổi học đã được xác nhận.');
        appendAudit(draft, context, 'SESSION_CONFIRMED', 'SESSION', session.id, 'Đã vượt qua kiểm tra trùng lịch.');
        return { message: 'Đã xác nhận buổi học.' };
      },

      MARK_SESSION_READY(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        const profile = draft.teacherProfiles.find((item) => item.userId === context.actor.id);
        const assigned = profile && draft.teacherAssignments.some((item) => item.teacherProfileId === profile.id && item.classId === session.classId && item.status === 'ACTIVE');
        if (!assigned) throw new CommandError('SESSION_NOT_ASSIGNED', 'Giáo viên chưa được phân công vào lớp này.');
        const plan = required(draft.lessonPlans.find((item) => item.sessionId === session.id), 'LESSON_PLAN_NOT_FOUND', 'Buổi học chưa có giáo án.');
        plan.adaptations = payload.adaptations || plan.adaptations;
        plan.readiness = 'READY';
        plan.readyAt = nowIso();
        appendEvent(draft, context, 'SESSION_READY', 'LESSON_PLAN', plan.id, 'Giáo viên xác nhận sẵn sàng trước buổi học.');
        appendAudit(draft, context, 'SESSION_READY', 'LESSON_PLAN', plan.id, `${plan.adaptations.length} điều chỉnh.`);
        return { message: 'Đã xác nhận giáo án sẵn sàng.' };
      },

      START_SESSION(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        const plan = draft.lessonPlans.find((item) => item.sessionId === session.id);
        if (!plan || plan.readiness !== 'READY') throw new CommandError('SESSION_NOT_READY', 'Cần xác nhận giáo án sẵn sàng trước khi bắt đầu.');
        if (session.status !== 'CONFIRMED') throw new CommandError('INVALID_SESSION_STATE', 'Chỉ buổi đã xác nhận mới được bắt đầu.');
        const enrollments = draft.enrollments.filter((item) => item.classId === session.classId && item.status === 'ACTIVE');
        const makeUpBookings = draft.makeUpBookings.filter((item) => (item.targetSessionId || item.sessionId) === session.id && ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status));
        session.rosterSnapshot = {
          capturedAt: nowIso(),
          learnerIds: [...new Set([...enrollments.map((item) => item.learnerId), ...makeUpBookings.map((item) => item.learnerId)])],
          enrollmentIds: enrollments.map((item) => item.id),
          makeUpBookingIds: makeUpBookings.map((item) => item.id),
        };
        session.status = 'IN_PROGRESS';
        session.actualStartsAt = nowIso();
        session.version = Number(session.version || 0) + 1;
        appendEvent(draft, context, 'SESSION_STARTED', 'SESSION', session.id, 'Giáo viên xác nhận có mặt và bắt đầu buổi học.');
        appendAudit(draft, context, 'TEACHER_CHECKED_IN', 'SESSION', session.id, context.actor.name);
        return { message: 'Buổi học đã bắt đầu.' };
      },

      COMPLETE_SESSION(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (session.status !== 'IN_PROGRESS') throw new CommandError('INVALID_SESSION_STATE', 'Buổi học phải đang diễn ra trước khi hoàn tất.');
        const taughtItemIds = payload.taughtItemIds || [];
        if (!taughtItemIds.length) throw new CommandError('DELIVERY_EVIDENCE_REQUIRED', 'Cần ghi nhận ít nhất một nội dung học tập đã dạy.');
        const delivery = {
          id: uid('delivery'),
          sessionId: session.id,
          teacherId: context.actor.id,
          actualStartsAt: session.actualStartsAt,
          actualEndsAt: nowIso(),
          taughtItemIds,
          deferredItemIds: payload.deferredItemIds || [],
          note: payload.note || '',
          coverageStatus: (payload.deferredItemIds || []).length ? 'GAP' : 'COMPLETE',
          status: 'RECORDED',
        };
        draft.deliveryRecords.push(delivery);
        session.status = 'COMPLETED';
        session.actualEndsAt = delivery.actualEndsAt;
        appendEvent(draft, context, 'DELIVERY_RECORDED', 'DELIVERY_RECORD', delivery.id, `${taughtItemIds.length} item đã dạy, ${delivery.deferredItemIds.length} item deferred.`);
        appendAudit(draft, context, 'SESSION_COMPLETED', 'SESSION', session.id, payload.note || 'Đã đủ bằng chứng giảng dạy.');
        if (delivery.coverageStatus === 'GAP') notifyRole(draft, 'ACADEMIC_MANAGER', 'Có nội dung chưa dạy cần theo dõi', payload.note || 'Buổi học có nội dung được chuyển sang sau.', '/app/academic/dashboard');
        return { message: 'Đã hoàn tất buổi học và lưu bằng chứng giảng dạy.' };
      },

      CORRECT_ATTENDANCE(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE', 'ACADEMIC_MANAGER']);
        if (!String(payload.reason || '').trim()) throw new CommandError('REASON_REQUIRED', 'Sửa điểm danh cần lý do để ghi nhật ký.');
        const record = required(draft.attendanceRecords.find((item) => item.id === payload.attendanceId), 'ATTENDANCE_NOT_FOUND', 'Không tìm thấy bản ghi điểm danh.');
        const previous = record.status;
        record.status = payload.status;
        record.correctedAt = nowIso();
        record.correctedBy = context.actor.id;
        record.correctionReason = payload.reason.trim();
        const reconciliation = root.YC.remedial.reconcileAttendance(draft, record, previous, { now: nowIso(), actorId: context.actor.id });
        if (reconciliation.createdAssignment) {
          appendEvent(draft, context, 'REMEDIAL_ASSIGNED', 'REMEDIAL_ASSIGNMENT', reconciliation.assignment.id, 'Đã tạo bài học bù sau khi sửa điểm danh.', { learnerId: record.learnerId });
        }
        appendEvent(draft, context, 'ATTENDANCE_CORRECTED', 'ATTENDANCE', record.id, `${previous} → ${record.status}.`, { learnerId: record.learnerId });
        appendAudit(draft, context, 'ATTENDANCE_CORRECTED', 'ATTENDANCE', record.id, payload.reason.trim());
        return { message: 'Đã sửa điểm danh với đầy đủ lý do.' };
      },

      REQUEST_SUBSTITUTION(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE', 'ACADEMIC_MANAGER']);
        if (!String(payload.reason || '').trim()) throw new CommandError('REASON_REQUIRED', 'Yêu cầu dạy thay cần lý do.');
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (draft.substitutions.some((item) => item.sessionId === session.id && !['CLOSED', 'CANCELLED'].includes(item.status))) throw new CommandError('SUBSTITUTION_EXISTS', 'Buổi học đã có yêu cầu dạy thay đang xử lý.');
        const primary = draft.teacherAssignments.find((item) => item.classId === session.classId && item.status === 'ACTIVE');
        const substitution = { id: uid('substitution'), sessionId: session.id, originalTeacherProfileId: primary?.teacherProfileId || null, replacementTeacherProfileId: null, reason: payload.reason.trim(), status: 'REQUESTED', handover: null, requestedBy: context.actor.id, requestedAt: nowIso(), accessStartsAt: null, accessEndsAt: null };
        draft.substitutions.push(substitution);
        appendEvent(draft, context, 'SUBSTITUTION_REQUESTED', 'SUBSTITUTION', substitution.id, payload.reason.trim());
        appendAudit(draft, context, 'SUBSTITUTION_REQUESTED', 'SUBSTITUTION', substitution.id, payload.reason.trim());
        return { message: 'Đã mở yêu cầu tìm giáo viên dạy thay.' };
      },

      CONFIRM_SUBSTITUTE(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE', 'ACADEMIC_MANAGER']);
        const substitution = required(draft.substitutions.find((item) => item.sessionId === payload.sessionId && item.status === 'REQUESTED'), 'SUBSTITUTION_NOT_FOUND', 'Không tìm thấy yêu cầu dạy thay.');
        const session = draft.sessions.find((item) => item.id === payload.sessionId);
        const eligibility = root.YC.selectors.teacherEligibility(draft, payload.replacementTeacherId, session.classId, 90);
        if (!eligibility.eligible) throw new CommandError('TEACHER_INELIGIBLE', 'Giáo viên dạy thay không đạt điều kiện bắt buộc.', { evidence: eligibility });
        const replacement = draft.teacherProfiles.find((item) => item.userId === payload.replacementTeacherId);
        substitution.replacementTeacherProfileId = replacement.id;
        substitution.status = 'CONFIRMED';
        substitution.confirmedAt = nowIso();
        substitution.accessStartsAt = new Date(new Date(session.startsAt).getTime() - 86400000).toISOString();
        substitution.accessEndsAt = new Date(new Date(session.endsAt).getTime() + 86400000).toISOString();
        appendEvent(draft, context, 'SUBSTITUTE_CONFIRMED', 'SUBSTITUTION', substitution.id, `${draft.users.find((item) => item.id === payload.replacementTeacherId)?.name} đã được chọn.`);
        appendAudit(draft, context, 'SUBSTITUTE_ACCESS_GRANTED', 'SUBSTITUTION', substitution.id, 'Quyền theo buổi học trong thời gian bàn giao.');
        return { message: 'Đã xác nhận giáo viên dạy thay.' };
      },

      MARK_HANDOVER_READY(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'STUDENT_SERVICE']);
        const substitution = required(draft.substitutions.find((item) => item.sessionId === payload.sessionId && item.status === 'CONFIRMED'), 'SUBSTITUTION_NOT_CONFIRMED', 'Yêu cầu dạy thay chưa được xác nhận.');
        if (!String(payload.note || '').trim()) throw new CommandError('HANDOVER_REQUIRED', 'Cần nội dung bàn giao.');
        substitution.handover = { note: payload.note.trim(), lessonTemplateId: draft.sessions.find((item) => item.id === payload.sessionId)?.lessonTemplateId, openHomeworkIds: draft.homeworkAssignments.filter((item) => item.classId === draft.sessions.find((session) => session.id === payload.sessionId)?.classId).map((item) => item.id), preparedBy: context.actor.id, preparedAt: nowIso() };
        substitution.status = 'HANDOVER_READY';
        appendEvent(draft, context, 'SUBSTITUTION_HANDOVER_READY', 'SUBSTITUTION', substitution.id, payload.note.trim());
        appendAudit(draft, context, 'SUBSTITUTION_HANDOVER_READY', 'SUBSTITUTION', substitution.id, 'Bài học, rủi ro và bài tập đã được bàn giao.');
        return { message: 'Gói bàn giao đã sẵn sàng.' };
      },

      CLOSE_SUBSTITUTION(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE', 'ACADEMIC_MANAGER']);
        const substitution = required(draft.substitutions.find((item) => item.sessionId === payload.sessionId && !['CLOSED', 'CANCELLED'].includes(item.status)), 'SUBSTITUTION_NOT_FOUND', 'Không tìm thấy yêu cầu dạy thay.');
        if (substitution.status !== 'HANDOVER_READY') throw new CommandError('HANDOVER_NOT_READY', 'Cần hoàn tất bàn giao trước khi đóng yêu cầu dạy thay.');
        substitution.status = 'CLOSED';
        substitution.closedAt = nowIso();
        appendEvent(draft, context, 'SUBSTITUTION_CLOSED', 'SUBSTITUTION', substitution.id, 'Đã đóng yêu cầu dạy thay và giới hạn thời gian truy cập.');
        appendAudit(draft, context, 'SUBSTITUTION_CLOSED', 'SUBSTITUTION', substitution.id, 'Đã giữ lại bằng chứng bàn giao.');
        return { message: 'Đã đóng yêu cầu dạy thay.' };
      },

      HOLD_MAKE_UP_SEAT(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        const existing = activeMakeUpBooking(draft, payload.caseId);
        if (existing) {
          if (existing.targetSessionId === payload.targetSessionId && existing.status === 'HELD') return { message: 'Chỗ học bù đang được giữ.', bookingId: existing.id };
          throw new CommandError('ACTIVE_MAKE_UP_BOOKING_EXISTS', 'Hồ sơ đã có một lịch học bù đang hoạt động.');
        }
        const validated = validateMakeUpTarget(draft, payload, context);
        const booking = makeUpBookingRecord(draft, validated, context, 'HELD');
        appendEvent(draft, context, 'MAKE_UP_SEAT_HELD', 'MAKE_UP_BOOKING', booking.id, `Giữ chỗ tại buổi ${booking.targetSessionId}.`, { learnerId: booking.learnerId });
        appendAudit(draft, context, 'MAKE_UP_SEAT_HELD', 'MAKE_UP_BOOKING', booking.id, `Hạn xác nhận ${booking.confirmationDeadline}.`);
        if (booking.contentMapping.type === 'ADMIN_EQUIVALENT') appendAudit(draft, context, 'MAKE_UP_MAPPING_OVERRIDDEN', 'MAKE_UP_BOOKING', booking.id, booking.contentMapping.coverageNote);
        return { message: 'Đã giữ chỗ học bù trong 24 giờ.', bookingId: booking.id };
      },

      CONFIRM_MAKE_UP_BOOKING(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        const existing = activeMakeUpBooking(draft, payload.caseId);
        if (existing && existing.targetSessionId !== payload.targetSessionId) throw new CommandError('ACTIVE_MAKE_UP_BOOKING_EXISTS', 'Hồ sơ đã có một lịch học bù đang hoạt động.');
        if (existing && ['BOOKED', 'NOTIFIED'].includes(existing.status)) return { message: 'Lịch học bù đã được xác nhận.', bookingId: existing.id };
        const validated = validateMakeUpTarget(draft, payload, context);
        const booking = existing || makeUpBookingRecord(draft, validated, context, 'BOOKED');
        if (existing) {
          booking.history ||= [];
          booking.history.push({ fromStatus: booking.status, toStatus: 'BOOKED', occurredAt: nowIso(), actorId: context.actor.id });
          booking.status = 'BOOKED';
          booking.bookedBy = context.actor.id;
          booking.bookedAt = nowIso();
          booking.contentMapping = validated.contentMapping;
        }
        appendEvent(draft, context, 'MAKE_UP_BOOKED', 'MAKE_UP_BOOKING', booking.id, `Đã xác nhận buổi học bù ${booking.targetSessionId}.`, { learnerId: booking.learnerId });
        appendAudit(draft, context, 'MAKE_UP_BOOKED', 'MAKE_UP_BOOKING', booking.id, `Buổi đích ${booking.targetSessionId}.`);
        if (booking.contentMapping.type === 'ADMIN_EQUIVALENT') appendAudit(draft, context, 'MAKE_UP_MAPPING_OVERRIDDEN', 'MAKE_UP_BOOKING', booking.id, booking.contentMapping.coverageNote);
        const studentUser = draft.users.find((item) => item.role === 'STUDENT' && (item.linkedLearnerIds || []).includes(booking.learnerId));
        if (studentUser) notifyUser(draft, studentUser.id, 'Lịch học bù đã được xác nhận', `Bạn sẽ tham dự buổi ${booking.targetSessionId} với tư cách khách học bù.`, `/app/student/remedial/${booking.remedialCaseId}`);
        return { message: 'Đã xác nhận lịch học bù.', bookingId: booking.id };
      },

      CANCEL_MAKE_UP_BOOKING(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Hủy lịch học bù cần ghi rõ lý do.');
        const booking = required(draft.makeUpBookings.find((item) => item.id === payload.bookingId), 'MAKE_UP_BOOKING_NOT_FOUND', 'Không tìm thấy lịch học bù.');
        if (!['HELD', 'BOOKED', 'NOTIFIED'].includes(booking.status)) throw new CommandError('INVALID_MAKE_UP_STATE', 'Chỉ lịch đang giữ hoặc đã đặt mới được hủy.');
        booking.history ||= [];
        booking.history.push({ fromStatus: booking.status, toStatus: 'CANCELLED', occurredAt: nowIso(), actorId: context.actor.id, reason });
        booking.status = 'CANCELLED';
        booking.cancelledAt = nowIso();
        booking.cancelledBy = context.actor.id;
        booking.cancellationReason = reason;
        appendEvent(draft, context, 'MAKE_UP_CANCELLED', 'MAKE_UP_BOOKING', booking.id, reason, { learnerId: booking.learnerId });
        appendAudit(draft, context, 'MAKE_UP_CANCELLED', 'MAKE_UP_BOOKING', booking.id, reason);
        return { message: 'Đã hủy lịch học bù và giữ lại lịch sử.' };
      },

      RECORD_MAKE_UP_ATTENDANCE(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'STUDENT_SERVICE', 'ACADEMIC_MANAGER']);
        const booking = required(draft.makeUpBookings.find((item) => item.id === payload.bookingId), 'MAKE_UP_BOOKING_NOT_FOUND', 'Không tìm thấy lịch học bù.');
        if (!['BOOKED', 'NOTIFIED'].includes(booking.status)) throw new CommandError('INVALID_MAKE_UP_STATE', 'Lịch học bù chưa ở trạng thái có thể điểm danh.');
        const targetSession = required(draft.sessions.find((item) => item.id === booking.targetSessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học đích.');
        if (!['IN_PROGRESS', 'COMPLETED'].includes(targetSession.status)) throw new CommandError('TARGET_SESSION_NOT_DELIVERED', 'Chỉ ghi nhận sau khi buổi học đích bắt đầu.');
        if (context.actor.role === 'TEACHER') {
          const profile = draft.teacherProfiles.find((item) => item.userId === context.actor.id);
          if (!profile || !draft.teacherAssignments.some((item) => item.teacherProfileId === profile.id && item.classId === targetSession.classId && ['ACTIVE', 'ACCEPTED'].includes(item.status))) {
            throw new CommandError('FORBIDDEN', 'Giáo viên không được phân công vào lớp đích.');
          }
        }
        const nextStatus = String(payload.attendanceStatus || '').toUpperCase();
        if (!['ATTENDED', 'NO_SHOW'].includes(nextStatus)) throw new CommandError('INVALID_ATTENDANCE_STATUS', 'Kết quả học bù phải là Đã tham dự hoặc Vắng buổi bù.');
        const note = String(payload.note || '').trim();
        if (nextStatus === 'NO_SHOW' && !note) throw new CommandError('REASON_REQUIRED', 'Vắng buổi bù cần ghi chú đối soát.');
        booking.history ||= [];
        booking.history.push({ fromStatus: booking.status, toStatus: nextStatus, occurredAt: nowIso(), actorId: context.actor.id, note });
        booking.status = nextStatus;
        booking.attendanceRecordedAt = nowIso();
        booking.attendanceRecordedBy = context.actor.id;
        booking.attendanceNote = note;
        booking.rebookRequired = nextStatus === 'NO_SHOW';
        appendEvent(draft, context, nextStatus === 'ATTENDED' ? 'MAKE_UP_ATTENDED' : 'MAKE_UP_NO_SHOW', 'MAKE_UP_BOOKING', booking.id, note || 'Đã xác nhận tham dự.', { learnerId: booking.learnerId });
        appendAudit(draft, context, 'MAKE_UP_ATTENDANCE_RECORDED', 'MAKE_UP_BOOKING', booking.id, `${nextStatus}${note ? ` · ${note}` : ''}.`);
        return { message: nextStatus === 'ATTENDED' ? 'Đã ghi nhận học viên tham dự buổi học bù.' : 'Đã ghi nhận vắng buổi bù; hồ sơ có thể được xếp lại lịch.' };
      },

      BOOK_MAKE_UP(draft, payload, context) {
        requireRole(context.actor, ['STUDENT_SERVICE']);
        const attendance = required(draft.attendanceRecords.find((item) => item.id === payload.attendanceId && ['ABSENT', 'EXCUSED'].includes(item.status)), 'MAKE_UP_NOT_ELIGIBLE', 'Bản ghi điểm danh chưa đủ điều kiện học bù.');
        const session = required(draft.sessions.find((item) => item.id === payload.makeUpSessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học bù.');
        const booking = { id: uid('make-up'), learnerId: attendance.learnerId, sourceAttendanceId: attendance.id, sessionId: session.id, status: 'BOOKED', bookedBy: context.actor.id, bookedAt: nowIso() };
        draft.makeUpBookings.push(booking);
        appendEvent(draft, context, 'MAKE_UP_BOOKED', 'MAKE_UP', booking.id, 'Đã đặt buổi học bù.', { learnerId: booking.learnerId });
        appendAudit(draft, context, 'MAKE_UP_BOOKED', 'MAKE_UP', booking.id, `Buổi học ${session.id}.`);
        return { message: 'Đã đặt buổi học bù.' };
      },

      FINALIZE_ATTENDANCE(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'TA']);
        const session = required(draft.sessions.find((item) => item.id === payload.sessionId), 'SESSION_NOT_FOUND', 'Không tìm thấy buổi học.');
        if (!['IN_PROGRESS', 'COMPLETED'].includes(session.status)) throw new CommandError('INVALID_SESSION_STATE', 'Chỉ điểm danh khi buổi học đang hoặc đã diễn ra.');
        if (!root.YC.policy.can(context.actor, 'ATTENDANCE_EDIT', { classId: session.classId }, draft)) throw new CommandError('FORBIDDEN', 'Không có phân công hiệu lực cho lớp này.');
        const records = payload.records || [];
        if (!records.length) throw new CommandError('ATTENDANCE_REQUIRED', 'Cần ít nhất một bản ghi điểm danh.');
        let createdAssignments = 0;
        for (const input of records) {
          const learner = required(draft.learners.find((item) => item.id === input.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên trong danh sách điểm danh.');
          let record = draft.attendanceRecords.find((item) => item.sessionId === session.id && item.learnerId === learner.id);
          const previousStatus = record?.status || null;
          if (!record) {
            record = { id: uid('attendance'), sessionId: session.id, learnerId: learner.id };
            draft.attendanceRecords.push(record);
          }
          record.status = input.status;
          record.reasonCode = input.reasonCode || null;
          record.markedBy = context.actor.id;
          record.markedAt = nowIso();
          const reconciliation = root.YC.remedial.reconcileAttendance(draft, record, previousStatus, { now: nowIso(), actorId: context.actor.id });
          if (reconciliation.createdAssignment) {
            const assignment = reconciliation.assignment;
            createdAssignments += 1;
            appendEvent(draft, context, 'REMEDIAL_ASSIGNED', 'REMEDIAL_ASSIGNMENT', assignment.id, `${learner.name} nhận bài học bù.`, { learnerId: learner.id });
            const studentUser = draft.users.find((item) => item.role === 'STUDENT' && (item.linkedLearnerIds || []).includes(learner.id));
            if (studentUser) draft.notifications.unshift({ id: uid('notification'), userId: studentUser.id, title: 'Bạn có bài học bù mới', body: 'Hoàn tất video và bài kiểm tra trước hạn.', link: '/app/student/remedial', read: false, createdAt: nowIso() });
          }
        }
        session.attendanceFinalized = true;
        appendEvent(draft, context, 'ATTENDANCE_FINALIZED', 'SESSION', session.id, `${records.length} bản ghi · ${createdAssignments} bài học bù mới.`);
        appendAudit(draft, context, 'ATTENDANCE_FINALIZED', 'SESSION', session.id, `Không tạo trùng · ${createdAssignments} nhiệm vụ mới.`);
        return { message: `Đã lưu điểm danh; tạo ${createdAssignments} bài học bù.`, createdAssignments };
      },

      START_REMEDIAL(draft, payload, context) {
        requireRole(context.actor, ['STUDENT']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        if (!(context.actor.linkedLearnerIds || []).includes(assignment.learnerId)) throw new CommandError('FORBIDDEN', 'Bài học bù không thuộc tài khoản này.');
        if (assignment.status === 'ASSIGNED') assignment.status = 'IN_PROGRESS';
        appendEvent(draft, context, 'REMEDIAL_STARTED', 'REMEDIAL_ASSIGNMENT', assignment.id, 'Học viên bắt đầu bài học bù.', { learnerId: assignment.learnerId });
        return { message: 'Đã bắt đầu bài học bù.' };
      },

      REGENERATE_REMEDIAL_LINK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'TA']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        assignment.accessToken = uid('access');
        assignment.accessStatus = 'ACTIVE';
        assignment.linkVersion = Number(assignment.linkVersion || 1) + 1;
        assignment.accessExpiresAt = assignment.dueAt;
        appendEvent(draft, context, 'REMEDIAL_LINK_REGENERATED', 'REMEDIAL_ASSIGNMENT', assignment.id, `Đã tạo liên kết phiên bản ${assignment.linkVersion}.`, { learnerId: assignment.learnerId });
        appendAudit(draft, context, 'REMEDIAL_LINK_REGENERATED', 'REMEDIAL_ASSIGNMENT', assignment.id, `Phiên bản ${assignment.linkVersion}.`);
        return { message: 'Đã tạo lại liên kết bài học bù.', linkVersion: assignment.linkVersion };
      },

      REVOKE_REMEDIAL_LINK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'TA']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        const reason = String(payload.reason || '').trim();
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Thu hồi liên kết cần có lý do.');
        assignment.accessStatus = 'REVOKED';
        assignment.revokedAt = nowIso();
        assignment.revokedBy = context.actor.id;
        assignment.revocationReason = reason;
        appendEvent(draft, context, 'REMEDIAL_LINK_REVOKED', 'REMEDIAL_ASSIGNMENT', assignment.id, reason, { learnerId: assignment.learnerId });
        appendAudit(draft, context, 'REMEDIAL_LINK_REVOKED', 'REMEDIAL_ASSIGNMENT', assignment.id, reason);
        return { message: 'Đã thu hồi liên kết bài học bù.' };
      },

      EXTEND_REMEDIAL_DEADLINE(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'TA']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        const reason = String(payload.reason || '').trim();
        const days = Number(payload.days || 0);
        if (!reason) throw new CommandError('REASON_REQUIRED', 'Gia hạn cần có lý do.');
        if (!Number.isInteger(days) || days < 1 || days > 30) throw new CommandError('INVALID_EXTENSION', 'Số ngày gia hạn phải từ 1 đến 30.');
        assignment.dueAt = new Date(new Date(assignment.dueAt).getTime() + days * 86400000).toISOString();
        if (assignment.accessStatus === 'ACTIVE') assignment.accessExpiresAt = assignment.dueAt;
        appendEvent(draft, context, 'REMEDIAL_DEADLINE_EXTENDED', 'REMEDIAL_ASSIGNMENT', assignment.id, `Gia hạn ${days} ngày.`, { learnerId: assignment.learnerId });
        appendAudit(draft, context, 'REMEDIAL_DEADLINE_EXTENDED', 'REMEDIAL_ASSIGNMENT', assignment.id, `${days} ngày · ${reason}`);
        return { message: `Đã gia hạn ${days} ngày.`, dueAt: assignment.dueAt };
      },

      UPDATE_VIDEO_PROGRESS(draft, payload, context) {
        requireRole(context.actor, ['STUDENT']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        if (!(context.actor.linkedLearnerIds || []).includes(assignment.learnerId)) throw new CommandError('FORBIDDEN', 'Bài học bù không thuộc tài khoản này.');
        assignment.videoProgress = Math.max(0, Math.min(100, Number(payload.progress || 0)));
        if (assignment.status === 'ASSIGNED') assignment.status = 'IN_PROGRESS';
        let progressRecord = draft.videoProgressRecords.find((item) => item.assignmentId === assignment.id);
        if (!progressRecord) {
          progressRecord = { id: uid('video-progress'), assignmentId: assignment.id, learnerId: assignment.learnerId };
          draft.videoProgressRecords.push(progressRecord);
        }
        progressRecord.progress = assignment.videoProgress;
        progressRecord.updatedAt = nowIso();
        appendEvent(draft, context, 'VIDEO_PROGRESS_UPDATED', 'VIDEO_PROGRESS', progressRecord.id, `${assignment.videoProgress}%`, { learnerId: assignment.learnerId });
        return { message: `Đã lưu ${assignment.videoProgress}% tiến độ video.` };
      },

      SUBMIT_AUTO_ASSESSMENT(draft, payload, context) {
        requireRole(context.actor, ['STUDENT']);
        const assignment = required(draft.remedialAssignments.find((item) => item.id === payload.assignmentId), 'REMEDIAL_NOT_FOUND', 'Không tìm thấy bài học bù.');
        if (!(context.actor.linkedLearnerIds || []).includes(assignment.learnerId)) throw new CommandError('FORBIDDEN', 'Bài kiểm tra không thuộc tài khoản này.');
        const assessment = required(draft.assessments.find((item) => item.id === assignment.assessmentId), 'ASSESSMENT_NOT_FOUND', 'Không tìm thấy bài kiểm tra.');
        const previous = draft.attempts.filter((item) => item.assignmentId === assignment.id);
        if (previous.length >= assessment.maxAttempts) throw new CommandError('MAX_ATTEMPTS_REACHED', 'Đã hết số lượt làm bài.');
        const answers = payload.answers || [];
        if (answers.length !== assessment.questionIds.length) throw new CommandError('INCOMPLETE_ATTEMPT', 'Cần trả lời đầy đủ trước khi nộp.');
        const correct = assessment.questionIds.reduce((total, questionId, index) => {
          const question = draft.questions.find((item) => item.id === questionId);
          return total + (Number(answers[index]) === Number(question.correctIndex) ? 1 : 0);
        }, 0);
        const score = Math.round((correct / assessment.questionIds.length) * 100);
        const attempt = { id: uid('attempt'), assignmentId: assignment.id, learnerId: assignment.learnerId, assessmentId: assessment.id, attemptNumber: previous.length + 1, answers: answers.slice(), correct, score, status: 'RELEASED', startedAt: nowIso(), submittedAt: nowIso(), releasedAt: nowIso(), gradingMode: 'AUTO' };
        draft.attempts.push(attempt);
        assignment.highestScore = Math.max(Number(assignment.highestScore || 0), score);
        const completion = root.YC.selectors.completionStatus(draft, assignment.id);
        if (completion.completed) {
          assignment.status = 'COMPLETED';
          assignment.completedAt = nowIso();
          assignment.completionMode = 'AUTO';
          appendEvent(draft, context, 'REMEDIAL_COMPLETED', 'REMEDIAL_ASSIGNMENT', assignment.id, `${score}/100 · tiến độ video ${assignment.videoProgress}%.`, { learnerId: assignment.learnerId });
          draft.notifications.unshift({ id: uid('notification'), userId: context.actor.id, title: 'Bạn đã bù xong', body: `Kết quả ${score}/100 đã được ghi nhận.`, link: '/app/student/progress', read: false, createdAt: nowIso() });
          notifyRole(draft, 'TEACHER', 'Học viên đã bù xong', `${draft.learners.find((item) => item.id === assignment.learnerId)?.name}: ${score}/100.`, '/app/teacher/dashboard');
        } else {
          assignment.status = 'NOT_PASSED';
          appendEvent(draft, context, 'ASSESSMENT_ATTEMPT_RELEASED', 'ATTEMPT', attempt.id, `${score}/100 · chưa đủ điều kiện hoàn thành.`, { learnerId: assignment.learnerId });
        }
        appendAudit(draft, context, 'AUTO_ASSESSMENT_SUBMITTED', 'ATTEMPT', attempt.id, `${correct}/${assessment.questionIds.length} câu đúng.`);
        return { message: completion.completed ? 'Đã hoàn tất bài học bù.' : 'Đã lưu kết quả; còn thiếu điều kiện hoàn thành.', score, completed: completion.completed };
      },

      ASSIGN_HOMEWORK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        if (!root.YC.policy.can(context.actor, 'HOMEWORK_EDIT', { classId: payload.classId, learnerId: learner.id }, draft)) throw new CommandError('FORBIDDEN', 'Không có quyền giao bài cho lớp này.');
        const homework = { id: uid('homework'), classId: payload.classId, learnerId: learner.id, title: payload.title, objective: payload.objective || 'Thực hành và củng cố', status: 'ASSIGNED', assignedBy: context.actor.id, assignedAt: nowIso(), dueAt: new Date(new Date(nowIso()).getTime() + 3 * 86400000).toISOString(), currentSubmissionId: null };
        draft.homeworkAssignments.push(homework);
        appendEvent(draft, context, 'HOMEWORK_ASSIGNED', 'HOMEWORK', homework.id, homework.title, { learnerId: learner.id });
        return { message: 'Đã giao bài tập.' };
      },

      SUBMIT_HOMEWORK(draft, payload, context) {
        requireRole(context.actor, ['STUDENT']);
        const homework = required(draft.homeworkAssignments.find((item) => item.id === payload.homeworkId), 'HOMEWORK_NOT_FOUND', 'Không tìm thấy bài tập.');
        if (!(context.actor.linkedLearnerIds || []).includes(homework.learnerId)) throw new CommandError('FORBIDDEN', 'Bài tập không thuộc tài khoản này.');
        if (!['ASSIGNED', 'REVISION_REQUIRED'].includes(homework.status)) throw new CommandError('INVALID_HOMEWORK_STATE', 'Bài tập chưa sẵn sàng để nộp.');
        const submission = { id: uid('homework-submission'), homeworkId: homework.id, learnerId: homework.learnerId, version: draft.homeworkSubmissions.filter((item) => item.homeworkId === homework.id).length + 1, evidence: payload.evidence, status: 'SUBMITTED', submittedAt: nowIso() };
        draft.homeworkSubmissions.push(submission);
        homework.currentSubmissionId = submission.id;
        homework.status = homework.status === 'REVISION_REQUIRED' ? 'RESUBMITTED' : 'SUBMITTED';
        appendEvent(draft, context, 'HOMEWORK_SUBMITTED', 'HOMEWORK_SUBMISSION', submission.id, `${homework.title} · v${submission.version}.`, { learnerId: homework.learnerId });
        notifyRole(draft, 'TEACHER', 'Có bài tập chờ chấm', homework.title, '/app/teacher/grading');
        return { message: 'Đã nộp bài tập.' };
      },

      RESUBMIT_HOMEWORK(draft, payload, context) {
        return handlers.SUBMIT_HOMEWORK(draft, payload, context);
      },

      GRADE_HOMEWORK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const homework = required(draft.homeworkAssignments.find((item) => item.id === payload.homeworkId), 'HOMEWORK_NOT_FOUND', 'Không tìm thấy bài tập.');
        if (!['SUBMITTED', 'RESUBMITTED'].includes(homework.status)) throw new CommandError('INVALID_HOMEWORK_STATE', 'Bài tập chưa có bài nộp chờ chấm.');
        const submission = draft.homeworkSubmissions.find((item) => item.id === homework.currentSubmissionId);
        submission.score = Number(payload.score);
        submission.feedback = payload.feedback;
        submission.gradedBy = context.actor.id;
        submission.gradedAt = nowIso();
        submission.status = 'FEEDBACK_READY';
        homework.status = 'FEEDBACK_READY';
        appendEvent(draft, context, 'HOMEWORK_GRADED', 'HOMEWORK_SUBMISSION', submission.id, `${submission.score}/100.`, { learnerId: homework.learnerId });
        return { message: 'Đã chấm bài tập và chuẩn bị nhận xét.' };
      },

      RELEASE_HOMEWORK_FEEDBACK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const homework = required(draft.homeworkAssignments.find((item) => item.id === payload.homeworkId), 'HOMEWORK_NOT_FOUND', 'Không tìm thấy bài tập.');
        if (homework.status !== 'FEEDBACK_READY') throw new CommandError('FEEDBACK_NOT_READY', 'Nhận xét chưa sẵn sàng để phát hành.');
        const submission = draft.homeworkSubmissions.find((item) => item.id === homework.currentSubmissionId);
        submission.status = 'RELEASED';
        submission.releasedAt = nowIso();
        homework.status = 'RELEASED';
        appendEvent(draft, context, 'HOMEWORK_FEEDBACK_RELEASED', 'HOMEWORK', homework.id, 'Nhận xét đã phát hành.', { learnerId: homework.learnerId });
        return { message: 'Đã phát hành nhận xét bài tập.' };
      },

      REQUEST_REVISION(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const homework = required(draft.homeworkAssignments.find((item) => item.id === payload.homeworkId), 'HOMEWORK_NOT_FOUND', 'Không tìm thấy bài tập.');
        if (homework.status !== 'RELEASED') throw new CommandError('FEEDBACK_NOT_RELEASED', 'Cần phát hành nhận xét trước khi yêu cầu sửa bài.');
        homework.status = 'REVISION_REQUIRED';
        homework.nextAction = payload.nextAction;
        appendEvent(draft, context, 'HOMEWORK_REVISION_REQUIRED', 'HOMEWORK', homework.id, payload.nextAction, { learnerId: homework.learnerId });
        return { message: 'Đã yêu cầu nộp lại bài tập.' };
      },

      ACCEPT_HOMEWORK(draft, payload, context) {
        requireRole(context.actor, ['TEACHER']);
        const homework = required(draft.homeworkAssignments.find((item) => item.id === payload.homeworkId), 'HOMEWORK_NOT_FOUND', 'Không tìm thấy bài tập.');
        if (homework.status !== 'RELEASED') throw new CommandError('FEEDBACK_NOT_RELEASED', 'Cần phát hành nhận xét trước khi chấp nhận bài.' );
        homework.status = 'ACCEPTED';
        homework.acceptedAt = nowIso();
        appendEvent(draft, context, 'HOMEWORK_ACCEPTED', 'HOMEWORK', homework.id, 'Bài tập đã đạt mục tiêu.', { learnerId: homework.learnerId });
        return { message: 'Đã chấp nhận bài tập.' };
      },

      SUBMIT_MANUAL_GRADE(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'ACADEMIC_MANAGER']);
        const assessment = required(draft.assessments.find((item) => item.id === payload.assessmentId), 'ASSESSMENT_NOT_FOUND', 'Không tìm thấy bài kiểm tra.');
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        const values = Object.values(payload.skills || {}).map(Number);
        if (values.length !== 6) throw new CommandError('SKILL_EVIDENCE_REQUIRED', 'Cần đủ điểm của sáu kỹ năng.');
        const score = Math.round(values.reduce((sum, value) => sum + value, 0) / values.length);
        const attempt = { id: uid('attempt-final'), learnerId: learner.id, assessmentId: assessment.id, score, status: 'SUBMITTED_FOR_REVIEW', gradingMode: 'MANUAL', submittedAt: nowIso(), moderationRequired: assessment.purpose === 'FINAL' || values.some((value) => Math.abs(value - 60) <= 3) };
        draft.attempts.push(attempt);
        const grading = { id: uid('grading'), attemptId: attempt.id, learnerId: learner.id, graderId: context.actor.id, skills: { ...payload.skills }, score, feedback: payload.feedback, status: 'SUBMITTED_FOR_REVIEW', gradedAt: nowIso() };
        draft.gradingRecords.push(grading);
        const skillMap = { listening: 'LISTENING', reading: 'READING', spokenInteraction: 'SPOKEN_INTERACTION', spokenProduction: 'SPOKEN_PRODUCTION', writing: 'WRITING', language: 'LANGUAGE' };
        Object.entries(payload.skills).forEach(([key, value]) => draft.skillResults.push({ id: uid('skill-result'), learnerId: learner.id, assessmentId: assessment.id, attemptId: attempt.id, skill: skillMap[key], score: Number(value), status: 'PENDING_REVIEW', recordedAt: nowIso() }));
        appendEvent(draft, context, 'MANUAL_GRADE_SUBMITTED', 'GRADING_RECORD', grading.id, `${score}/100 · kiểm duyệt ${attempt.moderationRequired ? 'bắt buộc' : 'không bắt buộc'}.`, { learnerId: learner.id });
        notifyRole(draft, 'ACADEMIC_MANAGER', 'Có kết quả cần kiểm duyệt', `${learner.name} · ${assessment.title}.`, '/app/academic/moderation');
        return { message: 'Đã gửi điểm và bằng chứng để duyệt.', attemptId: attempt.id, score };
      },

      START_MODERATION(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const attempt = required(draft.attempts.find((item) => item.id === payload.attemptId), 'ATTEMPT_NOT_FOUND', 'Không tìm thấy lượt làm bài.');
        if (!attempt.moderationRequired) throw new CommandError('MODERATION_NOT_REQUIRED', 'Lượt làm này không cần kiểm duyệt.');
        if (draft.moderationCases.some((item) => item.attemptId === attempt.id)) throw new CommandError('MODERATION_EXISTS', 'Hồ sơ kiểm duyệt đã tồn tại.');
        const moderation = { id: uid('moderation'), attemptId: attempt.id, learnerId: attempt.learnerId, status: 'MODERATION', variance: 2, reviewerId: context.actor.id, openedAt: nowIso() };
        draft.moderationCases.push(moderation);
        appendEvent(draft, context, 'MODERATION_STARTED', 'MODERATION_CASE', moderation.id, 'Bắt đầu đối chiếu thang điểm và bằng chứng.', { learnerId: attempt.learnerId });
        return { message: 'Đã mở hồ sơ kiểm duyệt.' };
      },

      APPROVE_MODERATION(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const moderation = required(draft.moderationCases.find((item) => item.attemptId === payload.attemptId && item.status === 'MODERATION'), 'MODERATION_NOT_FOUND', 'Không tìm thấy hồ sơ kiểm duyệt đang mở.');
        if (!String(payload.note || '').trim()) throw new CommandError('EVIDENCE_NOTE_REQUIRED', 'Phê duyệt cần ghi chú bằng chứng.');
        moderation.status = 'APPROVED';
        moderation.note = payload.note.trim();
        moderation.approvedAt = nowIso();
        appendEvent(draft, context, 'MODERATION_APPROVED', 'MODERATION_CASE', moderation.id, moderation.note, { learnerId: moderation.learnerId });
        appendAudit(draft, context, 'MODERATION_APPROVED', 'MODERATION_CASE', moderation.id, moderation.note);
        return { message: 'Đã phê duyệt kiểm duyệt.' };
      },

      RELEASE_RESULT(draft, payload, context) {
        requireRole(context.actor, ['TEACHER', 'ACADEMIC_MANAGER']);
        const attempt = required(draft.attempts.find((item) => item.id === payload.attemptId), 'ATTEMPT_NOT_FOUND', 'Không tìm thấy lượt làm bài.');
        const grading = required(draft.gradingRecords.find((item) => item.attemptId === attempt.id), 'GRADING_NOT_FOUND', 'Không tìm thấy bản ghi chấm điểm.');
        if (attempt.moderationRequired && !draft.moderationCases.some((item) => item.attemptId === attempt.id && item.status === 'APPROVED')) throw new CommandError('MODERATION_REQUIRED', 'Kết quả cuối khóa hoặc sát ngưỡng cần được kiểm duyệt trước khi phát hành.');
        grading.status = 'RELEASED';
        grading.releasedAt = nowIso();
        attempt.status = 'RELEASED';
        attempt.releasedAt = nowIso();
        draft.skillResults.filter((item) => item.attemptId === attempt.id).forEach((item) => { item.status = 'RELEASED'; });
        appendEvent(draft, context, 'RESULT_RELEASED', 'ATTEMPT', attempt.id, `${attempt.score}/100.`, { learnerId: attempt.learnerId });
        appendAudit(draft, context, 'RESULT_RELEASED', 'ATTEMPT', attempt.id, attempt.moderationRequired ? 'Đã phát hành sau khi kiểm duyệt.' : 'Đã phát hành theo quy tắc chấm điểm.');
        return { message: 'Đã phát hành kết quả.' };
      },

      OPEN_INTERVENTION(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER', 'TEACHER', 'STUDENT_SERVICE']);
        if (!String(payload.plan || '').trim() || !payload.followUpAt) throw new CommandError('INTERVENTION_PLAN_REQUIRED', 'Can thiệp cần kế hoạch hành động và ngày theo dõi tiếp theo.');
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        const owner = draft.users.find((item) => item.role === payload.ownerRole && item.status === 'ACTIVE');
        const intervention = { id: uid('intervention'), learnerId: learner.id, signal: payload.signal, ownerRole: payload.ownerRole, ownerId: owner?.id || context.actor.id, status: 'OPEN', plan: payload.plan.trim(), followUpAt: payload.followUpAt, outcome: null, openedBy: context.actor.id, openedAt: nowIso() };
        draft.interventionCases.push(intervention);
        appendEvent(draft, context, 'INTERVENTION_OPENED', 'INTERVENTION', intervention.id, `${payload.signal} → ${payload.ownerRole}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'INTERVENTION_OPENED', 'INTERVENTION', intervention.id, intervention.plan);
        notifyRole(draft, payload.ownerRole, 'Có can thiệp cần xử lý', `${learner.name}: ${payload.signal}.`, '/app/service/cases');
        return { message: 'Đã mở can thiệp và giao người phụ trách.' };
      },

      PUBLISH_PROGRESS_REPORT(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        const evidence = root.YC.selectors.progressReportEvidence(draft, learner.id);
        if (evidence.skillProfile.some((item) => item.score === null)) throw new CommandError('SKILL_EVIDENCE_INCOMPLETE', 'Cần đủ kết quả sáu kỹ năng đã phát hành.');
        const report = { id: uid('progress-report'), learnerId: learner.id, status: 'PUBLISHED', snapshot: { attendanceRate: evidence.attendanceRate, homeworkCompletion: evidence.homeworkCompletion }, skillProfile: evidence.skillProfile, narrative: payload.narrative, nextActions: payload.nextActions || [], evidenceIds: [...evidence.interventionIds, ...evidence.remedialIds, ...evidence.skillProfile.map((item) => item.evidenceId)], approvedBy: context.actor.id, publishedAt: nowIso() };
        draft.progressReports.push(report);
        appendEvent(draft, context, 'PROGRESS_REPORT_PUBLISHED', 'PROGRESS_REPORT', report.id, learner.name, { learnerId: learner.id });
        appendAudit(draft, context, 'PROGRESS_REPORT_PUBLISHED', 'PROGRESS_REPORT', report.id, 'Bằng chứng đã công bố hiển thị cho học viên và phụ huynh.');
        const parent = draft.users.find((item) => item.role === 'PARENT' && (item.linkedLearnerIds || []).includes(learner.id));
        if (parent) draft.notifications.unshift({ id: uid('notification'), userId: parent.id, title: 'Báo cáo tiến bộ đã phát hành', body: `${learner.name}: xem kết quả và việc cần làm tiếp theo.`, link: '/app/parent/progress', read: false, createdAt: nowIso() });
        return { message: 'Đã phát hành báo cáo tiến bộ.', reportId: report.id };
      },

      DECIDE_PROMOTION(draft, payload, context) {
        requireRole(context.actor, ['ACADEMIC_MANAGER']);
        const learner = required(draft.learners.find((item) => item.id === payload.learnerId), 'LEARNER_NOT_FOUND', 'Không tìm thấy học viên.');
        const report = required(draft.progressReports.find((item) => item.learnerId === learner.id && item.status === 'PUBLISHED'), 'PROGRESS_REPORT_REQUIRED', 'Cần báo cáo tiến bộ đã công bố.');
        const enrollment = draft.enrollments.find((item) => item.learnerId === learner.id && item.status === 'ACTIVE');
        const courseVersion = draft.courseVersions.find((item) => item.id === enrollment?.courseVersionId) || draft.courseVersions.find((item) => item.id === 'course-v6');
        const minimum = courseVersion.completionRule.skillMinimum;
        const skillThresholds = report.skillProfile.map((item) => ({ skill: item.skill, score: item.score, minimum, passed: item.score >= minimum }));
        const overall = Math.round(report.skillProfile.reduce((sum, item) => sum + item.score, 0) / report.skillProfile.length);
        const evidence = { skillThresholds, attendanceRate: report.snapshot.attendanceRate, overall, rule: courseVersion.completionRule };
        const thresholdsPassed = skillThresholds.every((item) => item.passed)
          && report.snapshot.attendanceRate >= courseVersion.completionRule.attendanceMinimum
          && overall >= courseVersion.completionRule.finalScoreMinimum;
        const overrideReason = String(payload.overrideReason || '').trim();
        const overrideEvidence = Array.isArray(payload.overrideEvidence) ? payload.overrideEvidence.filter(Boolean) : [];
        if (payload.decision === 'PROMOTE' && !thresholdsPassed && (!overrideReason || overrideEvidence.length === 0)) {
          throw new CommandError('PROMOTION_THRESHOLDS_NOT_MET', 'Bằng chứng chưa đạt quy tắc lên lớp; ngoại lệ cần lý do và bằng chứng.', { evidence });
        }
        const decision = { id: uid('promotion'), learnerId: learner.id, progressReportId: report.id, decision: payload.decision, nextCourseVersionId: payload.nextCourseVersionId || null, evidence, status: 'FINAL', decidedBy: context.actor.id, decidedAt: nowIso(), overrideReason: overrideReason || null, overrideEvidence };
        draft.promotionDecisions.unshift(decision);
        appendEvent(draft, context, 'PROMOTION_DECIDED', 'PROMOTION', decision.id, `${learner.name}: ${decision.decision}.`, { learnerId: learner.id });
        appendAudit(draft, context, 'PROMOTION_DECIDED', 'PROMOTION', decision.id, `${decision.decision} · tổng thể ${overall}${overrideReason ? ` · ngoại lệ: ${overrideReason}` : ''}.`);
        notifyRole(draft, 'ADMISSIONS', 'Học viên sẵn sàng gia hạn', `${learner.name}: ${decision.decision}.`, '/app/admissions/renewals');
        return { message: 'Đã chốt quyết định lên lớp.', evidence };
      },

      ACKNOWLEDGE_PARENT_PROGRESS(draft, payload, context) {
        requireRole(context.actor, ['PARENT']);
        if (!(context.actor.linkedLearnerIds || []).includes(payload.learnerId)) throw new CommandError('FORBIDDEN', 'Học viên không thuộc tài khoản phụ huynh.');
        const report = required(draft.progressReports.find((item) => item.learnerId === payload.learnerId && item.status === 'PUBLISHED'), 'PROGRESS_REPORT_REQUIRED', 'Chưa có báo cáo tiến bộ được công bố.');
        appendEvent(draft, context, 'PARENT_PROGRESS_VIEWED', 'PROGRESS_REPORT', report.id, 'Phụ huynh đã xem báo cáo và việc cần làm tiếp theo.', { learnerId: payload.learnerId });
        appendAudit(draft, context, 'PARENT_PROGRESS_VIEWED', 'PROGRESS_REPORT', report.id, 'Đã lọc nội dung theo quyền xem của phụ huynh.');
        return { message: 'Đã ghi nhận phụ huynh xem báo cáo.' };
      },
    };

    function dispatch(name, payload = {}, actorId) {
      const handler = handlers[name];
      if (!handler) return { ok: false, code: 'UNKNOWN_COMMAND', message: `Command không tồn tại: ${name}` };
      const eventIds = [];
      try {
        let output;
        store.transact((draft) => {
          const actor = required(draft.users.find((item) => item.id === actorId), 'ACTOR_NOT_FOUND', 'Không tìm thấy người thực hiện.');
          const context = { actor, eventIds };
          output = handler(draft, payload, context) || {};
        });
        return { ok: true, eventIds, message: output.message || 'Đã cập nhật.', ...output };
      } catch (error) {
        if (error instanceof CommandError) {
          return { ok: false, code: error.code, message: error.message, alternatives: error.alternatives || [], evidence: error.evidence || null };
        }
        throw error;
      }
    }

    return Object.freeze({ dispatch, registered: Object.freeze(Object.keys(handlers)) });
  }

  root.YC.define('commands', Object.freeze({ CommandError, create }));
})(globalThis);

/* 06-public-content.js */
(function definePublicContent(root) {
  'use strict';

  const COLLECTIONS = Object.freeze([
    'siteSettings', 'navigationGroups', 'navigationItems', 'heroBanners', 'publicProgramProfiles',
    'publicBranchProfiles', 'publicTeacherProfiles', 'articles', 'articleCategories',
    'publicEvents', 'staticPages', 'contactChannels',
  ]);

  function published(type, state, at = null) {
    if (!COLLECTIONS.includes(type) || !Array.isArray(state?.[type])) return [];
    const moment = new Date(at || state.currentAt || state.seededAt || Date.now()).getTime();
    const byKey = new Map();
    state[type].forEach((item) => {
      if (item.status !== 'PUBLISHED') return;
      if (item.effectiveFrom && new Date(item.effectiveFrom).getTime() > moment) return;
      if (item.effectiveTo && new Date(item.effectiveTo).getTime() <= moment) return;
      const key = item.contentKey || item.id;
      const current = byKey.get(key);
      if (!current || Number(item.revision || 0) > Number(current.revision || 0)) byKey.set(key, item);
    });
    return [...byKey.values()].sort((a, b) => Number(a.order || 0) - Number(b.order || 0));
  }

  function publicNavigation(state) {
    const groups = published('navigationGroups', state);
    const items = published('navigationItems', state);
    const programs = published('publicProgramProfiles', state).map((item) => ({
      id: `nav-${item.id}`, contentKey: `nav-${item.contentKey || item.id}`, groupId: 'nav-group-programs',
      label: item.name, href: `/chuong-trinh/${item.slug}`, order: item.order, status: 'PUBLISHED', sourceId: item.id,
    }));
    return groups.map((group) => ({
      ...group,
      items: [...items.filter((item) => item.groupId === group.id), ...(group.source === 'PROGRAMS' ? programs : [])]
        .sort((a, b) => Number(a.order || 0) - Number(b.order || 0)),
    })).filter((group) => group.items.length > 0);
  }

  function homepage(state, actor = null) {
    const contacts = published('contactChannels', state).filter((item) => String(item.value || '').trim() && item.status === 'PUBLISHED');
    const programs = published('publicProgramProfiles', state).map((item) => ({
      ...item,
      saved: actor?.role === 'VISITOR' && (actor.savedProgramIds || []).includes(item.programId),
    }));
    return {
      site: published('siteSettings', state)[0] || null,
      hero: published('heroBanners', state).find((item) => item.placement === 'HOME') || null,
      programs,
      branches: published('publicBranchProfiles', state),
      teachers: published('publicTeacherProfiles', state).filter((item) => item.publicOptIn === true),
      categories: published('articleCategories', state),
      articles: published('articles', state),
      events: published('publicEvents', state),
      contacts,
      navigation: publicNavigation(state),
      accountState: actor?.role === 'VISITOR' ? 'VISITOR' : actor ? 'LEARNER_OR_STAFF' : 'ANONYMOUS',
    };
  }

  root.YC.define('publicContent', Object.freeze({ COLLECTIONS, homepage, publicNavigation, published }));
})(globalThis);

/* 06-remedial.js */
(function defineRemedial(root) {
  'use strict';

  const { clone, uid } = root.YC.utils;

  function sourceTrace(state, attendance) {
    const session = state.sessions.find((item) => item.id === attendance.sessionId);
    const cohort = state.classes.find((item) => item.id === session?.classId);
    const courseVersion = state.courseVersions.find((item) => item.id === cohort?.courseVersionId);
    const course = state.courses.find((item) => item.id === courseVersion?.courseId);
    const lesson = state.lessonTemplates.find((item) => item.id === session?.lessonTemplateId);
    return { session, cohort, courseVersion, course, lesson };
  }

  function overlaps(firstStart, firstEnd, secondStart, secondEnd) {
    return new Date(firstStart).getTime() < new Date(secondEnd).getTime()
      && new Date(firstEnd).getTime() > new Date(secondStart).getTime();
  }

  function activeAt(assignment, instant) {
    const time = new Date(instant).getTime();
    return ['ACTIVE', 'ACCEPTED'].includes(assignment.status)
      && (!assignment.startsAt || new Date(assignment.startsAt).getTime() <= time)
      && (!assignment.endsAt || new Date(assignment.endsAt).getTime() >= time);
  }

  function rankMakeUpTargets(state, caseId) {
    const remedialCase = state.remedialCases.find((item) => item.id === caseId);
    if (!remedialCase) return [];
    const sourceSession = state.sessions.find((item) => item.id === remedialCase.sourceSessionId);
    const sourceClass = state.classes.find((item) => item.id === remedialCase.sourceClassId);
    const learner = state.learners.find((item) => item.id === remedialCase.learnerId);
    const currentAt = new Date(state.currentAt || state.seededAt).getTime();
    const activeEnrollmentClassIds = state.enrollments
      .filter((item) => item.learnerId === remedialCase.learnerId && item.status === 'ACTIVE')
      .map((item) => item.classId);
    const activeBookingSessionIds = state.makeUpBookings
      .filter((item) => item.remedialCaseId !== caseId && item.learnerId === remedialCase.learnerId && ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status))
      .map((item) => item.targetSessionId || item.sessionId);

    return state.sessions
      .filter((session) => session.id !== remedialCase.sourceSessionId)
      .map((session) => {
        const cohort = state.classes.find((item) => item.id === session.classId);
        const targetCourseVersionId = cohort?.courseVersionId || null;
        const activeEnrollments = state.enrollments.filter((item) => item.classId === session.classId && item.status === 'ACTIVE').length;
        const reservations = state.makeUpBookings.filter((item) => item.remedialCaseId !== caseId
          && (item.targetSessionId || item.sessionId) === session.id
          && ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status)).length;
        const capacity = Number(cohort?.capacity || 0);
        const learnerConflict = state.sessions.some((other) => other.id !== session.id
          && !['CANCELLED', 'REVIEWED'].includes(other.status)
          && (activeEnrollmentClassIds.includes(other.classId) || activeBookingSessionIds.includes(other.id))
          && overlaps(session.startsAt, session.endsAt, other.startsAt, other.endsAt));
        const teacherAccess = state.teacherAssignments.some((item) => item.classId === session.classId && activeAt(item, session.startsAt));
        const sameCourseVersion = targetCourseVersionId === remedialCase.sourceCourseVersionId;
        const sameLesson = session.lessonTemplateId === remedialCase.sourceLessonTemplateId;
        const futureAndOpen = new Date(session.startsAt).getTime() > currentAt && ['CONFIRMED', 'READY'].includes(session.status);
        const hardGates = [
          { key: 'CASE_ACTIVE', label: 'Hồ sơ học bù còn hiệu lực', passed: remedialCase.resolution !== 'NOT_REQUIRED' },
          { key: 'COURSE_VERSION', label: 'Cùng phiên bản khóa học', passed: sameCourseVersion },
          { key: 'LESSON_TEMPLATE', label: 'Cùng bài học', passed: sameLesson },
          { key: 'CAPACITY', label: 'Còn chỗ cho khách học bù', passed: capacity > activeEnrollments + reservations },
          { key: 'LEARNER_SCHEDULE', label: 'Không trùng lịch học viên', passed: !learnerConflict },
          { key: 'SESSION_OPEN', label: 'Buổi học chưa bắt đầu và đã xác nhận', passed: futureAndOpen },
          { key: 'TEACHER_ACCESS', label: 'Giáo viên đích có phân công hiệu lực', passed: teacherAccess },
        ];
        const rankingSignals = [
          { key: 'EXACT_COURSE', label: 'Đúng phiên bản khóa học', score: sameCourseVersion ? 40 : 0 },
          { key: 'EXACT_LESSON', label: 'Đúng bài học', score: sameLesson ? 40 : 0 },
          { key: 'BRANCH_FIT', label: 'Cùng cơ sở', score: cohort?.branchId === sourceClass?.branchId ? 10 : 0 },
          { key: 'MODE_FIT', label: 'Cùng hình thức học', score: session.mode === sourceSession?.mode ? 5 : 0 },
          { key: 'AGE_BAND_FIT', label: 'Cùng nhóm tuổi', score: cohort?.ageBand === sourceClass?.ageBand ? 5 : 0 },
        ];
        const score = rankingSignals.reduce((sum, item) => sum + item.score, 0);
        const failedKeys = hardGates.filter((item) => !item.passed).map((item) => item.key);
        return {
          sessionId: session.id,
          classId: session.classId,
          learnerId: learner?.id || remedialCase.learnerId,
          eligible: failedKeys.length === 0,
          requiresAdminOverride: failedKeys.length === 1 && failedKeys[0] === 'LESSON_TEMPLATE',
          score,
          hardGates,
          rankingSignals,
          reasons: [...hardGates.filter((item) => !item.passed).map((item) => item.label), ...rankingSignals.filter((item) => item.score > 0).map((item) => item.label)],
        };
      })
      .sort((first, second) => Number(second.eligible) - Number(first.eligible)
        || Number(second.requiresAdminOverride) - Number(first.requiresAdminOverride)
        || second.score - first.score
        || new Date(state.sessions.find((item) => item.id === first.sessionId)?.startsAt).getTime() - new Date(state.sessions.find((item) => item.id === second.sessionId)?.startsAt).getTime());
  }

  function evaluateEligibility(state, attendanceId) {
    const attendance = state.attendanceRecords.find((item) => item.id === attendanceId);
    if (!attendance) return { eligible: false, code: 'ATTENDANCE_NOT_FOUND', policySnapshot: null };
    const trace = sourceTrace(state, attendance);
    if (!trace.session || !trace.cohort || !trace.courseVersion || !trace.lesson) return { eligible: false, code: 'SOURCE_TRACE_INCOMPLETE', policySnapshot: null };
    const policySnapshot = clone(trace.courseVersion.remedialPolicy || {
      triggerStatuses: ['ABSENT'], requiredModes: ['ONLINE'], deadlineDays: state.settings.remedialDeadlineDays,
      passingScore: state.settings.defaultPassingScore, minimumVideoProgress: state.settings.minimumVideoProgress,
    });
    const eligible = (policySnapshot.triggerStatuses || ['ABSENT']).includes(attendance.status);
    return { eligible, code: eligible ? 'ELIGIBLE' : 'ATTENDANCE_STATUS_NOT_ELIGIBLE', attendance, policySnapshot, ...trace };
  }

  function caseStatus(state, caseId) {
    const remedialCase = state.remedialCases.find((item) => item.id === caseId);
    if (!remedialCase) return null;
    const online = state.remedialAssignments.find((item) => item.remedialCaseId === remedialCase.id) || null;
    const liveBookings = state.makeUpBookings.filter((item) => item.remedialCaseId === remedialCase.id);
    const completedModes = [];
    if (online?.status === 'COMPLETED') completedModes.push('ONLINE');
    if (liveBookings.some((item) => item.status === 'ATTENDED')) completedModes.push('LIVE');
    const requiredModes = remedialCase.requiredModes || [];
    if (requiredModes.length && requiredModes.every((mode) => completedModes.includes(mode))) {
      return { caseId, status: 'COMPLETED', requiredModes, completedModes, online, liveBookings };
    }
    if (remedialCase.resolution === 'NOT_REQUIRED') return { caseId, status: 'NOT_REQUIRED', requiredModes, completedModes, online, liveBookings };
    const hasProgress = online && ['IN_PROGRESS', 'NOT_PASSED', 'COMPLETED'].includes(online.status)
      || liveBookings.some((item) => ['HELD', 'BOOKED', 'NOTIFIED', 'ATTENDED'].includes(item.status));
    return { caseId, status: hasProgress ? 'IN_PROGRESS' : 'OPEN', requiredModes, completedModes, online, liveBookings };
  }

  function createOnlineAssignment(draft, remedialCase, evaluation, context) {
    const now = context.now;
    const deadlineDays = Number(evaluation.policySnapshot.deadlineDays || draft.settings.remedialDeadlineDays);
    const dueAt = new Date(new Date(now).getTime() + deadlineDays * 86400000).toISOString();
    const assessment = draft.assessments.find((item) => item.lessonTemplateId === evaluation.lesson.id && item.purpose === 'FORMATIVE')
      || draft.assessments.find((item) => item.id === 'assessment-remedial');
    const assignment = {
      id: uid('remedial'), remedialCaseId: remedialCase.id, learnerId: remedialCase.learnerId,
      sessionId: remedialCase.sourceSessionId, lessonTemplateId: remedialCase.sourceLessonTemplateId,
      assessmentId: assessment?.id || null, status: 'ASSIGNED', assignedAt: now, dueAt,
      videoProgress: 0, highestScore: null, completionMode: null, completedAt: null,
      accessToken: uid('access'), accessStatus: 'ACTIVE', linkVersion: 1, accessExpiresAt: dueAt,
      policySnapshot: clone(evaluation.policySnapshot),
    };
    draft.remedialAssignments.push(assignment);
    return assignment;
  }

  function reconcileAttendance(draft, attendance, previousStatus, context) {
    const evaluation = evaluateEligibility(draft, attendance.id);
    let remedialCase = draft.remedialCases.find((item) => item.sourceAttendanceId === attendance.id) || null;
    let assignment = remedialCase ? draft.remedialAssignments.find((item) => item.remedialCaseId === remedialCase.id) || null : null;
    let createdCase = false;
    let createdAssignment = false;

    if (evaluation.eligible) {
      if (!remedialCase) {
        remedialCase = {
          id: uid('remedial-case'), learnerId: attendance.learnerId, sourceAttendanceId: attendance.id,
          sourceSessionId: evaluation.session.id, sourceClassId: evaluation.cohort.id,
          sourceCourseVersionId: evaluation.courseVersion.id, sourceCourseId: evaluation.course?.id || null,
          sourceLessonTemplateId: evaluation.lesson.id, policySnapshot: clone(evaluation.policySnapshot),
          requiredModes: clone(evaluation.policySnapshot.requiredModes || ['ONLINE']), openedAt: context.now,
          openedBy: context.actorId, resolution: null, reconciliationHistory: [],
        };
        draft.remedialCases.push(remedialCase);
        createdCase = true;
      }
      if (remedialCase.resolution === 'NOT_REQUIRED') {
        remedialCase.resolution = null;
        remedialCase.resolutionAt = null;
      }
      if ((remedialCase.requiredModes || []).includes('ONLINE')) {
        if (!assignment) {
          assignment = createOnlineAssignment(draft, remedialCase, evaluation, context);
          createdAssignment = true;
        } else if (assignment.status === 'CANCELLED' && !draft.attempts.some((item) => item.assignmentId === assignment.id)) {
          assignment.status = 'ASSIGNED';
          assignment.cancelledAt = null;
          assignment.cancellationReason = null;
          assignment.accessStatus = 'ACTIVE';
        }
      }
    } else if (remedialCase) {
      const completedEvidence = assignment?.status === 'COMPLETED' || draft.makeUpBookings.some((item) => item.remedialCaseId === remedialCase.id && item.status === 'ATTENDED');
      if (!completedEvidence) {
        remedialCase.resolution = 'NOT_REQUIRED';
        remedialCase.resolutionAt = context.now;
        remedialCase.resolvedBy = context.actorId;
        if (assignment && !['COMPLETED', 'CANCELLED'].includes(assignment.status)) {
          assignment.status = 'CANCELLED';
          assignment.cancelledAt = context.now;
          assignment.cancellationReason = 'Điểm danh nguồn không còn đủ điều kiện.';
          assignment.accessStatus = 'REVOKED';
        }
        draft.makeUpBookings.filter((item) => item.remedialCaseId === remedialCase.id && ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status)).forEach((item) => {
          item.status = 'CANCELLED';
          item.cancelledAt = context.now;
          item.cancellationReason = 'Điểm danh nguồn đã được sửa.';
        });
      }
    }

    if (remedialCase && previousStatus !== attendance.status) {
      remedialCase.reconciliationHistory ||= [];
      remedialCase.reconciliationHistory.push({ fromStatus: previousStatus || null, toStatus: attendance.status, occurredAt: context.now, actorId: context.actorId });
    }
    return { remedialCase, assignment, createdCase, createdAssignment, evaluation };
  }

  root.YC.define('remedial', Object.freeze({ caseStatus, evaluateEligibility, rankMakeUpTargets, reconcileAttendance, sourceTrace }));
})(globalThis);

/* 06-selectors.js */
(function defineSelectors(root) {
  'use strict';

  const ROLE_HOME = Object.freeze({
    ADMIN: '/app/admin/dashboard',
    CENTER_MANAGER: '/app/manager/dashboard',
    ADMISSIONS: '/app/admissions/dashboard',
    ACADEMIC_MANAGER: '/app/academic/dashboard',
    STUDENT_SERVICE: '/app/service/dashboard',
    FINANCE: '/app/finance/dashboard',
    TEACHER: '/app/teacher/dashboard',
    TA: '/app/teacher/dashboard',
    STUDENT: '/app/student/dashboard',
    PARENT: '/app/parent/dashboard',
    VISITOR: '/tai-khoan',
  });

  function byId(state, collection, id) {
    return (state[collection] || []).find((item) => item.id === id) || null;
  }

  function roleHome(role) {
    return ROLE_HOME[role] || '/login';
  }

  function journey(state) {
    const learnerId = state.demo.canonicalLearnerId;
    const lead = state.leads.find((item) => item.learnerId === learnerId);
    const checks = [
      { status: 'LEAD', ownerRole: 'ADMISSIONS', done: lead && lead.status !== 'NEW' },
      { status: 'PLACEMENT', ownerRole: 'ADMISSIONS', done: state.placementResults.some((item) => item.learnerId === learnerId && item.status === 'RELEASED') },
      { status: 'PAID', ownerRole: 'FINANCE', done: state.payments.some((item) => item.learnerId === learnerId && item.status === 'PAID') },
      { status: 'ENROLLED', ownerRole: 'STUDENT_SERVICE', done: state.enrollments.some((item) => item.learnerId === learnerId && item.status === 'ACTIVE') },
      { status: 'TEACHER_ASSIGNED', ownerRole: 'ACADEMIC_MANAGER', done: state.teacherAssignments.some((item) => item.classId === 'class-6a' && item.status === 'ACTIVE') },
      { status: 'SESSION_DELIVERED', ownerRole: 'TEACHER', done: state.deliveryRecords.some((item) => item.sessionId === 'session-canonical') },
      { status: 'REMEDIAL_ASSIGNED', ownerRole: 'TEACHER', done: state.remedialAssignments.some((item) => item.learnerId === learnerId) },
      { status: 'REMEDIAL_COMPLETED', ownerRole: 'STUDENT', done: state.remedialAssignments.some((item) => item.learnerId === learnerId && item.status === 'COMPLETED') && state.homeworkAssignments.some((item) => item.learnerId === learnerId && item.status === 'ACCEPTED') },
      { status: 'MODERATED', ownerRole: 'ACADEMIC_MANAGER', done: state.moderationCases.some((item) => item.learnerId === learnerId && item.status === 'APPROVED') },
      { status: 'PROGRESS_PUBLISHED', ownerRole: 'ACADEMIC_MANAGER', done: state.progressReports.some((item) => item.learnerId === learnerId && item.status === 'PUBLISHED') },
      { status: 'PARENT_REVIEWED', ownerRole: 'PARENT', done: state.domainEvents.some((item) => item.type === 'PARENT_PROGRESS_VIEWED' && item.learnerId === learnerId) },
      { status: 'RENEWED', ownerRole: 'ADMISSIONS', done: state.renewals.some((item) => item.learnerId === learnerId && item.status === 'ACCEPTED') },
    ];
    const index = checks.findIndex((item) => !item.done);
    if (index === -1) return { status: 'RENEWED', index: checks.length, total: checks.length, ownerRole: 'ADMISSIONS', complete: true };
    return { status: checks[index].status, index, total: checks.length, ownerRole: checks[index].ownerRole, complete: false };
  }

  function metrics(state, role) {
    const activeEnrollments = state.enrollments.filter((item) => item.status === 'ACTIVE');
    const openCases = [...state.serviceCases, ...state.interventionCases].filter((item) => item.status === 'OPEN');
    const common = {
      activeLearners: activeEnrollments.length,
      openCases: openCases.length,
      branchCount: state.branches.filter((item) => item.status === 'ACTIVE').length,
    };
    if (role === 'ADMISSIONS') return { ...common, newLeads: state.leads.filter((item) => item.status === 'NEW').length, renewalDue: state.renewals.filter((item) => item.status === 'DUE').length };
    if (role === 'FINANCE') return { ...common, paidInvoices: state.invoices.filter((item) => item.status === 'PAID').length, mockRevenue: state.payments.filter((item) => item.status === 'PAID').reduce((sum, item) => sum + item.amount, 0) };
    if (role === 'TEACHER') return { ...common, gradingBacklog: state.gradingRecords.filter((item) => !['RELEASED', 'APPROVED'].includes(item.status)).length, upcomingSessions: state.sessions.filter((item) => ['CONFIRMED', 'PLANNED'].includes(item.status)).length };
    return common;
  }

  function teacherWorkload(state, teacherId) {
    const profile = state.teacherProfiles.find((item) => item.userId === teacherId);
    const teachingMinutes = profile
      ? state.teacherAssignments
        .filter((item) => item.teacherProfileId === profile.id && ['ACCEPTED', 'ACTIVE'].includes(item.status))
        .reduce((sum, item) => sum + Number(item.workloadMinutes || 0), 0)
      : 0;
    const preparationMinutes = Math.round(teachingMinutes * 0.2);
    const gradingMinutes = Math.round(teachingMinutes * 0.25);
    const administrationMinutes = Math.round(teachingMinutes * 0.15);
    return {
      teachingMinutes,
      preparationMinutes,
      gradingMinutes,
      administrationMinutes,
      totalMinutes: teachingMinutes + preparationMinutes + gradingMinutes + administrationMinutes,
      limitMinutes: state.settings.workloadLimitMinutes,
    };
  }

  function teacherEligibility(state, teacherId, classId, requestedWorkloadMinutes = 720) {
    const user = state.users.find((item) => item.id === teacherId);
    const profile = state.teacherProfiles.find((item) => item.userId === teacherId);
    const cohort = state.classes.find((item) => item.id === classId);
    const courseVersion = state.courseVersions.find((item) => item.id === cohort?.courseVersionId);
    const levelCode = state.levels.find((item) => item.id === state.courses.find((course) => course.id === courseVersion?.courseId)?.levelId)?.code || '';
    const frameworkLevel = levelCode.split('.')[0];
    const now = new Date(state.currentAt || state.seededAt).getTime();
    const qualificationValid = Boolean(profile && state.qualifications.some((item) => item.teacherProfileId === profile.id
      && item.status === 'VALID'
      && new Date(item.expiresAt).getTime() >= now));
    const workload = teacherWorkload(state, teacherId);
    const hardGates = [
      { key: 'ACTIVE_PROFILE', label: 'Hồ sơ đang hoạt động', passed: Boolean(user?.status === 'ACTIVE' && profile?.status === 'ACTIVE') },
      { key: 'QUALIFICATION', label: 'Qualification còn hiệu lực', passed: qualificationValid },
      { key: 'LEVEL', label: `Được phép dạy ${frameworkLevel || 'level yêu cầu'}`, passed: Boolean(profile?.levels.includes(frameworkLevel)) },
      { key: 'AGE_BAND', label: `Có kinh nghiệm ${cohort?.ageBand || 'age band'}`, passed: Boolean(profile?.ageBands.includes(cohort?.ageBand)) },
      { key: 'BRANCH', label: `Được phân scope ${cohort?.branchId || 'chi nhánh'}`, passed: Boolean(profile?.branchIds.includes(cohort?.branchId)) },
      { key: 'MODE', label: `Dạy được mode ${cohort?.mode || ''}`, passed: Boolean(profile?.modes.includes(cohort?.mode) || (cohort?.mode === 'HYBRID' && profile?.modes.includes('ONLINE') && profile?.modes.includes('OFFLINE'))) },
      { key: 'WORKLOAD', label: 'Không vượt giới hạn workload', passed: workload.totalMinutes + Math.round(requestedWorkloadMinutes * 1.6) <= workload.limitMinutes },
    ];
    const rankingSignals = [
      { key: 'BRANCH_CONTINUITY', label: 'Liên tục cùng chi nhánh', score: profile?.branchIds.includes(cohort?.branchId) ? 20 : 0 },
      { key: 'PROGRAM_EXPERIENCE', label: 'Kinh nghiệm cùng level', score: profile?.levels.includes(frameworkLevel) ? 20 : 0 },
      { key: 'LOAD_BALANCE', label: 'Dư địa workload', score: Math.max(0, Math.round((1 - workload.totalMinutes / workload.limitMinutes) * 20)) },
    ];
    return { teacherId, classId, eligible: hardGates.every((item) => item.passed), hardGates, rankingSignals, workload };
  }

  function overlaps(firstStart, firstEnd, secondStart, secondEnd) {
    return new Date(firstStart).getTime() < new Date(secondEnd).getTime()
      && new Date(firstEnd).getTime() > new Date(secondStart).getTime();
  }

  function scheduleConflicts(state, request) {
    const profile = state.teacherProfiles.find((item) => item.userId === request.teacherId);
    const conflicts = [];
    for (const session of state.sessions.filter((item) => !['CANCELLED', 'REVIEWED'].includes(item.status))) {
      if (!overlaps(request.startsAt, request.endsAt, session.startsAt, session.endsAt)) continue;
      if (session.room === request.room && state.classes.find((item) => item.id === session.classId)?.branchId === request.branchId) {
        conflicts.push({ type: 'ROOM', sessionId: session.id, label: `Phòng ${request.room} đã có lịch.` });
      }
      const assigned = profile && state.teacherAssignments.some((item) => item.teacherProfileId === profile.id
        && item.classId === session.classId
        && ['ACCEPTED', 'ACTIVE'].includes(item.status));
      if (assigned) conflicts.push({ type: 'TEACHER', sessionId: session.id, label: 'Giáo viên đã có buổi dạy trùng giờ.' });
    }
    return conflicts;
  }

  function sessionValidation(state, proposal) {
    const errors = [];
    const warnings = [];
    const cohort = byId(state, 'classes', proposal.classId);
    if (!cohort) return { valid: false, errors: [{ code: 'CLASS_NOT_FOUND', message: 'Không tìm thấy lớp.' }], warnings };
    const startsAt = new Date(proposal.startsAt).getTime();
    const endsAt = new Date(proposal.endsAt).getTime();
    if (!Number.isFinite(startsAt) || !Number.isFinite(endsAt) || endsAt <= startsAt) errors.push({ code: 'INVALID_SESSION_TIME', message: 'Thời gian kết thúc phải sau thời gian bắt đầu.' });
    const unitIds = state.units.filter((item) => item.courseVersionId === cohort.courseVersionId).map((item) => item.id);
    const lesson = byId(state, 'lessonTemplates', proposal.lessonTemplateId);
    if (!lesson || !unitIds.includes(lesson.unitId)) errors.push({ code: 'LESSON_COURSE_MISMATCH', message: 'Bài học không thuộc phiên bản khóa học của lớp.' });
    if (!proposal.room && (proposal.mode || cohort.mode) !== 'ONLINE') errors.push({ code: 'ROOM_REQUIRED', message: 'Buổi học trực tiếp cần có phòng.' });
    const excludedId = proposal.excludeSessionId || proposal.id || null;
    const candidates = state.sessions.filter((item) => item.id !== excludedId && !['CANCELLED', 'COMPLETED', 'REVIEWED'].includes(item.status)
      && Number.isFinite(startsAt) && overlaps(proposal.startsAt, proposal.endsAt, item.startsAt, item.endsAt));
    const targetAssignments = state.teacherAssignments.filter((item) => item.classId === cohort.id && ['ACCEPTED', 'ACTIVE'].includes(item.status)).map((item) => item.teacherProfileId);
    const targetLearners = state.enrollments.filter((item) => item.classId === cohort.id && item.status === 'ACTIVE').map((item) => item.learnerId);
    for (const session of candidates) {
      const otherClass = byId(state, 'classes', session.classId);
      if (session.room === proposal.room && otherClass?.branchId === cohort.branchId) errors.push({ code: 'ROOM_CONFLICT', sessionId: session.id, message: `Phòng ${proposal.room} đã có lịch.` });
      const otherAssignments = state.teacherAssignments.filter((item) => item.classId === session.classId && ['ACCEPTED', 'ACTIVE'].includes(item.status)).map((item) => item.teacherProfileId);
      if (targetAssignments.some((id) => otherAssignments.includes(id))) errors.push({ code: 'TEACHER_CONFLICT', sessionId: session.id, message: 'Giáo viên đã có buổi dạy trùng giờ.' });
      const otherLearners = state.enrollments.filter((item) => item.classId === session.classId && item.status === 'ACTIVE').map((item) => item.learnerId);
      const conflictedLearners = targetLearners.filter((id) => otherLearners.includes(id));
      if (conflictedLearners.length) errors.push({ code: 'LEARNER_CONFLICT', sessionId: session.id, learnerIds: conflictedLearners, message: `${conflictedLearners.length} học viên có lịch học trùng.` });
    }
    if (!targetAssignments.length) warnings.push({ code: 'TEACHER_NOT_ASSIGNED', message: 'Lớp chưa có giáo viên đang hiệu lực.' });
    return { valid: errors.length === 0, errors, warnings };
  }

  function sessionTrace(state, sessionId) {
    const session = byId(state, 'sessions', sessionId);
    if (!session) return null;
    const cohort = byId(state, 'classes', session.classId);
    const courseVersion = byId(state, 'courseVersions', cohort?.courseVersionId);
    const course = byId(state, 'courses', courseVersion?.courseId);
    const lesson = byId(state, 'lessonTemplates', session.lessonTemplateId);
    const unit = byId(state, 'units', lesson?.unitId);
    const branch = byId(state, 'branches', cohort?.branchId);
    const enrollments = state.enrollments.filter((item) => item.classId === cohort?.id && item.status === 'ACTIVE');
    const makeUpBookings = state.makeUpBookings.filter((item) => (item.targetSessionId || item.sessionId) === session.id && ['HELD', 'BOOKED', 'NOTIFIED', 'ATTENDED'].includes(item.status));
    return {
      session, cohort, courseVersion, course, lesson, unit, branch,
      teacherAssignments: state.teacherAssignments.filter((item) => item.classId === cohort?.id && ['ACCEPTED', 'ACTIVE'].includes(item.status)),
      learnerIds: [...new Set([...enrollments.map((item) => item.learnerId), ...makeUpBookings.map((item) => item.learnerId)])],
      enrollmentIds: enrollments.map((item) => item.id),
      makeUpBookingIds: makeUpBookings.map((item) => item.id),
    };
  }

  function sessionWorkbench(state, sessionId) {
    const session = byId(state, 'sessions', sessionId);
    if (!session) return null;
    const plan = state.lessonPlans.find((item) => item.sessionId === sessionId) || null;
    const learnerIds = state.enrollments.filter((item) => item.classId === session.classId && item.status === 'ACTIVE').map((item) => item.learnerId);
    return {
      session,
      plan,
      roster: state.learners.filter((item) => learnerIds.includes(item.id)),
      risks: state.interventionCases.filter((item) => learnerIds.includes(item.learnerId) && item.status === 'OPEN'),
      openHomework: state.homeworkAssignments.filter((item) => item.classId === session.classId && !['ACCEPTED', 'CLOSED'].includes(item.status)),
      delivery: state.deliveryRecords.find((item) => item.sessionId === sessionId) || null,
    };
  }

  function completionStatus(state, assignmentId) {
    const assignment = state.remedialAssignments.find((item) => item.id === assignmentId);
    if (!assignment) return null;
    const assessment = state.assessments.find((item) => item.id === assignment.assessmentId);
    const attempts = state.attempts.filter((item) => item.assignmentId === assignment.id && item.status === 'RELEASED');
    const highestScore = attempts.reduce((highest, item) => Math.max(highest, Number(item.score || 0)), 0);
    const videoPassed = Number(assignment.videoProgress || 0) >= Number(state.settings.minimumVideoProgress || 0);
    const scorePassed = highestScore >= Number(assessment?.passingScore || state.settings.defaultPassingScore);
    return { assignmentId, videoPassed, scorePassed, highestScore, completed: videoPassed && scorePassed };
  }

  function skillProfile(state, learnerId) {
    const labels = ['LISTENING', 'READING', 'SPOKEN_INTERACTION', 'SPOKEN_PRODUCTION', 'WRITING', 'LANGUAGE'];
    return labels.map((skill) => {
      const result = state.skillResults.filter((item) => item.learnerId === learnerId && item.skill === skill && item.status === 'RELEASED').at(-1);
      return { skill, score: result?.score ?? null, evidenceId: result?.id || null };
    });
  }

  function progressReportEvidence(state, learnerId) {
    const enrollment = state.enrollments.find((item) => item.learnerId === learnerId && item.status === 'ACTIVE');
    const classSessions = state.sessions.filter((item) => item.classId === enrollment?.classId);
    const attendance = state.attendanceRecords.filter((item) => item.learnerId === learnerId && classSessions.some((session) => session.id === item.sessionId));
    const present = attendance.filter((item) => ['PRESENT', 'LATE', 'ONLINE', 'MAKE_UP'].includes(item.status)).length;
    const homework = state.homeworkAssignments.filter((item) => item.learnerId === learnerId);
    const acceptedHomework = homework.filter((item) => item.status === 'ACCEPTED').length;
    return {
      enrollmentId: enrollment?.id || null,
      attendanceRate: attendance.length ? Math.round((present / attendance.length) * 100) : 100,
      homeworkCompletion: homework.length ? Math.round((acceptedHomework / homework.length) * 100) : 100,
      skillProfile: skillProfile(state, learnerId),
      interventionIds: state.interventionCases.filter((item) => item.learnerId === learnerId).map((item) => item.id),
      remedialIds: state.remedialAssignments.filter((item) => item.learnerId === learnerId).map((item) => item.id),
    };
  }

  function riskSignals(state) {
    return state.learners.flatMap((learner) => {
      const records = state.attendanceRecords.filter((item) => item.learnerId === learner.id);
      const recentAbsences = records.filter((item) => item.status === 'ABSENT').length;
      const overdueHomework = state.homeworkAssignments.filter((item) => item.learnerId === learner.id && !['ACCEPTED', 'CLOSED'].includes(item.status) && item.dueAt && new Date(item.dueAt) < new Date(state.currentAt || state.seededAt)).length;
      const signals = [];
      if (recentAbsences >= 2) signals.push({ learnerId: learner.id, type: 'ABSENT_TWO_SESSIONS', severity: 'HIGH', ownerRole: 'STUDENT_SERVICE' });
      if (overdueHomework > 0) signals.push({ learnerId: learner.id, type: 'HOMEWORK_OVERDUE', severity: 'MEDIUM', ownerRole: 'TEACHER' });
      return signals;
    });
  }

  function coursePublishValidation(state, courseVersionId) {
    const version = byId(state, 'courseVersions', courseVersionId);
    const errors = [];
    const warnings = [];
    if (!version) return { valid: false, errors: [{ code: 'COURSE_VERSION_NOT_FOUND', message: 'Không tìm thấy phiên bản khóa học.' }], warnings };
    const course = byId(state, 'courses', version.courseId);
    if (!course) errors.push({ code: 'COURSE_REQUIRED', message: 'Phiên bản chưa gắn với khóa học.' });
    else {
      if (!byId(state, 'programs', course.programId)) errors.push({ code: 'PROGRAM_REQUIRED', message: 'Khóa học chưa có chương trình.' });
      if (!byId(state, 'levels', course.levelId)) errors.push({ code: 'LEVEL_REQUIRED', message: 'Khóa học chưa có cấp độ.' });
      if (!String(course.description || '').trim()) warnings.push({ code: 'DESCRIPTION_RECOMMENDED', message: 'Nên bổ sung mô tả khóa học.' });
    }
    const units = state.units.filter((item) => item.courseVersionId === version.id);
    if (!units.length) errors.push({ code: 'UNIT_REQUIRED', message: 'Cần ít nhất một học phần.' });
    const unitIds = units.map((item) => item.id);
    const lessons = state.lessonTemplates.filter((item) => unitIds.includes(item.unitId));
    if (units.length && !lessons.length) errors.push({ code: 'LESSON_REQUIRED', message: 'Cần ít nhất một bài học.' });
    for (const lesson of lessons) {
      if (!Array.isArray(lesson.objectives) || !lesson.objectives.filter(Boolean).length) errors.push({ code: 'LESSON_OBJECTIVE_REQUIRED', lessonId: lesson.id, message: `${lesson.title}: thiếu mục tiêu.` });
      if (!Number(lesson.durationMinutes) || Number(lesson.durationMinutes) < 1) errors.push({ code: 'LESSON_DURATION_REQUIRED', lessonId: lesson.id, message: `${lesson.title}: thiếu thời lượng.` });
      if (!state.learningItems.some((item) => item.lessonTemplateId === lesson.id && item.status !== 'ARCHIVED')) warnings.push({ code: 'LEARNING_ITEM_RECOMMENDED', lessonId: lesson.id, message: `${lesson.title}: chưa có học liệu.` });
    }
    const lessonIds = lessons.map((item) => item.id);
    const assessments = state.assessments.filter((item) => item.courseVersionId === version.id || lessonIds.includes(item.lessonTemplateId));
    if (!assessments.length) errors.push({ code: 'ASSESSMENT_REQUIRED', message: 'Cần ít nhất một bài đánh giá.' });
    for (const assessment of assessments) {
      const invalidQuestion = (assessment.questionIds || []).find((id) => !state.questions.some((item) => item.id === id));
      if (invalidQuestion) errors.push({ code: 'ASSESSMENT_QUESTION_INVALID', assessmentId: assessment.id, message: `${assessment.title}: câu hỏi không tồn tại.` });
    }
    if (!version.completionRule) errors.push({ code: 'COMPLETION_RULE_REQUIRED', message: 'Thiếu quy tắc hoàn thành.' });
    if (!version.remedialPolicy) errors.push({ code: 'REMEDIAL_POLICY_REQUIRED', message: 'Thiếu chính sách học bù.' });
    if (!Number(version.totalHours)) errors.push({ code: 'TOTAL_HOURS_REQUIRED', message: 'Thiếu tổng số giờ học.' });
    return { valid: errors.length === 0, errors, warnings };
  }

  function classCapacity(state, classId) {
    const cohort = byId(state, 'classes', classId);
    if (!cohort) return null;
    const activeEnrollments = state.enrollments.filter((item) => item.classId === classId && item.status === 'ACTIVE').length;
    const sessionIds = state.sessions.filter((item) => item.classId === classId).map((item) => item.id);
    const makeUpReservations = state.makeUpBookings.filter((item) => ['HELD', 'BOOKED', 'NOTIFIED'].includes(item.status)
      && sessionIds.includes(item.targetSessionId || item.sessionId)).length;
    const capacity = Number(cohort.capacity || 0);
    const used = activeEnrollments + makeUpReservations;
    return { classId, capacity, activeEnrollments, makeUpReservations, used, remaining: Math.max(0, capacity - used), full: used >= capacity };
  }

  function classReadiness(state, classId) {
    const cohort = byId(state, 'classes', classId);
    if (!cohort) return { ready: false, errors: [{ code: 'CLASS_NOT_FOUND', message: 'Không tìm thấy lớp.' }], warnings: [] };
    const errors = [];
    const warnings = [];
    const version = byId(state, 'courseVersions', cohort.courseVersionId);
    if (!version || version.status !== 'PUBLISHED' || !version.immutable) errors.push({ code: 'COURSE_VERSION_NOT_PUBLISHED', message: 'Phiên bản khóa học chưa được công bố.' });
    const rules = state.timetableRules.filter((item) => item.classId === cohort.id && item.status !== 'INACTIVE');
    if (!rules.length || rules.some((item) => !Array.isArray(item.recurrence) || !item.recurrence.length || !Number(item.durationMinutes))) errors.push({ code: 'TIMETABLE_REQUIRED', message: 'Lớp chưa có lịch định kỳ hợp lệ.' });
    if (!cohort.room && cohort.mode !== 'ONLINE') errors.push({ code: 'ROOM_REQUIRED', message: 'Lớp trực tiếp cần có phòng.' });
    if (!cohort.meetingUrl && cohort.mode === 'ONLINE') errors.push({ code: 'MEETING_URL_REQUIRED', message: 'Lớp trực tuyến cần có liên kết học.' });
    const assignment = state.teacherAssignments.find((item) => item.classId === cohort.id && item.role === 'PRIMARY' && ['ACCEPTED', 'ACTIVE'].includes(item.status));
    if (!assignment) errors.push({ code: 'PRIMARY_TEACHER_REQUIRED', message: 'Lớp chưa có giáo viên chính đang hiệu lực.' });
    if (!state.sessions.some((item) => item.classId === cohort.id && item.status !== 'CANCELLED')) errors.push({ code: 'SESSION_REQUIRED', message: 'Lớp chưa có buổi học.' });
    const capacity = classCapacity(state, cohort.id);
    if (capacity.used < Number(cohort.minCapacity || 1)) errors.push({ code: 'MINIMUM_CAPACITY', message: `Cần tối thiểu ${cohort.minCapacity || 1} học viên; hiện có ${capacity.used}.` });
    if (capacity.remaining <= 1) warnings.push({ code: 'CAPACITY_LOW', message: 'Lớp gần đạt sức chứa tối đa.' });
    return { classId, ready: errors.length === 0, errors, warnings, capacity, assignmentId: assignment?.id || null };
  }

  root.YC.define('selectors', Object.freeze({ byId, classCapacity, classReadiness, completionStatus, coursePublishValidation, journey, metrics, progressReportEvidence, riskSignals, roleHome, scheduleConflicts, sessionTrace, sessionValidation, sessionWorkbench, skillProfile, teacherEligibility, teacherWorkload }));
})(globalThis);

